/* GENERATED by tools/build-explain-db.py — DO NOT EDIT BY HAND.
   Sources: glossary.html (354 terms) + tools/explain-extra.json (140 curated). See standarization/EXPLAIN_ENGINE_STANDARD.md. */
window.RZ_EXPLAIN_DB = {"version":"1.0.0","counts":{"glossary":354,"curated":140,"total":481},"entries":{"2n":{"t":"2N Redundancy","d":"A fully redundant configuration where the entire infrastructure is duplicated. Two independent power paths, each capable of supporting 100% of the load. If one entire path fails, the other sustains operations. Required for Tier IV certification. More expensive but eliminates single points of failure.","link":"glossary.html#term-2n","aliases":["2N Redundancy"]},"a2l":{"t":"A2L (Mildly Flammable Refrigerants)","d":"The ASHRAE 34 class for refrigerants with low toxicity and mild flammability (low burning velocity, hard to ignite) — the class most of the industry is migrating to, including R-32, R-454B, and the HFO R-1234ze. A2L systems require leak detection, ventilation interlocks, and charge-limit compliance per ASHRAE 15/IEC 60335, modeled as a ~3% equipment cost premium. The trade is regulatory durability: A2L fluids clear the AIM Act and EU F-Gas GWP thresholds that are eliminating A1 legacy HFCs like R-410A.","rel":["ashrae-34-safety-class","r1234ze","refrigerant","gwp"],"aliases":["A2L","mildly flammable"]},"access-floor":{"t":"Access Floor (Raised Access Floor) ((Raised Access Floor))","d":"A modular elevated floor system creating an underfloor plenum for routing power cables, data cabling, and conditioned air to server racks. Standard tile sizes are 600mm x 600mm with typical heights of 300-1000mm.","link":"glossary.html#term-access-floor","aliases":["(Raised Access Floor)","Access Floor (Raised Access Floor)"]},"active-power":{"t":"Active Power (Real Power, kW) ((Real Power, kW))","d":"The actual power consumed by IT and facility equipment, measured in kilowatts (kW). Unlike apparent power (kVA), active power represents the energy that performs useful work. Active power = Apparent Power x Power Factor.","link":"glossary.html#term-active-power","aliases":["(Real Power, kW)","Active Power (Real Power, kW)"]},"adiabatic-cooling":{"t":"Adiabatic Cooling","d":"A cooling method that pre-cools outdoor air by evaporating water before it passes through a heat exchanger. Adiabatic coolers extend the operating hours of free cooling in warm climates while using significantly less water than cooling towers. Common in European and Australian data centers.","link":"glossary.html#term-adiabatic-cooling","aliases":["Adiabatic Cooling"]},"ahu":{"t":"AHU (Air Handling Unit) ((Air Handling Unit))","d":"A large HVAC unit that conditions and circulates air through ductwork. In data centers, AHUs supply chilled air to the data hall or support economizer cooling by mixing outside air with return air. Typical capacities range from 50 to 500+ kW.","link":"glossary.html#term-ahu","aliases":["(Air Handling Unit)","AHU (Air Handling Unit)"]},"ai-cooling":{"t":"AI Cooling","d":"Specialized cooling solutions designed for artificial intelligence and machine learning workloads. AI servers with multiple GPUs (4-8 per node) generate 5-10+ kW per server, requiring direct liquid cooling, rear-door heat exchangers, or immersion cooling to manage thermal loads that far exceed traditional air cooling capacity.","link":"glossary.html#term-ai-cooling","aliases":["AI Cooling"]},"aiops":{"t":"AIOps (AI for IT Operations) ((AI for IT Operations))","d":"A category of platforms that apply machine learning to automate incident detection, anomaly correlation, and remediation across IT and data center operations. AIOps tools reduce mean-time-to-resolution (MTTR) by up to 50% and shift L1/L2 staff to higher-value work. The market grew to $16-18 billion in 2024 with 20%+ annual CAGR, and 73% of Uptime Institute respondents expect AI to reduce facility staffing within five years.","link":"glossary.html#term-aiops","aliases":["(AI for IT Operations)","AIOps (AI for IT Operations)"]},"air-cooling":{"t":"Air Cooling","d":"The traditional method of removing heat from IT equipment using chilled air delivered through raised floors or overhead ducts. Cost-effective for densities below 10 kW per rack but becomes less efficient at higher densities compared to liquid cooling.","link":"glossary.html#term-air-cooling","aliases":["Air Cooling"]},"airflow-management":{"t":"Airflow Management","d":"Strategies to optimize the movement of conditioned air through a data center, including hot/cold aisle containment, blanking panels, grommets, and brush strips. Proper airflow management can reduce cooling energy by 20-40%.","link":"glossary.html#term-airflow-management","aliases":["Airflow Management"]},"aisle-containment":{"t":"Aisle Containment","d":"Physical enclosures (doors, roof panels, end caps) that separate hot and cold air streams in a server room. Cold aisle containment (CAC) encloses the cold supply side; hot aisle containment (HAC) encloses the hot exhaust side. Both approaches improve cooling efficiency by preventing air mixing.","link":"glossary.html#term-aisle-containment","aliases":["Aisle Containment"]},"alarm-management":{"t":"Alarm Management","d":"The systematic process of configuring, prioritizing, and responding to alerts from BMS, EPMS, and monitoring systems. Effective alarm management reduces alarm fatigue by categorizing alerts into critical, major, minor, and informational tiers with defined response procedures for each.","link":"glossary.html#term-alarm-management","aliases":["Alarm Management"]},"alternator":{"t":"Alternator","d":"The component of a generator that converts mechanical rotation into AC electrical power via electromagnetic induction. Alternator ratings define generator output capacity. Brushless alternators with permanent magnet excitation are standard in data center generator sets for reliability.","link":"glossary.html#term-alternator","aliases":["Alternator"]},"ambient-temperature":{"t":"Ambient Temperature","d":"The temperature of the outside air surrounding a facility. ASHRAE recommends data center inlet temperatures of 18-27 C (A1 class). Ambient temperature directly affects free cooling availability and chiller efficiency.","link":"glossary.html#term-ambient-temperature","aliases":["Ambient Temperature"]},"ampere":{"t":"Ampere (Amp, A) ((Amp, A))","d":"The SI unit of electrical current. In data centers, amperage ratings determine conductor sizing, breaker capacity, and PDU specifications. A standard 20A circuit at 208V delivers approximately 3.3 kW of power.","link":"glossary.html#term-ampere","aliases":["(Amp, A)","Ampere (Amp, A)"]},"annual-energy-cost":{"t":"Annual Energy Cost","d":"Estimated yearly electricity spend: IT Load x PUE x 8,760 hours x the electricity rate. It is an OPEX item, not part of CAPEX, and over a 10–15 year horizon it typically exceeds the original build cost — which is why a 0.1 PUE improvement or an On-Site Renewable hedge moves TCO more than most construction savings. Feeds directly into NOI and therefore DSCR in the financing model.","f":"Annual Energy = IT Load (kW) x PUE x 8,760 h x $/kWh","u":"USD/yr","rel":["pue","opex","tco","onsite-renewable","noi"],"aliases":["Annual Energy","Annual Energy Cost","annual electricity cost"]},"annualized-failure-rate":{"t":"Annualized Failure Rate (AFR) ((AFR))","d":"The probability that a device or component will fail during a full year of use. AFR = 1 - e^(-8760/MTBF). Hard drives typically have an AFR of 0.5-3%, while enterprise SSDs range from 0.1-0.5%.","link":"glossary.html#term-annualized-failure-rate","aliases":["(AFR)","Annualized Failure Rate (AFR)"]},"apparent-power":{"t":"Apparent Power (kVA) ((kVA))","d":"The product of voltage and current in an AC circuit, measured in kilovolt-amperes. Apparent power includes both real power (kW) that does useful work and reactive power (kVAR) that sustains electromagnetic fields. UPS and transformer ratings are specified in kVA.","link":"glossary.html#term-apparent-power","aliases":["(kVA)","Apparent Power (kVA)"]},"apprenticeship":{"t":"Apprenticeship (Data Center)","d":"A US Department of Labor-registered training pathway combining paid on-the-job hours with classroom instruction, typically 1-4 years to journeyman status. IBEW Local 26 in Northern Virginia doubled to 14,700+ members since 2018 partly through DC-aligned electrical apprenticeships. OpenAI committed $1.5M to NABTU in 2026 to expand DC trades pipelines, and DOL invested $84M in apprenticeship expansion in 2024.","link":"glossary.html#term-apprenticeship","aliases":["Apprenticeship (Data Center)"]},"approach-temperature":{"t":"Approach Temperature (ATD) ((ATD))","d":"The closest temperature difference a CDU heat exchanger achieves between the secondary (chip-side) supply and the facility (primary) supply — the residual pinch. Lower approach = a more effective exchanger. Typical L2L CDUs run 3–5 °C (OCP Project Deschutes targets 3 °C). From heat-exchanger effectiveness: approach = (1 − &epsilon;) &times; (hot-in − cold-in).","link":"glossary.html#term-approach-temperature","aliases":["(ATD)","Approach Temperature (ATD)"]},"arc-flash":{"t":"Arc Flash","d":"A dangerous release of energy caused by an electrical fault between conductors or between a conductor and ground. Arc flash incidents can generate temperatures exceeding 19,000 C. NFPA 70E requires arc flash hazard analysis and PPE categories for personnel working near energized equipment.","link":"glossary.html#term-arc-flash","aliases":["Arc Flash"]},"ashrae":{"t":"ASHRAE (American Society of Heating, Refrigerating and Air-Conditioning Engineers) ((American Society of Heating, Refrigerating and Air-Conditioning Engineers))","d":"The organization that publishes thermal guidelines for data center environments through Technical Committee 9.9. ASHRAE defines recommended and allowable temperature/humidity envelopes (classes A1 through A4) for IT equipment.","link":"glossary.html#term-ashrae","aliases":["(American Society of Heating, Refrigerating and Air-Conditioning Engineers)","ASHRAE (American Society of Heating, Refrigerating and Air-Conditioning Engineers)"]},"ashrae-34-safety-class":{"t":"ASHRAE 34 Safety Class","d":"The standard two-character refrigerant safety code: the letter grades toxicity (A = lower, B = higher) and the number grades flammability (1 = none, 2L = mildly flammable with low burning velocity, 2 = flammable, 3 = highly flammable). A1 fluids (R-134a, R-410A, R-1233zd) need no special mitigation; A2L fluids add ~3% equipment cost for leak detection and ventilation; B2L (ammonia) and A3 (propane) require machine-room isolation or strict charge limits, adding 6–7%. The class therefore converts directly into mitigation CAPEX in the refrigerant impact model.","table":[["Class","Meaning"],["A1","Non-flammable, lower toxicity"],["A2L","Mildly flammable"],["B2L","Toxic, mildly flammable"],["A3","Highly flammable"]],"s":"ASHRAE Standard 34","rel":["a2l","b2l","refrigerant","r290-propane"],"aliases":["ASHRAE 34","safety class","ASHRAE 34 safety class"]},"asset-management":{"t":"Asset Management","d":"Tracking and managing all physical and virtual assets in a data center throughout their lifecycle. Includes hardware inventory (serial numbers, locations, warranties), software licenses, cable management, and decommissioning records. DCIM tools automate asset tracking with barcode or RFID scanning.","link":"glossary.html#term-asset-management","aliases":["Asset Management"]},"ats":{"t":"ATS (Automatic Transfer Switch) ((Automatic Transfer Switch))","d":"A device that automatically transfers electrical load from a primary power source to a backup source (typically a generator) when it detects a failure. Transfer time is typically 10-20 seconds for open-transition and under 100ms for closed-transition ATS.","link":"glossary.html#term-ats","aliases":["(Automatic Transfer Switch)","ATS (Automatic Transfer Switch)"]},"availability":{"t":"Availability","d":"The percentage of time a system or facility is operational. Calculated as Uptime / (Uptime + Downtime) x 100%. Tier III targets 99.982% (1.6 hours downtime/year) and Tier IV targets 99.995% (0.4 hours/year).","link":"glossary.html#term-availability","aliases":["Availability"]},"b2l":{"t":"B2L (Toxic, Mildly Flammable)","d":"The ASHRAE 34 class combining higher toxicity with mild flammability — in practice this means R-717 Ammonia, the zero-GWP industrial refrigerant. B2L systems demand dedicated machine-room isolation, gas detection, emergency ventilation, and occupied-space charge limits per IIAR and EN 378, modeled as a ~7% capex premium. The payoff is the best cycle efficiency in the database (COP index 1.04) with literally zero direct Global Warming Potential.","rel":["ashrae-34-safety-class","r717-ammonia","gwp"],"aliases":["B2L"]},"backup-power":{"t":"Backup Power","d":"Secondary power systems (UPS, generators, fuel cells) that maintain operation during utility outages. A typical data center backup chain: utility fails, UPS batteries bridge 5-15 minutes, then diesel generators run indefinitely with fuel supply.","link":"glossary.html#term-backup-power","aliases":["Backup Power"]},"bandwidth":{"t":"Bandwidth","d":"The maximum data transfer rate of a network connection, measured in bits per second (bps). Modern data centers commonly use 25/100/400 GbE within the facility and multiple 100G+ uplinks to external networks.","link":"glossary.html#term-bandwidth","aliases":["Bandwidth"]},"battery":{"t":"Battery (UPS Battery) ((UPS Battery))","d":"Energy storage devices within UPS systems that provide immediate backup power during outages. VRLA (Valve-Regulated Lead-Acid) batteries last 3-5 years; lithium-ion alternatives offer 8-15 year life with smaller footprint and faster recharge.","link":"glossary.html#term-battery","aliases":["(UPS Battery)","Battery (UPS Battery)"]},"battery-monitoring":{"t":"Battery Monitoring System","d":"A system that continuously measures individual battery cell voltage, internal resistance, temperature, and current to predict failures before they occur. Proactive battery monitoring reduces the risk of UPS backup failure, which is the leading cause of data center outages.","link":"glossary.html#term-battery-monitoring","aliases":["Battery Monitoring System"]},"bcms":{"t":"BCMS (Business Continuity Management System) ((Business Continuity Management System))","d":"A management framework (ISO 22301) for identifying potential threats and building organizational resilience. In data centers, BCMS covers disaster recovery plans, failover procedures, and regular continuity testing.","link":"glossary.html#term-bcms","aliases":["(Business Continuity Management System)","BCMS (Business Continuity Management System)"]},"benchmark-percentile":{"t":"Benchmark Percentile","d":"Where a metric sits relative to a reference population — for example, a Cost per kW at the 30th percentile of the City / Market dataset means 70% of comparable builds cost more. Percentile framing is how the DCMOC Benchmarks module scores countries across cost, energy, connectivity, talent, and risk categories, converting raw numbers into rankings a board can act on. Beware population definition: a 'cheap' P20 build against Tier IV comparables may be a P80 build against Tier II ones.","rel":["cost-per-kw","city-market","tab-benchmark"],"aliases":["Benchmark Percentile","percentile ranking"]},"bicsi-rcdd":{"t":"BICSI RCDD (Registered Communications Distribution Designer) ((Registered Communications Distribution Designer))","d":"A BICSI-issued professional credential for telecommunications and data center cabling design. RCDD holders demonstrate mastery of TIA-942 zone topology, structured cabling pathways, fiber/copper specifications, and grounding/bonding. The credential is widely required for senior cabling design roles in DC construction. Exam fee is approximately $400-$600 with continuing education for renewal.","link":"glossary.html#term-bicsi-rcdd","aliases":["(Registered Communications Distribution Designer)","BICSI RCDD (Registered Communications Distribution Designer)"]},"biometric-access":{"t":"Biometric Access Control","d":"Physical security systems using unique biological characteristics (fingerprint, iris scan, facial recognition) to authenticate personnel entering data center secure areas. Multi-factor authentication combining biometrics with badge and PIN is best practice for Tier III/IV facilities.","link":"glossary.html#term-biometric-access","aliases":["Biometric Access Control"]},"blade-server":{"t":"Blade Server","d":"A modular server design where multiple thin compute modules (blades) share a common chassis with power supplies, cooling fans, and network switches. Blade servers offer higher density than rack-mounted servers but are being superseded by hyperconverged architectures.","link":"glossary.html#term-blade-server","aliases":["Blade Server"]},"blanking-panel":{"t":"Blanking Panel","d":"A plastic or metal panel installed in unused rack unit spaces to prevent hot exhaust air from recirculating to the cold aisle. Blanking panels are the single most cost-effective airflow management measure, reducing bypass air by up to 60%.","link":"glossary.html#term-blanking-panel","aliases":["Blanking Panel"]},"bms":{"t":"BMS (Building Management System) ((Building Management System))","d":"A computer-based control system that monitors and manages a building's mechanical, electrical, and plumbing systems. In data centers, BMS integrates HVAC, fire suppression, access control, and environmental sensors via protocols like BACnet or Modbus.","link":"glossary.html#term-bms","aliases":["(Building Management System)","BMS (Building Management System)"]},"bonding":{"t":"Bonding (Electrical Bonding) ((Electrical Bonding))","d":"Connecting all metallic components (racks, cable trays, raised floor, pipes) to a common grounding system to ensure equal electrical potential and prevent shock hazards. Bonding eliminates voltage differences that could damage sensitive IT equipment or endanger personnel.","link":"glossary.html#term-bonding","aliases":["(Electrical Bonding)","Bonding (Electrical Bonding)"]},"branch-circuit":{"t":"Branch Circuit","d":"The final circuit between the last overcurrent protection device (breaker) and the connected load. Data center branch circuits typically operate at 120V, 208V, or 230V with 20A-30A ratings for server power feeds.","link":"glossary.html#term-branch-circuit","aliases":["Branch Circuit"]},"breaker":{"t":"Breaker (Circuit Breaker) ((Circuit Breaker))","d":"An automatically operated electrical switch that protects circuits from overcurrent damage. Breaker types used in data centers include MCB (miniature, branch circuits), MCCB (molded case, sub-distribution), and ACB (air circuit, main switchboards). Breakers must be selectively coordinated to isolate faults without cascading trips.","link":"glossary.html#term-breaker","aliases":["(Circuit Breaker)","Breaker (Circuit Breaker)"]},"brownfield":{"t":"Brownfield","d":"An existing building or site being repurposed or retrofitted as a data center. Brownfield conversions are faster than greenfield (new construction) but face constraints from existing structural capacity, electrical infrastructure, and cooling limitations. Common conversions include warehouses and office buildings.","link":"glossary.html#term-brownfield","aliases":[]},"btu":{"t":"BTU (British Thermal Unit) ((British Thermal Unit))","d":"A unit of heat energy. 1 BTU is the energy required to raise 1 pound of water by 1 degree Fahrenheit. Data center cooling is often rated in BTU/hr. 1 kW of IT load produces approximately 3,412 BTU/hr of heat.","link":"glossary.html#term-btu","aliases":["(British Thermal Unit)","BTU (British Thermal Unit)"]},"building-automation":{"t":"Building Automation","d":"Integrated systems that automatically control facility operations including HVAC, lighting, fire safety, and security. Modern data centers use building automation to optimize energy use, maintain environmental conditions, and alert operators to anomalies.","link":"glossary.html#term-building-automation","aliases":["Building Automation"]},"building-type":{"t":"Building Type","d":"The type of structure that houses the data hall, which swings construction cost by a factor of two. Warehouse conversions are cheapest (0.70x) because the shell exists; modular/prefab runs 0.85x with faster schedules; purpose-built is the 1.00x baseline optimized for load paths, floor loading, and cooling; high-rise multi-story is costliest (1.40x) due to structural steel, vertical riser distribution, and craneage. The choice also shifts build time (modular ~0.6x, high-rise ~1.4x of baseline schedule), which interacts with Year Escalation.","table":[["Type","Cost Factor"],["Warehouse Conversion","0.70x (lowest)"],["Modular / Prefab","0.85x"],["Purpose-Built","1.00x (baseline)"],["High-Rise Multi-Story","1.40x (highest)"]],"rel":["total-capex","year-escalation","site-condition"],"aliases":["Building Type","building type"]},"bulk-power":{"t":"Bulk Power","d":"Large-format power equipment serving the entire facility, including main transformers, generators, and UPS systems. Bulk power design determines the fundamental capacity and redundancy level of the data center. Typical bulk power configurations include N+1, 2N, and distributed redundant architectures.","link":"glossary.html#term-bulk-power","aliases":["Bulk Power"]},"bus-duct":{"t":"Bus Duct (Busway) ((Busway))","d":"A prefabricated electrical distribution system using enclosed copper or aluminum bus bars instead of traditional cable and conduit. Bus duct enables flexible tap-off connections for PDUs and is common in data center overhead power distribution. Rated from 800A to 5000A.","link":"glossary.html#term-bus-duct","aliases":["(Busway)","Bus Duct (Busway)"]},"busbar":{"t":"Busbar","d":"A metallic strip or bar (copper or aluminum) used for local high-current power distribution inside switchboards, panelboards, and busway systems. Busbars reduce wiring complexity and provide efficient power distribution paths. Ratings range from 100A in small panels to 6,300A in main switchboards.","link":"glossary.html#term-busbar","aliases":["Busbar"]},"bypass":{"t":"Bypass","d":"An alternate electrical path that allows maintenance on UPS or switchgear without interrupting power to the load. Static bypass (automatic, millisecond switching) and maintenance bypass (manual, wrench-operated) are standard features in critical power systems.","link":"glossary.html#term-bypass","aliases":["Bypass"]},"cable-tray":{"t":"Cable Tray","d":"A structural system of metal troughs or ladders used to route and support power and data cables throughout a data center. Ladder trays are preferred for power cables (better heat dissipation), while mesh trays suit fiber and copper data cabling.","link":"glossary.html#term-cable-tray","aliases":["Cable Tray"]},"cabling-type":{"t":"Structured Cabling System","d":"Backbone and horizontal network cabling. Cat6A copper (~$600/rack) suits standard enterprise; hybrid fiber backbone + Cat6A drops (~$1,200/rack) is the mainstream standard; all-fiber OM4/OS2 (~$2,000/rack) is the premium choice for high-density and AI facilities where 400G+ east-west fabrics dominate. AI clusters can spend more on optics and cabling per rack than on power distribution, so density strategy (Rack Density) drives this line item.","table":[["Type","Cost per Rack"],["Cat6A Copper","~$600/rack"],["Hybrid (Fiber + Cat6A)","~$1,200/rack"],["All-Fiber (OM4/OS2)","~$2,000/rack"]],"rel":["fiber-entry","rack-density"],"aliases":["Structured Cabling","Structured Cabling System","Cat6A","OM4"]},"cap-rate":{"t":"Cap Rate (Capitalization Rate)","d":"NOI divided by asset value — the real-estate market's shorthand for pricing income streams, and the inverse cousin of the EV/EBITDA multiple. Stabilized data centers have traded at cap rates in the 5–7% range in recent cycles, tighter (lower) for long-leased hyperscale assets and wider for retail colocation with shorter contracts. Cap-rate movement between entry and exit is a silent but powerful driver of Equity IRR: 100 bps of expansion can erase years of NOI growth.","f":"Cap Rate = NOI / Asset Value","u":"%","rel":["noi","exit-ev-ebitda-multiple","terminal-value","equity-irr"],"aliases":["Cap Rate","cap rate","capitalization rate"]},"capacity-auction":{"t":"Capacity Auction (PJM RPM) ((PJM RPM))","d":"PJM's competitive market mechanism that procures generation and demand-response resources three years forward to ensure adequate reserve margin. Run as the Reliability Pricing Model (RPM) Base Residual Auction. Recent auctions have cleared at historically high prices ($269.92/MW-day for 2025/26 delivery year) as load growth from data centers exceeded retiring generation, signaling capacity scarcity.","link":"glossary.html#term-capacity-auction","aliases":["(PJM RPM)","Capacity Auction (PJM RPM)"]},"capacity-planning":{"t":"Capacity Planning","d":"The process of forecasting and managing data center resources (power, cooling, space, network) to meet current and future demand. Effective capacity planning prevents both stranded assets (over-provisioning) and service disruptions (under-provisioning).","link":"glossary.html#term-capacity-planning","aliases":["Capacity Planning"]},"capex":{"t":"CAPEX (Capital Expenditure)","d":"One-time investment in long-lived assets: land, building, electrical and mechanical plant, fit-out, and commissioning. CAPEX is capitalized on the balance sheet and recovered through Depreciation over asset lives (5–39 years by category), unlike OPEX which is expensed as incurred. The CAPEX/OPEX split shapes taxes, TCO, and financing — lenders fund CAPEX against future NOI, which is the whole project-finance construct.","u":"USD","rel":["total-capex","opex","depreciation","tco"],"aliases":["CAPEX","Capital Expenditure","capital expenditure"]},"cash-flow-waterfall":{"t":"Cash Flow Waterfall","d":"The strict priority ladder by which each period's cash is distributed: operating costs first, then senior debt service (interest, then scheduled principal), then reserves and covenants, and only then equity distributions — often further split by sponsor/investor promote tiers. The waterfall is why DSCR matters: debt eats before equity does, so thin coverage years mean zero distributions even when EBITDA is positive. The Investment module's amortization schedule and coverage charts trace this ladder year by year.","rel":["dscr","debt-ratio-leverage","equity-irr","noi"],"aliases":["Cash Flow Waterfall","cash flow waterfall","distribution waterfall"]},"cdctp":{"t":"CDCTP (Certified Data Center Technician Professional) ((Certified Data Center Technician Professional))","d":"An entry- to mid-level certification for data center operations technicians covering critical facility systems, electrical distribution, cooling, and incident response. CDCTP is one of several recognized credentials (alongside DCCA, BICSI DCDC, and Uptime ATD) that 7x24 Exchange/MCGA recommends as a substitute for the \"5 years experience\" hiring barrier that perpetuates the shortage.","link":"glossary.html#term-cdctp","aliases":["(Certified Data Center Technician Professional)","CDCTP (Certified Data Center Technician Professional)"]},"cdu":{"t":"CDU (Coolant Distribution Unit) ((Coolant Distribution Unit))","d":"A device that manages the flow and temperature of coolant in liquid cooling systems. CDUs transfer heat from the server-side coolant loop to the facility water loop via a heat exchanger, maintaining precise temperature control for direct-to-chip or immersion cooling. Compare in-row vs in-rack CDUs &rarr;","link":"glossary.html#term-cdu","aliases":["(Coolant Distribution Unit)","CDU (Coolant Distribution Unit)"]},"cfm":{"t":"CFM (Cubic Feet per Minute) ((Cubic Feet per Minute))","d":"A unit of air volume flow rate used to measure cooling system output and server airflow requirements. A typical 1U server requires 80-150 CFM. CRAC/CRAH units are rated in CFM (5,000-20,000+ CFM per unit). Proper CFM matching prevents hot spots and over-cooling.","link":"glossary.html#term-cfm","aliases":["(Cubic Feet per Minute)","CFM (Cubic Feet per Minute)"]},"change-management":{"t":"Change Management (MOC) ((MOC))","d":"A structured process for planning, approving, implementing, and documenting modifications to data center infrastructure. Includes risk assessment, rollback procedures, and stakeholder communication. Poor change management is responsible for approximately 22% of data center outages.","link":"glossary.html#term-change-management","aliases":["(MOC)","Change Management (MOC)"]},"chiller":{"t":"Chiller","d":"A refrigeration machine that removes heat from a liquid (chilled water) which is then circulated to cooling units. Data center chillers typically produce chilled water at 7-12 C. Types include air-cooled (outdoor condenser), water-cooled (cooling tower required), and magnetic-bearing centrifugal chillers.","link":"glossary.html#term-chiller","aliases":["Chiller"]},"circuit-breaker":{"t":"Circuit Breaker","d":"An automatically operated electrical switch that interrupts current flow when overcurrent or fault conditions are detected. Types include MCB (miniature, up to 125A), MCCB (molded case, up to 2,500A), and ACB (air circuit, up to 6,300A). Selective coordination ensures proper trip sequencing.","link":"glossary.html#term-circuit-breaker","aliases":["Circuit Breaker"]},"city-market":{"t":"City / Market ($/W)","d":"Metro-level construction cost per watt of IT capacity, which overrides the generic Region multiplier with published market data. The spread is large: Tokyo ~$15.20/W and Zurich ~$14.50/W at the top, Dallas ~$14.30/W, down to Warsaw ~$9.00/W and Chennai ~$6.20/W. Cost per Watt is the industry's headline benchmarking unit and maps directly to Cost per kW (multiply by 1,000). Sources: Turner & Townsend DCCI 2025, Cushman & Wakefield 2025.","u":"$/W","table":[["City","$/W (2025)"],["Tokyo","$15.20"],["Zurich","$14.50"],["Dallas, TX","$14.30"],["Warsaw","$9.00"],["Chennai","$6.20"]],"s":"Turner & Townsend DCCI 2025, Cushman & Wakefield 2025","rel":["region-location","cost-per-kw","benchmark-percentile"],"aliases":["City / Market","City-Specific $/W Cost","$/W"]},"closed-transition":{"t":"Closed Transition Transfer","d":"A power transfer method where the load is briefly connected to both sources simultaneously (make-before-break), eliminating any interruption. Closed-transition ATS requires momentary paralleling of utility and generator, necessitating synchronization controls. Transfer time is under 100ms with zero power interruption.","link":"glossary.html#term-closed-transition","aliases":["Closed Transition Transfer"]},"cloud":{"t":"Cloud Computing","d":"The delivery of computing resources (servers, storage, networking, software) over the internet from data center infrastructure. Cloud deployment models include public (shared infrastructure), private (dedicated), and hybrid (combination). Cloud drives demand for hyperscale and edge data centers.","link":"glossary.html#term-cloud","aliases":["Cloud Computing"]},"cold-aisle":{"t":"Cold Aisle","d":"The aisle between two rows of server racks where cooled air is delivered to the front (intake) of IT equipment. Cold aisle temperatures are maintained at 18-27 C per ASHRAE recommendations. Cold aisle containment encloses this space to prevent mixing with hot exhaust air.","link":"glossary.html#term-cold-aisle","aliases":["Cold Aisle"]},"cold-plate":{"t":"Cold Plate","d":"A liquid-cooled metal block clamped to a CPU or GPU that carries heat into the secondary coolant through micro-channels. Direct-to-chip cold plates set the minimum per-device flow and the cleanliness requirement (5–10 &micro;m side-stream filtration) for the whole loop.","link":"glossary.html#term-cold-plate","aliases":["Cold Plate"]},"colocation":{"t":"Colocation (Colo) ((Colo))","d":"A facility where businesses rent rack space, power, cooling, and network connectivity. Tenants own and operate their IT equipment while the provider maintains the physical infrastructure. Pricing models include per-rack, per-kW, and per-cabinet.","link":"glossary.html#term-colocation","aliases":["(Colo)","Colocation (Colo)"]},"colocation-pricing":{"t":"Colocation Pricing","d":"How multi-tenant data center capacity is sold: retail colocation prices per kW per month (commonly $100–250/kW/mo with cross-connects and remote hands on top), while wholesale prices per kW or per MW on multi-year terms at lower unit rates. Pricing power tracks market vacancy, power availability, and connectivity (a Fiber Entry meet-me room adds interconnection revenue). Contract Escalation clauses and term length determine how durable today's Revenue per kW is against OPEX Growth.","u":"$/kW/month","rel":["revenue-per-kw","hyperscaler-prelease","escalation","fiber-entry"],"aliases":["Colocation Pricing","colocation pricing","colo pricing"]},"colossus":{"t":"Colossus (xAI)","d":"xAI's 100,000-GPU H100 supercomputer in Memphis, Tennessee, completed in 122 days (June-September 2024). Notable for its retrofit-first construction methodology (converted Electrolux factory) and use of Tesla Megapacks for power conditioning. The deployment is also notable for environmental controversy: temporary methane gas turbines were operated without Clean Air Act permits, drawing $75,000 enforcement action and community lawsuits.","link":"glossary.html#term-colossus","aliases":["Colossus (xAI)"]},"commissioning":{"t":"Commissioning (Cx) ((Cx))","d":"A systematic process of verifying that all data center systems are designed, installed, tested, and capable of operating per the owner's requirements. Includes factory acceptance testing (FAT), site acceptance testing (SAT), and integrated systems testing (IST).","link":"glossary.html#term-commissioning","aliases":["(Cx)","Commissioning (Cx)"]},"compartmentation":{"t":"Compartmentation","d":"Dividing a facility into fire-rated compartments (rated walls/floors, fire dampers, sealed cable penetrations) so a fire &mdash; or a lithium-ion thermal-runaway event &mdash; is contained to one zone and cannot propagate. The structural complement to detection and suppression, and a core requirement for Li-ion battery rooms under NFPA 855.","link":"glossary.html#term-compartmentation","aliases":["Compartmentation"]},"compliance":{"t":"Compliance","d":"Adherence to regulatory requirements and industry standards governing data center operations. Key frameworks include SOC 2, ISO 27001, PCI DSS, HIPAA, GDPR, and local building codes. Compliance requires documented policies, regular audits, and continuous monitoring.","link":"glossary.html#term-compliance","aliases":[]},"computational-fluid-dynamics":{"t":"CFD (Computational Fluid Dynamics) ((Computational Fluid Dynamics))","d":"Computer simulation of airflow, temperature, and pressure distributions within a data center. CFD modeling validates cooling designs, identifies hot spots, and optimizes tile placement before physical deployment. Industry-standard tools include 6SigmaRoom and Future Facilities.","link":"glossary.html#term-computational-fluid-dynamics","aliases":["(Computational Fluid Dynamics)","CFD (Computational Fluid Dynamics)"]},"concurrent-maintainability":{"t":"Concurrent Maintainability","d":"The ability to perform planned maintenance on any infrastructure component without interrupting IT operations. A defining requirement of Tier III certification. Requires multiple distribution paths and N+1 component redundancy so one path can be taken offline while the other serves the load.","link":"glossary.html#term-concurrent-maintainability","aliases":["Concurrent Maintainability"]},"condenser":{"t":"Condenser","d":"A heat exchanger that rejects heat from the refrigeration cycle to the outdoor environment. Air-cooled condensers use fans to blow ambient air over coils; water-cooled condensers reject heat to a cooling tower water circuit for higher efficiency.","link":"glossary.html#term-condenser","aliases":["Condenser"]},"conduit":{"t":"Conduit","d":"A tube or channel that protects electrical wiring from physical damage. Types used in data centers include EMT (Electrical Metallic Tubing), rigid metal conduit, and PVC conduit. Under-floor conduit runs must be routed to minimize obstruction of airflow in the plenum space.","link":"glossary.html#term-conduit","aliases":["Conduit"]},"containment":{"t":"Containment (Hot Aisle / Cold Aisle Containment) ((Hot Aisle / Cold Aisle Containment))","d":"Physical barriers (doors, curtains, panels) that separate hot exhaust air from cold supply air in a data center. Containment prevents air mixing, improves cooling efficiency by 20-40%, and allows higher supply air temperatures for economizer operation.","link":"glossary.html#term-containment","aliases":["(Hot Aisle / Cold Aisle Containment)","Containment (Hot Aisle / Cold Aisle Containment)"]},"contingency":{"t":"Contingency","d":"The budget reserve for unknowns — design development, scope growth, market movement, and site surprises — typically 5–20% of estimated cost (10% is standard for well-defined projects; early-stage or novel-technology builds like Deep Sea Water Cooling carry 15%+). Contingency is exactly what the Monte-Carlo P10/P50/P90 range quantifies: if your P90 sits far above your point estimate, your contingency is telling you it is too thin.","u":"% of estimated cost","rel":["monte-carlo","p10-p50-p90","design-fee","total-capex"],"aliases":["Contingency","contingency reserve"]},"contractor-availability":{"t":"Contractor Availability","d":"Labor-market tightness in the chosen metro, a major source of regional cost variance — location-specific labor costs drive significant spread between otherwise identical builds (per Matt Pacione). High availability adds no premium, normal markets ~+3%, and tight markets (multiple hyperscale projects competing for the same electricians and pipefitters) ~+8%. Correlates strongly with Market Conditions and the City / Market cost level.","table":[["Availability","Premium"],["High Availability","+0%"],["Normal","+3%"],["Tight Market","+8%"]],"rel":["market-condition","city-market","tab-talent"],"aliases":["Contractor Availability","contractor availability"]},"cooling-tower":{"t":"Cooling Tower","d":"An evaporative heat rejection device that cools water by exposing it to air. Water-cooled chillers reject heat to cooling towers. Types include open-circuit (water contacts air directly) and closed-circuit (water stays in coils). Cooling towers consume significant water (3-5 L/kWh of heat rejected).","link":"glossary.html#term-cooling-tower","aliases":["Cooling Tower"]},"cooling-type":{"t":"Cooling Type","d":"The heat-rejection technology, which affects both CAPEX and operational efficiency (PUE). Air cooling via CRAC/CRAH units serves standard racks under 10 kW; in-row precision units handle 10–20 kW; RDHX (rear-door heat exchangers) cover 20–40 kW; DLC (direct liquid cooling) is required for AI/HPC racks at 50+ kW. The choice sets the Refrigerant path (chiller/CRAC vs chiller-less), the achievable PUE, and build schedule (liquid ~1.3x, Deep Sea Water Cooling ~1.45x of baseline cooling schedule).","table":[["Type","Best For"],["Air (CRAC/CRAH)","Standard <10 kW/rack"],["In-Row Precision","Medium 10-20 kW/rack"],["RDHX (Rear Door)","High 20-40 kW/rack"],["DLC (Direct Liquid)","AI/HPC 50+ kW/rack"]],"rel":["rack-density","pue","refrigerant","deep-sea-water-cooling"],"aliases":["Cooling Type","cooling type","CRAC","CRAH","RDHX","Direct Liquid Cooling","DLC"]},"cop":{"t":"COP (Coefficient of Performance)","d":"Cooling delivered per unit of electrical input — a chiller with COP 6.5 (the water-cooled baseline in the engine) moves 6.5 kW of heat per kW of compressor power. Refrigerant choice shifts COP by a few percent either way (indexed to R-134a = 1.00: ammonia 1.04, R-32 1.02, R-410A 0.95, R-1234ze 0.96), which compounds over 8,760 hours a year into real PUE and Annual Energy Cost differences. Higher COP also shrinks the heat-rejection plant needed per MW of IT.","f":"COP = cooling output (kWth) / electrical input (kWe)","rel":["refrigerant","pue","annual-energy-cost"],"aliases":["COP","Coefficient of Performance","copIndex"]},"corrosion":{"t":"Corrosion","d":"Chemical degradation of metal surfaces caused by exposure to humidity, airborne contaminants (sulfur, chlorine), or galvanic reactions. ASHRAE TC 9.9 classifies data center environments as G1 (mild) to GX (severe) for gaseous contamination. Copper and silver coupon testing monitors corrosion rates.","link":"glossary.html#term-corrosion","aliases":["Corrosion"]},"cost-per-kw":{"t":"Cost per kW (of IT Load)","d":"The industry benchmark unit cost: Total CAPEX divided by IT Load capacity. Typical ranges are $8,000–15,000/kW for Tier III facilities and $15,000–25,000/kW for Tier IV; AI/liquid-cooled builds trend higher on mechanical scope but can be lower per kW at very high Rack Density because the building shrinks. Comparing your figure against the City / Market $/W anchors and Benchmark Percentile tells you instantly whether an estimate is credible.","f":"Cost per kW = Total CAPEX / IT Load (kW)","u":"$/kW","table":[["Class","Typical Range"],["Tier III","$8,000-15,000/kW"],["Tier IV","$15,000-25,000/kW"]],"rel":["total-capex","it-load","city-market","benchmark-percentile"],"aliases":["Cost per kW IT Load","Cost per kW","$/kW"]},"crac":{"t":"CRAC (Computer Room Air Conditioning) ((Computer Room Air Conditioning))","d":"A precision cooling unit with a built-in compressor that provides temperature and humidity control for data centers. CRACs use a direct expansion (DX) refrigeration cycle. Typical capacities range from 20-150 kW per unit.","link":"glossary.html#term-crac","aliases":["(Computer Room Air Conditioning)","CRAC (Computer Room Air Conditioning)"]},"crah":{"t":"CRAH (Computer Room Air Handler) ((Computer Room Air Handler))","d":"A precision air handler that uses chilled water from a central plant instead of a built-in compressor. CRAHs are more energy-efficient than CRACs for larger deployments and allow variable-speed fan control for demand-based cooling.","link":"glossary.html#term-crah","aliases":["(Computer Room Air Handler)","CRAH (Computer Room Air Handler)"]},"cross-connect":{"t":"Cross-Connect","d":"A physical cable link between two customers or between a customer and a network carrier within a colocation facility. Cross-connects enable direct, low-latency interconnection without traversing the public internet. Types include copper (Cat6), fiber (single/multi-mode), and coax.","link":"glossary.html#term-cross-connect","aliases":["Cross-Connect"]},"cross-zoned-detection":{"t":"Cross-Zoned Detection","d":"A fire-detection arrangement that requires two independent detectors (or two zones) to alarm before a clean-agent system discharges &mdash; preventing a costly accidental release from a single faulty detector. Standard practice for gaseous suppression in data centers per NFPA 72 / NFPA 2001.","link":"glossary.html#term-cross-zoned-detection","aliases":["Cross-Zoned Detection"]},"cue":{"t":"CUE (Carbon Usage Effectiveness)","d":"The carbon intensity of the facility's compute: total CO2 emissions from energy divided by IT energy, equal to PUE multiplied by the grid's carbon intensity. Two identical 1.3-PUE facilities can differ 20x in CUE depending on whether the grid is hydro/nuclear or coal — which is why siting and On-Site Renewable procurement move carbon more than another PUE decimal. Core metric of the Carbon/ESG module alongside Scope-1 refrigerant and Generator Type fuel emissions.","f":"CUE = Total CO2 (kg) / IT Energy (kWh) = PUE x grid carbon intensity","u":"kgCO2/kWh","rel":["pue","onsite-renewable","tab-carbon","gwp"],"aliases":["CUE","Carbon Usage Effectiveness"]},"data-hall":{"t":"Data Hall (White Space) ((White Space))","d":"The usable floor area within a data center where IT racks and servers are deployed. Data halls are typically designed for specific power densities (kW/rack) and organized into hot/cold aisle configurations. Modern halls range from 500 to 5,000+ sqm.","link":"glossary.html#term-data-hall","aliases":["(White Space)","Data Hall (White Space)"]},"day-tank":{"t":"Day Tank","d":"A small fuel storage tank (typically 500-2,000 liters) located near each generator that provides immediate fuel supply. Fuel is pumped from the main storage tank to day tanks automatically. Day tanks ensure generators can start and run even if the main fuel transfer pump fails.","link":"glossary.html#term-day-tank","aliases":["Day Tank"]},"dc-power":{"t":"DC Power Distribution","d":"A power architecture that distributes direct current (typically 48V or 380V DC) directly to IT equipment, eliminating AC-DC-AC conversion stages in traditional UPS systems. DC distribution achieves 2-5% higher end-to-end efficiency. Used in telecom facilities and some hyperscale data centers.","link":"glossary.html#term-dc-power","aliases":["DC Power Distribution"]},"dcdc-bicsi":{"t":"DCDC (Data Center Design Consultant — BICSI) ((Data Center Design Consultant — BICSI))","d":"A senior-level BICSI credential for designers leading full data center facility designs. DCDC builds on RCDD with deeper coverage of MEP integration, redundancy topology, and risk analysis. Holding both RCDD and DCDC is common for principal designers at DC engineering firms.","link":"glossary.html#term-dcdc-bicsi","aliases":["(Data Center Design Consultant — BICSI)","DCDC (Data Center Design Consultant — BICSI)"]},"dcie":{"t":"DCiE (Data Center Infrastructure Efficiency)","d":"The reciprocal of PUE expressed as a percentage: IT power divided by total facility power. A PUE of 1.55 equals DCiE 65%; PUE 1.15 equals DCiE 87%. It carries identical information to PUE but reads intuitively as 'what share of my electricity actually reaches the servers' — useful when presenting efficiency to non-technical stakeholders.","f":"DCiE = (IT Power / Total Facility Power) x 100% = 100% / PUE","u":"%","rel":["pue"],"aliases":["DCiE","Data Center Infrastructure Efficiency"]},"dcim":{"t":"DCIM (Data Center Infrastructure Management) ((Data Center Infrastructure Management))","d":"Software platforms that monitor, measure, manage, and optimize data center infrastructure including power, cooling, space, and network connectivity. DCIM tools provide real-time dashboards, capacity planning, and automated alerting.","link":"glossary.html#term-dcim","aliases":["(Data Center Infrastructure Management)","DCIM (Data Center Infrastructure Management)"]},"debt-ratio-leverage":{"t":"Debt Ratio (Leverage)","d":"The share of Total CAPEX funded by debt rather than equity — data center project finance commonly runs 50–70% loan-to-cost, with stabilized refinancings going higher. More leverage magnifies Equity IRR when the project outearns its interest rate, but it also thins the DSCR cushion and raises default risk in downside scenarios; lenders size the loan to whichever binds first, the LTC cap or the DSCR covenant. The Investment module's Capital Structure and Debt Amortization Schedule show the mechanics.","f":"Debt Ratio = Debt / (Debt + Equity)","u":"%","rel":["dscr","equity-irr","wacc","tab-invest"],"aliases":["Debt Ratio","leverage","loan-to-cost","Capital Structure"]},"decommission":{"t":"Decommission","d":"The process of safely removing IT equipment or infrastructure from active service. Includes data sanitization (NIST 800-88), physical asset tracking, environmental compliance for e-waste, and reclaiming power and cooling capacity.","link":"glossary.html#term-decommission","aliases":["Decommission"]},"deep-sea-water-cooling":{"t":"Deep Sea Water Cooling (DSWC)","d":"Chiller-less primary cooling that rejects heat into cold deep seawater (4–6 °C drawn from 800–1000 m depth) through a Titanium Plate Heat Exchanger, organized as a Three-Loop Architecture (rack CDU → closed facility water → open seawater). Because the ocean does the refrigeration, compressor energy disappears: design PUE ≤ 1.15 and WUE ≈ 0 (no evaporative water use), with a Trim Chiller kept as hybrid backup for warm events and maintenance. Reference basis: a 150 MW AI data center rejecting 172.5 MW of heat needs 8.625 m³/s (31,050 m³/h) of Seawater Flow at the 5 °C design ΔT, moved by 4+1 pumps of 2.9 m³/s at 60 m head (~2,000 kW each).","f":"Flow = Heat (W) / (rho x cp x deltaT); poster basis: 172.5e6 / (4000 x 1000/... ) -> 8.625 m3/s at deltaT 5 C","s":"150 MW AI DC deep-sea cooling reference architecture (2026); Makai Ocean Engineering SWAC studies; NOAA World Ocean Atlas temperature profiles","rel":["intake-depth","seawater-delta-t","three-loop-architecture","titanium-phe","trim-chiller","seawater-flow","ppue","wue"],"aliases":["Deep Sea Water Cooling System","Deep Sea Water Cooling","deep sea cooling","SWAC"]},"delivery-method":{"t":"Delivery Method","d":"The contracting structure for design and construction, which shifts both cost and risk allocation. Design-Bid-Build is the baseline (full owner control, sequential schedule); Design-Build integrates the two and saves ~3%; modular-prefab moves work into the factory for ~-8% and faster schedules; EPC turnkey costs ~+5% for single-source responsibility but transfers delivery risk to the contractor. The right choice depends on the owner's in-house Project Management capability and risk appetite.","table":[["Method","Impact"],["Design-Bid-Build","Baseline"],["Design-Build","-3% (integrated)"],["Modular-Prefab","-8% (factory-built)"],["EPC Turnkey","+5% (single source)"]],"rel":["pm-fee","design-fee","market-condition","building-type"],"aliases":["Delivery Method","Design-Bid-Build","Design-Build","EPC Turnkey"]},"delta-t":{"t":"Delta-T (Temperature Differential) ((Temperature Differential))","d":"The difference between supply and return air temperatures across IT equipment. A typical server Delta-T is 10-15 C. Monitoring Delta-T helps identify airflow problems, overloaded racks, and cooling inefficiencies.","link":"glossary.html#term-delta-t","aliases":["(Temperature Differential)","Delta-T (Temperature Differential)"]},"demand-response":{"t":"Demand Response","d":"Programs where data centers reduce or shift electrical consumption during peak grid demand in exchange for financial incentives from the utility. Strategies include temporarily raising cooling setpoints, shifting non-critical workloads, or activating on-site generation to reduce grid draw.","link":"glossary.html#term-demand-response","aliases":["Demand Response"]},"depreciation":{"t":"Depreciation","d":"The accounting allocation of CAPEX over asset useful lives — building shell 30–39 years, electrical and mechanical plant 10–20, IT and controls 3–7 — via straight-line or declining-balance methods. It is a non-cash expense that shields income from tax (the depreciation tax shield), so accelerated schedules and Tax Holiday interactions pull real cash value forward. The DCMOC Asset Lifecycle module models category-level depreciation, book value decay, and replacement timing across the projection horizon.","u":"USD/yr","rel":["capex","tax-holiday","ebitda","tab-asset-lifecycle"],"aliases":["Depreciation","depreciation"]},"derating":{"t":"Derating","d":"Reducing the rated capacity of electrical equipment based on operating conditions. Common derating factors include altitude (above 1,000m), ambient temperature (above 40 C), and harmonic content. A generator rated at 2,000 kW may derate to 1,800 kW at high altitude and temperature.","link":"glossary.html#term-derating","aliases":["Derating"]},"design-concentration":{"t":"Design Concentration","d":"The volumetric concentration (%) of a clean agent a system is engineered to achieve &mdash; the minimum extinguishing concentration plus a safety factor. Novec 1230 ~4.7%, FM-200 ~7%, IG-541 ~37.5%. It must stay at or below the agent's NOAEL in a normally-occupied space, and sets the agent mass via the NFPA 2001 equation W = (V/s)&middot;(C/(100−C)).","link":"glossary.html#term-design-concentration","aliases":["Design Concentration"]},"design-fee":{"t":"Design & Engineering Fee","d":"Architecture, MEP engineering, and specialty consulting fees, typically 5–12% of construction cost (8% is a common midpoint for mission-critical work, higher than commercial buildings because of redundancy engineering and commissioning documentation). Complex Cooling Type choices (DLC, Deep Sea Water Cooling) and high Redundancy push toward the top of the range. Booked as a soft cost alongside the Project Management fee and Contingency.","u":"% of construction cost","rel":["pm-fee","contingency","delivery-method"],"aliases":["Design & Engineering","Design Fee","design fee"]},"dew-point":{"t":"Dew Point","d":"The temperature at which air becomes saturated and condensation forms. ASHRAE recommends maintaining data center dew point between 5.5 C and 15 C to prevent both condensation (too high) and electrostatic discharge (too low).","link":"glossary.html#term-dew-point","aliases":["Dew Point"]},"dew-point-reset":{"t":"Dew-Point Reset","d":"A CDU control strategy that raises the secondary supply temperature to stay &ge;2–3 °C above the room dew point, preventing condensation on cold-plate and manifold surfaces. A room RH/temperature sensor drives the reset; it is the critical safety interlock for warm-water cooling.","link":"glossary.html#term-dew-point-reset","aliases":["Dew-Point Reset"]},"diesel-generator":{"t":"Diesel Generator (Genset) ((Genset))","d":"An engine-driven generator that produces electrical power from diesel fuel during utility outages. Data center generators are sized to carry full facility load and typically rated for continuous operation. Start time is 10-15 seconds with fuel autonomy of 24-72 hours on-site.","link":"glossary.html#term-diesel-generator","aliases":["(Genset)","Diesel Generator (Genset)"]},"digital-twin":{"t":"Digital Twin (Data Center)","d":"A high-fidelity virtual replica of a data center facility used for training, scenario rehearsal, commissioning validation, and what-if analysis without risking production systems. NVIDIA Omniverse and Cadence RealityDC (deployed at Yotta) are leading platforms. Once built, twins support unlimited concurrent trainees, dramatically accelerating onboarding for adjacent-industry hires. Setup cost ranges $170K-$2.7M depending on facility complexity.","link":"glossary.html#term-digital-twin","aliases":["Digital Twin (Data Center)"]},"disaster-recovery":{"t":"Disaster Recovery (DR) ((DR))","d":"Plans and procedures for restoring IT services after a catastrophic event (natural disaster, fire, cyber attack). DR strategies include cold standby (hours RTO), warm standby (minutes), hot standby (seconds), and active-active (near-zero). DR plans require regular testing and updating.","link":"glossary.html#term-disaster-recovery","aliases":["(DR)","Disaster Recovery (DR)"]},"discounted-payback":{"t":"Discounted Payback Period","d":"The payback calculation with each year's cash flow discounted at the cost of capital first — the honest version of the Payback Period, always longer than the simple one. It answers 'when has the project repaid its capital including the return that capital had to earn'. A project whose discounted payback never arrives within the horizon has negative NPV by construction.","f":"Discounted Payback = years until sum( CF_t / (1+r)^t ) >= initial investment","u":"years","rel":["payback-period","npv","wacc"],"aliases":["Discounted Payback","discounted payback"]},"distribution":{"t":"Distribution (Power Distribution) ((Power Distribution))","d":"The network of switchgear, transformers, PDUs, and cabling that delivers electricity from the utility entrance to individual server power supplies. Distribution topology (radial, ring, or distributed redundant) determines the facility's reliability and maintainability characteristics.","link":"glossary.html#term-distribution","aliases":["(Power Distribution)","Distribution (Power Distribution)"]},"diversity-factor":{"t":"Diversity Factor","d":"The ratio of the sum of individual maximum demands to the maximum demand of the combined system. Data centers apply diversity factors (typically 0.7-0.85) when sizing upstream electrical infrastructure, recognizing that not all loads peak simultaneously.","link":"glossary.html#term-diversity-factor","aliases":["Diversity Factor"]},"dlc":{"t":"DLC (Direct Liquid Cooling) ((Direct Liquid Cooling))","d":"A cooling method where liquid flows directly to cold plates mounted on CPUs, GPUs, or memory modules. DLC captures 60-80% of server heat at the source, enabling rack densities exceeding 100 kW. Essential for AI/HPC deployments with GPUs above 700W TDP.","link":"glossary.html#term-dlc","aliases":["(Direct Liquid Cooling)","DLC (Direct Liquid Cooling)"]},"dmsms":{"t":"DMSMS (Diminishing Manufacturing Sources and Material Shortages) ((Diminishing Manufacturing Sources and Material Shortages))","d":"A supply-chain risk management discipline that proactively monitors component lifecycle status through stages — Active → NRND (Not Recommended for New Designs) → Last-Time-Buy → Obsolete — and initiates mitigation actions before shortages occur. For data centers, DMSMS applies to BMS/EPMS control boards, legacy UPS modules, proprietary chiller controllers, and cooling fluids like Novec 7000 (discontinued by 3M in 2025). Key outputs are an EOL Exposure Score and a Last-Time-Buy quantity recommendation.","link":"glossary.html#term-dmsms","aliases":["(Diminishing Manufacturing Sources and Material Shortages)","DMSMS (Diminishing Manufacturing Sources and Material Shortages)"]},"dns":{"t":"DNS (Domain Name System) ((Domain Name System))","d":"The hierarchical naming system that translates human-readable domain names into IP addresses. Data centers host DNS servers that require high availability and low latency. Anycast DNS distributes queries across geographically dispersed servers.","link":"glossary.html#term-dns","aliases":["(Domain Name System)","DNS (Domain Name System)"]},"double-conversion":{"t":"Double Conversion (Online UPS) ((Online UPS))","d":"A UPS topology where incoming AC power is converted to DC (rectifier), then back to AC (inverter), providing complete isolation from utility disturbances. Double-conversion UPS offers the highest level of protection but has 3-6% energy loss. Modern designs achieve 96-97% efficiency.","link":"glossary.html#term-double-conversion","aliases":["(Online UPS)","Double Conversion (Online UPS)"]},"dry-cooler":{"t":"Dry Cooler","d":"An air-cooled heat exchanger that rejects heat from a glycol or water loop to outdoor air without evaporative processes. Dry coolers are used in free cooling systems and consume no water, making them suitable for water-scarce regions. Effective when ambient temperature is below the cooling setpoint.","link":"glossary.html#term-dry-cooler","aliases":["Dry Cooler"]},"dscr":{"t":"DSCR (Debt Service Coverage Ratio)","d":"Net Operating Income divided by annual debt service (principal + interest) — the lender's primary covenant metric answering 'how comfortably does the project pay its loan'. Data center project finance typically requires minimum DSCR of 1.20–1.40x, with hyperscale pre-leased assets achieving cheaper debt at lower thresholds; a DSCR below 1.0 means the project cannot cover its debt from operations. It is squeezed from both sides: NOI (via Occupancy Ramp, Revenue per kW, OPEX Growth) and leverage (via the Debt Ratio and interest rate), and it caps how much debt the Capital Structure can carry.","f":"DSCR = NOI / Annual Debt Service","table":[["Level","Meaning"],["<1.0x","Cannot service debt"],["1.2x","Typical covenant floor"],["1.4x+","Comfortable"],["2.0x+","Under-levered"]],"rel":["noi","debt-ratio-leverage","equity-irr","occupancy-ramp","tab-invest"],"aliases":["DSCR","Debt Service Coverage Ratio"]},"dual-feed":{"t":"Dual Feed (Dual Utility Feed) ((Dual Utility Feed))","d":"Two independent utility power feeds from separate substations or grid paths supplying a data center. Dual feeds provide redundancy at the utility level, reducing single points of failure. Required for Tier III and Tier IV facilities.","link":"glossary.html#term-dual-feed","aliases":["(Dual Utility Feed)","Dual Feed (Dual Utility Feed)"]},"duct-bank":{"t":"Duct Bank","d":"An underground conduit system for routing electrical cables from utility transformers to the building. Duct banks protect cables from environmental damage and allow future cable pulls. Typical configurations include 2x2 or 3x3 PVC conduit arrays encased in concrete.","link":"glossary.html#term-duct-bank","aliases":["Duct Bank"]},"ebitda":{"t":"EBITDA","d":"Earnings Before Interest, Taxes, Depreciation, and Amortization — the operating cash-generation proxy used for valuation (Exit EV/EBITDA Multiple) and leverage metrics (debt/EBITDA). For a data center it is nearly identical to NOI, differing mainly in corporate overhead treatment; stabilized facilities commonly run 50–65% EBITDA margins because the cost base is dominated by pass-through or contracted items. Exit-year EBITDA times the exit multiple is usually the largest single cash flow in the deal.","f":"EBITDA = Revenue - OPEX (before interest, tax, depreciation, amortization)","u":"USD/yr","rel":["noi","exit-ev-ebitda-multiple","terminal-value","depreciation"],"aliases":["EBITDA"]},"economizer":{"t":"Economizer","d":"A system that uses outside air or water to provide free cooling when ambient conditions are favorable. Air-side economizers introduce filtered outdoor air directly; water-side economizers bypass the chiller using a plate heat exchanger. Economizers can reduce cooling energy by 40-70% in temperate climates.","link":"glossary.html#term-economizer","aliases":["Economizer"]},"edge-data-center":{"t":"Edge Data Center","d":"A small-footprint facility (typically 0.1-5 MW) located close to end users to reduce latency for real-time applications. Edge sites support 5G, IoT, content delivery, and autonomous vehicles. They trade large-scale efficiency for proximity, achieving sub-5ms latency to users.","link":"glossary.html#term-edge-data-center","aliases":["Edge Data Center"]},"effectiveness-ntu":{"t":"Effectiveness-NTU (&epsilon;-NTU) ((&epsilon;-NTU))","d":"The standard method to size or rate a heat exchanger without iterating on outlet temperatures. Effectiveness &epsilon; = actual heat transfer &divide; maximum possible; NTU = UA &divide; C min . Used to compute a CDU's approach temperature from its UA and flow rates.","link":"glossary.html#term-effectiveness-ntu","aliases":["(&epsilon;-NTU)","Effectiveness-NTU (&epsilon;-NTU)"]},"efficiency":{"t":"Efficiency (Energy Efficiency) ((Energy Efficiency))","d":"The ratio of useful output to total input energy. Data center efficiency is measured at multiple levels: UPS efficiency (96-97%), cooling plant efficiency (kW/ton), and overall facility efficiency (PUE). Improving efficiency reduces both OPEX and environmental impact.","link":"glossary.html#term-efficiency","aliases":["(Energy Efficiency)","Efficiency (Energy Efficiency)"]},"efi":{"t":"EF&I (Engineer, Furnish & Install) ((Engineer, Furnish & Install))","d":"A project delivery method where a single contractor is responsible for engineering design, equipment procurement, and installation. Common in data center construction for mechanical and electrical systems to streamline accountability and scheduling.","link":"glossary.html#term-efi","aliases":["(Engineer, Furnish & Install)","EF&I (Engineer, Furnish & Install)"]},"electrical-panel":{"t":"Electrical Panel (Distribution Board) ((Distribution Board))","d":"An enclosure that divides an electrical power feed into subsidiary circuits with individual overcurrent protection (breakers or fuses). In data centers, panels distribute power from PDUs to individual rack whips at the branch circuit level.","link":"glossary.html#term-electrical-panel","aliases":["(Distribution Board)","Electrical Panel (Distribution Board)"]},"electrical-single-line":{"t":"Electrical Single-Line Diagram","d":"A simplified schematic showing the power distribution path from utility intake through switchgear, transformers, UPS, and PDUs to the IT load. The single-line diagram is the fundamental reference document for understanding a data center's electrical topology and redundancy architecture.","link":"glossary.html#term-electrical-single-line","aliases":["Electrical Single-Line Diagram"]},"encapsulation":{"t":"Encapsulation","d":"The process of isolating data packets within protocol layers for network transmission. In data centers, VXLAN and NVGRE encapsulation enable network virtualization by wrapping tenant traffic in overlay headers, allowing flexible workload placement across physical switches.","link":"glossary.html#term-encapsulation","aliases":["Encapsulation"]},"enclosure":{"t":"Enclosure (Server Cabinet / Rack) ((Server Cabinet / Rack))","d":"A physical structure (typically 42U or 48U tall, 600-800mm wide) that houses IT equipment. Enclosures provide physical security, cable management, and airflow direction. High-density enclosures include integrated liquid cooling manifolds for DLC deployments.","link":"glossary.html#term-enclosure","aliases":["(Server Cabinet / Rack)","Enclosure (Server Cabinet / Rack)"]},"energy-star":{"t":"Energy Star","d":"A US EPA certification program that identifies energy-efficient products and buildings. Data centers can earn Energy Star certification by achieving a score of 75 or higher on the EPA's 1-100 energy performance scale, indicating they perform better than 75% of similar facilities.","link":"glossary.html#term-energy-star","aliases":["Energy Star"]},"entrainment":{"t":"Entrainment (Marine Impact)","d":"The drawing of small marine organisms — larvae, eggs, plankton — into the intake flow, the primary ecological concern of any large seawater system moving 31,050 m³/h. Mitigations include low intake approach velocities, deep placement (the 800–1000 m Intake Depth is naturally less biologically productive than surface waters), and fine Seawater Filtration screens with fish-return provisions. Entrainment and thermal-plume studies are core to the environmental impact assessment that permits the project.","rel":["intake-depth","seawater-filtration","outfall-diffuser"],"aliases":["Entrainment","entrainment"]},"environmental-monitoring":{"t":"Environmental Monitoring","d":"Continuous measurement of temperature, humidity, water leaks, airflow, and air quality within a data center using distributed sensors. Modern systems use wireless IoT sensors with 30-second polling intervals feeding DCIM dashboards and automated alerts.","link":"glossary.html#term-environmental-monitoring","aliases":["Environmental Monitoring"]},"epms":{"t":"EPMS (Electrical Power Monitoring System) ((Electrical Power Monitoring System))","d":"A centralized platform that collects real-time electrical data (voltage, current, power, energy, harmonics) from meters throughout the power distribution chain. EPMS enables power capacity planning, PUE tracking, and tenant billing in colocation facilities.","link":"glossary.html#term-epms","aliases":["(Electrical Power Monitoring System)","EPMS (Electrical Power Monitoring System)"]},"epo":{"t":"EPO (Emergency Power Off) ((Emergency Power Off))","d":"A system that immediately disconnects all power to IT equipment in an emergency (fire, flood, electrical hazard). EPO buttons are required by NFPA 70 and must be located at each exit door. Accidental EPO activation is a leading cause of data center outages.","link":"glossary.html#term-epo","aliases":["(Emergency Power Off)","EPO (Emergency Power Off)"]},"equity-irr":{"t":"Equity IRR (Internal Rate of Return to Equity)","d":"The annualized return on the equity slice of the capital stack, after debt service — the number sponsors and investors actually underwrite. Leverage amplifies it: if the Project IRR exceeds the cost of debt, raising the Debt Ratio lifts Equity IRR (and its risk); typical stabilized data center deals target low-to-mid teens Equity IRR, with development-risk deals in the high teens to twenties. Highly sensitive to the Exit EV/EBITDA Multiple, Occupancy Ramp speed, and Revenue per kW — the Sensitivity Matrix and Monte Carlo modules quantify exactly how much.","f":"IRR: rate where NPV of levered equity cash flows (incl. Terminal Value) = 0","u":"%","rel":["project-irr","debt-ratio-leverage","exit-ev-ebitda-multiple","terminal-value","dscr","npv"],"aliases":["Equity IRR","equity IRR","levered IRR"]},"escalation":{"t":"Escalation","d":"Contractual or assumed annual price growth applied to a cash-flow line — construction cost escalation (see Year Escalation, ~7% CAGR 2020–2025 decelerating toward ~3.3% by 2030), lease revenue escalators (commonly 2–3%/yr or CPI-linked in Colocation Pricing), and OPEX Growth. The spread between revenue escalation and cost escalation determines whether margins expand or compress over the hold, so model them separately rather than assuming one inflation number.","u":"%/yr","rel":["year-escalation","opex-growth","colocation-pricing","revenue-per-kw"],"aliases":["Escalation","escalation rate","escalator"]},"esd":{"t":"ESD (Electrostatic Discharge) ((Electrostatic Discharge))","d":"The sudden transfer of static electricity between objects at different electrical potentials. ESD can damage or destroy sensitive electronic components. Prevention requires conductive flooring, grounding straps, humidity control (above 20% RH), and ESD-safe work practices in data centers.","link":"glossary.html#term-esd","aliases":["(Electrostatic Discharge)","ESD (Electrostatic Discharge)"]},"ethernet":{"t":"Ethernet","d":"The dominant networking standard for data center LAN connections. Current speeds include 10 GbE, 25 GbE, 100 GbE, and 400 GbE, with 800 GbE emerging. Ethernet standards (IEEE 802.3) define physical layer, data link protocols, and cabling specifications for both copper and fiber media.","link":"glossary.html#term-ethernet","aliases":["Ethernet"]},"evaporator":{"t":"Evaporator","d":"The heat exchanger in a refrigeration cycle where liquid refrigerant absorbs heat and evaporates. In CRAC units, the evaporator coil cools return air from the data hall. In chillers, the evaporator cools water or glycol for distribution to air handlers.","link":"glossary.html#term-evaporator","aliases":["Evaporator"]},"exhaust":{"t":"Exhaust Air","d":"Hot air expelled from the rear of IT equipment after absorbing heat from processors, memory, and storage. Server exhaust temperatures typically range from 35-50 C depending on load and inlet temperature. Proper exhaust management prevents recirculation to cold aisles.","link":"glossary.html#term-exhaust","aliases":["Exhaust Air"]},"exit-ev-ebitda-multiple":{"t":"Exit EV/EBITDA Multiple","d":"The valuation multiple assumed when the asset is sold or refinanced at the end of the hold: Enterprise Value = exit-year EBITDA x the multiple. Stabilized data centers have traded in the mid-teens to 20x+ EV/EBITDA in recent cycles depending on tenant quality (Hyperscaler Pre-Lease commands premium multiples), market, and growth. Because the exit often represents the majority of total equity proceeds, Equity IRR is acutely sensitive to this single assumption — always stress it in the Sensitivity Matrix.","f":"Exit Enterprise Value = Exit-Year EBITDA x Multiple","u":"x","rel":["ebitda","terminal-value","equity-irr","cap-rate","sensitivity-matrix"],"aliases":["Exit EV/EBITDA Multiple","EV/EBITDA","exit multiple"]},"expansion":{"t":"Expansion (Scalable Design) ((Scalable Design))","d":"Design methodology that allows a data center to grow in phases. Modular expansion enables deploying power and cooling capacity incrementally (e.g., 2 MW phases) to match demand, reducing stranded CAPEX and improving capital efficiency.","link":"glossary.html#term-expansion","aliases":["(Scalable Design)","Expansion (Scalable Design)"]},"fail-safe":{"t":"Fail-Safe","d":"A design principle where a system defaults to a safe state when a failure occurs. In data centers, fail-safe examples include fire dampers that close on power loss, EPO systems that de-energize equipment, and cooling valves that open fully on control signal failure.","link":"glossary.html#term-fail-safe","aliases":["Fail-Safe"]},"fault-tolerance":{"t":"Fault Tolerance","d":"The ability of a system to continue operating without interruption when one or more components fail. Tier IV data centers require fault-tolerant infrastructure where any single equipment failure or distribution path event does not impact IT operations.","link":"glossary.html#term-fault-tolerance","aliases":["Fault Tolerance"]},"fiber-entry":{"t":"Fiber Entry (Connectivity)","d":"The number of physically diverse fiber paths into the building. A single path (~$150K) is a single point of failure; dual diverse entry (~$350K) is the standard for Tier III+ so one backhoe cannot sever connectivity; multi-path with a carrier meet-me room (~$600K) adds interconnection revenue potential and carrier density that raises Colocation Pricing power. Network diversity mirrors the power Redundancy philosophy — no single point of failure.","table":[["Entry","Cost"],["Single Path","~$150K"],["Dual Diverse","~$350K"],["Multi-Path + MMR","~$600K"]],"rel":["cabling-type","redundancy","colocation-pricing"],"aliases":["Fiber Entry","Fiber / Connectivity","Meet-Me Room"]},"fiber-optic":{"t":"Fiber Optic","d":"Glass or plastic strands that transmit data as pulses of light. Single-mode fiber supports distances up to 100 km at speeds up to 400 Gbps. Multi-mode fiber covers shorter distances (up to 500m) at lower cost. OS2 (single-mode) and OM4/OM5 (multi-mode) are common data center grades.","link":"glossary.html#term-fiber-optic","aliases":["Fiber Optic"]},"filtration":{"t":"Filtration (ISO 4406 / NAS 1638) ((ISO 4406 / NAS 1638))","d":"Particulate control for liquid-cooling loops. Integrated CDU filters run ~50 &micro;m; cold-plate side-stream filtration is 5–10 &micro;m. Commissioning flushing targets an ISO 4406 cleanliness code (sensitive loops ~16/14/11) to protect cold-plate micro-channels from clogging.","link":"glossary.html#term-filtration","aliases":["(ISO 4406 / NAS 1638)","Filtration (ISO 4406 / NAS 1638)"]},"fire-alarm":{"t":"Fire Alarm System","d":"The detection layer that triggers Fire Suppression — in a data center, minutes of early warning are worth millions in avoided discharge and downtime. Conventional systems detect late-stage smoke only; addressable systems identify the exact point location; VESDA (aspirating smoke detection) continuously samples air and catches pre-combustion particles before visible smoke; hybrid VESDA + addressable combines earliest warning with precise location. Tier III+ facilities typically specify VESDA in white space.","table":[["Type","Detection Time"],["Conventional","Late stage smoke"],["Addressable","Point location ID"],["VESDA","Pre-combustion"],["Hybrid","Best of both"]],"rel":["fire-suppression","tier-class"],"aliases":["Fire Alarm System","Fire Alarm","VESDA"]},"fire-damper":{"t":"Fire Damper","d":"A device installed in ductwork or wall penetrations that automatically closes to prevent fire and smoke from spreading between zones. Fire dampers activate when a fusible link melts at a set temperature (typically 74 C) or upon signal from the fire alarm system. Required at all fire-rated boundaries.","link":"glossary.html#term-fire-damper","aliases":["Fire Damper"]},"fire-suppression":{"t":"Fire Suppression","d":"Clean-agent suppression systems designed to extinguish fire without damaging live IT equipment (no water dump on servers). FM200/HFC-227ea is common but being phased out on GWP grounds; Novec 1230 is the low-GWP, safest mainstream choice; Inergen (IG-541) is an inert-gas system with no residue; nitrogen inerting suits permanently sealed rooms; water mist is the green alternative for support spaces. Works alongside the Fire Alarm System — detection triggers release, so early VESDA sensing reduces discharge events.","table":[["Agent","Notes"],["FM200/HFC-227ea","Common, being phased out"],["Novec 1230","Low GWP, safest choice"],["Inergen (IG-541)","Inert gas, unlimited"],["Water Mist","Green alternative"]],"rel":["fire-alarm","gwp"],"aliases":["Fire Suppression","FM200","Novec 1230","Inergen"]},"floor-loading":{"t":"Floor Loading","d":"The weight capacity of a data center floor, measured in kg/sqm or lbs/sqft. Standard raised floor tiles support 500-800 kg concentrated load. High-density areas with heavy UPS batteries or liquid cooling equipment may require structural reinforcement to 1,500+ kg/sqm.","link":"glossary.html#term-floor-loading","aliases":["Floor Loading"]},"floor-type":{"t":"Floor Construction (Raised Floor vs Slab)","d":"Whether the data hall uses an access (raised) floor or slab-on-grade with overhead services. Raised floor enables under-floor air distribution and cable routing but adds $25–50/sqft; 600 mm is the baseline, 900 mm adds ~+6% and 1200 mm ~+12% on the building for high-airflow designs. Slab with overhead distribution saves ~5% and is increasingly popular for high Rack Density deployments where air comes from in-row or liquid loops rather than under the floor.","table":[["Type","Cost Impact"],["Slab (overhead services)","-5% on building"],["Raised Floor 600mm","Baseline"],["Raised Floor 900mm","+6% on building"],["Raised Floor 1200mm","+12% (high airflow)"]],"rel":["cooling-type","power-distribution","rack-density"],"aliases":["Floor Construction","Raised Floor","raised floor","slab"]},"flywheel-ups":{"t":"Flywheel UPS","d":"A UPS that stores kinetic energy in a spinning mass instead of chemical batteries. Flywheels provide 10-30 seconds of ride-through, enough for generator transfer. Benefits include 20-year lifespan, smaller footprint, and no battery replacement cycles.","link":"glossary.html#term-flywheel-ups","aliases":["Flywheel UPS"]},"fm200":{"t":"FM-200 (HFC-227ea) ((HFC-227ea))","d":"A clean agent fire suppressant that extinguishes fires by absorbing heat. FM-200 discharges within 10 seconds and leaves no residue, making it safe for IT equipment. Being phased out in some regions due to high global warming potential (GWP = 3,220). Novec 1230 (GWP = 1) is the common replacement.","link":"glossary.html#term-fm200","aliases":["(HFC-227ea)","FM-200 (HFC-227ea)"]},"fmeca":{"t":"FMECA (Failure Mode, Effects & Criticality Analysis) ((Failure Mode, Effects & Criticality Analysis))","d":"A systematic reliability engineering method (MIL-STD-1629A) that identifies every failure mode of a component, assesses its effect on the system, and computes a Criticality Number C m combining severity, occurrence probability, and detectability. In data center spare-parts management, FMECA drives the VITAL / ESSENTIAL / DESIRABLE tier classification and the stock-vs-no-stock decision for M&E components. High-C m parts in failure-effect categories I (catastrophic) or II (critical) are mandatory stock items.","link":"glossary.html#term-fmeca","aliases":["(Failure Mode, Effects & Criticality Analysis)","FMECA (Failure Mode, Effects & Criticality Analysis)"]},"footprint":{"t":"Footprint (Building Footprint) ((Building Footprint))","d":"The total floor area occupied by a data center, including white space, mechanical rooms, electrical rooms, and support spaces. Gross footprint includes the entire building; net footprint counts only usable IT space. Typical ratio of white space to total is 40-60%.","link":"glossary.html#term-footprint","aliases":["(Building Footprint)","Footprint (Building Footprint)"]},"free-cooling":{"t":"Free Cooling","d":"Using outdoor air or water temperatures to cool a data center without running compressors. Available when ambient temperature falls below the cooling setpoint (typically below 18 C). Facilities in northern climates can achieve 3,000-6,000+ hours of annual free cooling.","link":"glossary.html#term-free-cooling","aliases":["Free Cooling"]},"frequency":{"t":"Frequency (Hz) ((Hz))","d":"The number of AC power cycles per second, measured in Hertz. Standard frequencies are 50 Hz (most of the world) and 60 Hz (North America, parts of Asia). IT power supplies are typically auto-ranging (50/60 Hz). Frequency stability is critical; UPS systems regulate output to +/-0.5 Hz.","link":"glossary.html#term-frequency","aliases":["(Hz)","Frequency (Hz)"]},"front-of-meter":{"t":"Front-of-Meter Costs","d":"Grid-side infrastructure the operator often pays for under the utility agreement even though it sits before the revenue meter: interconnection, Substation, transformer, and switchgear, plus the utility's regulated Rate of Return (typically ~9%) on that investment. These costs are frequently forgotten in early budgets yet can add millions — 'Don't forget front-of-meter: transformer, substation, switchgear, and the utility's 9% return on investment' (Mark Lewis, VP Engineering). Transformer Lead Time (18–36 months) often gates the whole project schedule.","rel":["substation-type","transformer-lead","utility-rate","total-capex"],"aliases":["Front-of-Meter","Include Front-of-Meter Costs","front of meter"]},"ft-alerts":{"t":"Alerts","d":"Price-trigger notifications on your chosen symbols: set a level, get alerted when it crosses. Turns the Watchlist from a page you check into a system that checks for you.","rel":["ft-watchlist","ft-stocks"],"aliases":["Alerts"]},"ft-commodities":{"t":"Commodities","d":"Prices and charts for energy, metals, and agricultural commodities. Energy commodities (natural gas, crude) and metals (copper, aluminum) are leading indicators for data center OPEX and construction costs respectively.","rel":["ft-futures","ft-economy"],"aliases":["Commodities"]},"ft-crypto":{"t":"Crypto","d":"Cryptocurrency market data with candle charts and a technical-only committee analysis (Technical + Quant + Risk panels) plus a momentum-scored crypto screener. Fundamentals are intentionally excluded — crypto has no earnings to value. Educational only, not investment advice.","rel":["ft-screener","ft-stocks"],"aliases":["Crypto"]},"ft-economy":{"t":"Economy","d":"Macro indicators dashboard: rates, inflation prints, employment, GDP, and central-bank data. The macro regime sets the discount-rate backdrop — the same force that moves equity valuations also moves data center WACC and Cap Rate assumptions.","rel":["ft-overview","ft-futures","wacc"],"aliases":["Economy"]},"ft-forex":{"t":"Forex","d":"Foreign-exchange rates and history for major and Asian pairs (USD/IDR and peers), with charting. Currency moves matter directly to data center economics: CAPEX is largely USD-denominated equipment while revenue may be local-currency.","rel":["ft-economy","ft-overview"],"aliases":["Forex"]},"ft-futures":{"t":"Futures","d":"Index and commodity futures quotes — the 24-hour risk signal that trades before and after cash markets open. Overnight futures direction is the standard read on how the cash session will open.","rel":["ft-commodities","ft-overview"],"aliases":["Futures"]},"ft-news":{"t":"News","d":"Aggregated market news headlines across equities, macro, and crypto. Headlines drive short-term price action; cross-reference against the Economy calendar to separate noise from scheduled catalysts.","rel":["ft-economy","ft-overview"],"aliases":["News"]},"ft-overview":{"t":"Overview (Finance Terminal)","d":"The market-at-a-glance dashboard: major indices, top movers, sector snapshot, and headline economic prints in one view. The launch pad before drilling into Stocks, Sectors, or Economy tabs.","rel":["ft-stocks","ft-sectors","ft-economy"],"aliases":["Overview"]},"ft-screener":{"t":"Screener","d":"Filters the US or Indonesian stock universe by fundamentals and technicals, ranked by the FIN Engine composite score (value, quality, momentum, risk factors). The systematic top-of-funnel that feeds candidates into the Stocks committee analysis and your Watchlist.","rel":["ft-stocks","ft-watchlist"],"aliases":["Screener"]},"ft-sectors":{"t":"Sectors","d":"Performance heat view of the 11 GICS sectors (technology, energy, financials, utilities, etc.), showing where money is rotating. Sector breadth confirms or contradicts index-level moves on the Overview tab.","rel":["ft-overview","ft-stocks"],"aliases":["Sectors"]},"ft-stocks":{"t":"Stocks","d":"Individual equity view: quotes, candlestick charts with technical indicators (RSI, moving averages, MACD), and the FIN Investment Committee scorecard combining Value Gate screening with conviction scoring. Covers US and Indonesian (IDX .JK) markets. Educational analysis only — not investment advice.","rel":["ft-screener","ft-watchlist","ft-sectors"],"aliases":["Stocks"]},"ft-watchlist":{"t":"Watchlist","d":"Your saved symbols with live quotes in one tracking view — the personal shortlist built from Screener results and Stocks research. Pair with Alerts to get notified on price triggers instead of watching the tape.","rel":["ft-alerts","ft-screener","ft-stocks"],"aliases":["Watchlist"]},"fuel-autonomy":{"t":"Fuel Autonomy","d":"How long the backup generators can run at full facility load without refueling during a utility outage. It is driven by on-site tank capacity versus generator fuel burn, and it directly supports the Tier classification: Uptime Institute Tier III expects 48 hours minimum, while mission-critical sites carry 72+ hours plus refueling contracts. More autonomy means larger tanks, more fuel-polishing systems, and higher Generator Type CAPEX.","u":"hours","table":[["Tier Level","Typical Hours"],["Minimum","8 hours"],["Standard","24 hours"],["Tier III","48 hours"],["Mission Critical","72+ hours"]],"rel":["generator-type","tier-class","redundancy"],"aliases":["Fuel Autonomy (hours)","Fuel Autonomy","fuel autonomy"]},"fuel-cell":{"t":"Fuel Cell","d":"An electrochemical device that converts hydrogen or natural gas directly into electricity without combustion. Data centers are exploring fuel cells as clean on-site power generation with 50-60% electrical efficiency. Can serve as primary power or backup replacing diesel generators.","link":"glossary.html#term-fuel-cell","aliases":["Fuel Cell"]},"fuse":{"t":"Fuse","d":"A sacrificial overcurrent protection device that melts its internal element to break the circuit when current exceeds a safe level. In data centers, fuses are used in high-voltage switchgear (HRC fuses) and low-voltage distribution for selective coordination with upstream breakers.","link":"glossary.html#term-fuse","aliases":["Fuse"]},"fws":{"t":"FWS (Facility Water System) ((Facility Water System))","d":"The primary loop — building chilled or condenser water that rejects the CDU's heat. Hydraulically decoupled from the chip-side TCS loop by the CDU heat exchanger, so it carries a looser water-quality band than the secondary (pH 7–9, chloride <50 ppm, hardness <200 ppm CaCO 3 ).","link":"glossary.html#term-fws","aliases":["(Facility Water System)","FWS (Facility Water System)"]},"galden-ht":{"t":"Galden HT (Solvay/Syensqo PFPE Series) ((Solvay/Syensqo PFPE Series))","d":"A family of perfluoropolyether (PFPE) heat-transfer fluids manufactured by Solvay (Syensqo) used in two-phase immersion cooling. Galden HT is one of the primary alternatives operators are evaluating after 3M's Novec 7000 production wind-down (announced 2022, completed 2025). All Galden HT variants are PFAS compounds and subject to the same regulatory and environmental scrutiny as Novec 7000.","link":"glossary.html#term-galden-ht","aliases":["(Solvay/Syensqo PFPE Series)","Galden HT (Solvay/Syensqo PFPE Series)"]},"gas-suppression":{"t":"Gas Suppression","d":"Fire suppression using inert gases (nitrogen, argon, CO2) or chemical agents (FM-200, Novec 1230) that extinguish fire without water damage. Gas suppression systems require sealed rooms with pressure relief vents and VESDA detection for early warning.","link":"glossary.html#term-gas-suppression","aliases":["Gas Suppression"]},"generator":{"t":"Generator (Standby Generator) ((Standby Generator))","d":"An engine-driven machine that converts mechanical energy into electrical power during utility outages. Data center generators are typically diesel-powered, rated for continuous operation at 1,500-3,000 kW per unit, with N+1 redundancy and automatic start on utility failure.","link":"glossary.html#term-generator","aliases":["(Standby Generator)","Generator (Standby Generator)"]},"generator-paralleling":{"t":"Generator Paralleling","d":"Connecting multiple generators to a common bus to share the electrical load. Paralleling requires synchronization of voltage, frequency, and phase angle. Paralleled generators provide greater flexibility, N+1 redundancy, and the ability to match generation capacity to actual load.","link":"glossary.html#term-generator-paralleling","aliases":["Generator Paralleling"]},"generator-type":{"t":"Generator Type","d":"The backup power generation fuel choice, affecting maintenance regime, emissions, and sustainability posture. Diesel is the reliable industry standard; natural gas cuts local emissions but depends on pipeline availability during regional events; dual-fuel offers flexibility; HVO/biodiesel achieves roughly 90% lower lifecycle CO2 and is a drop-in decarbonization lever that improves the Carbon/ESG picture. Sizing pairs with Fuel Autonomy (tank hours) and Redundancy (N+1 or 2N generator sets).","table":[["Fuel","Notes"],["Diesel","Standard, reliable"],["Natural Gas","Lower emissions"],["Dual Fuel","Flexibility"],["HVO/Biodiesel","90% lower CO2"]],"rel":["fuel-autonomy","redundancy","tab-fuel-gen","tab-carbon"],"aliases":["Generator Type","generator type","HVO","Biodiesel"]},"gfci":{"t":"GFCI (Ground Fault Circuit Interrupter) ((Ground Fault Circuit Interrupter))","d":"A device that disconnects a circuit when it detects an imbalance between the hot and neutral conductors, indicating current leaking to ground. Required near water sources in data centers (cooling equipment areas, battery rooms) per NEC Article 210.","link":"glossary.html#term-gfci","aliases":["(Ground Fault Circuit Interrupter)","GFCI (Ground Fault Circuit Interrupter)"]},"glycol":{"t":"Glycol","d":"An antifreeze additive (propylene or ethylene glycol) mixed with water in cooling loops to prevent freezing in outdoor piping runs. Glycol reduces heat transfer capacity by 5-15% compared to pure water. Concentration typically ranges from 20-40% depending on minimum ambient temperature.","link":"glossary.html#term-glycol","aliases":["Glycol"]},"gpu":{"t":"GPU (Graphics Processing Unit) ((Graphics Processing Unit))","d":"A specialized processor designed for parallel computation, now essential for AI/ML training and inference workloads. Modern data center GPUs (NVIDIA H100, B200) consume 300-1000W each, driving the shift toward liquid cooling and 50-100+ kW rack densities.","link":"glossary.html#term-gpu","aliases":["(Graphics Processing Unit)","GPU (Graphics Processing Unit)"]},"gray-space":{"t":"Gray Space","d":"Non-IT support areas in a data center including electrical rooms, mechanical plant rooms, battery rooms, generator yards, and loading docks. Gray space typically occupies 40-60% of total facility footprint and houses the infrastructure that supports white space operations.","link":"glossary.html#term-gray-space","aliases":["Gray Space"]},"green-building":{"t":"Green Building (LEED / BREEAM) ((LEED / BREEAM))","d":"Sustainable building certifications that evaluate energy efficiency, water conservation, materials selection, and indoor environmental quality. Data centers pursue LEED or BREEAM certification to demonstrate environmental commitment and reduce operating costs.","link":"glossary.html#term-green-building","aliases":["(LEED / BREEAM)","Green Building (LEED / BREEAM)"]},"green-certification":{"t":"Green Certification (LEED / BREEAM)","d":"Third-party green building certification, adding 2–8% to construction cost for sustainable materials, energy modeling, enhanced commissioning, and documentation: LEED Silver ~+2%, Gold ~+4%, Platinum ~+8% (BREEAM Very Good/Outstanding are the European equivalents). The premium buys lower long-term OPEX (better PUE and WUE by design), easier permitting in strict jurisdictions, and ESG credibility that Hyperscaler Pre-Lease tenants increasingly require.","table":[["Level","Cost Premium"],["None","0%"],["LEED Silver","+2%"],["LEED Gold","+4%"],["LEED Platinum","+8%"]],"rel":["pue","wue","tab-carbon","hyperscaler-prelease"],"aliases":["Green Certification","LEED","BREEAM","LEED / BREEAM"]},"greenfield":{"t":"Greenfield","d":"A new data center built from scratch on undeveloped land. Greenfield construction offers maximum design flexibility but requires 18-36 months for completion. Site selection factors include power availability, fiber connectivity, natural disaster risk, land cost, and cooling climate.","link":"glossary.html#term-greenfield","aliases":[]},"grid-connection":{"t":"Grid Connection","d":"The electrical interface between a data center and the utility power grid. Includes high-voltage switchgear, step-down transformers, and metering. Large data centers connect at 33 kV-132 kV and may negotiate dedicated substations with the utility.","link":"glossary.html#term-grid-connection","aliases":["Grid Connection"]},"ground-fault":{"t":"Ground Fault","d":"An unintentional electrical path between an energized conductor and ground. Ground faults can cause equipment damage, fire, and electrocution. Ground fault protection (GFP) devices detect leakage current imbalances and disconnect the circuit. NEC requires GFP on services rated 1,000A or more.","link":"glossary.html#term-ground-fault","aliases":["Ground Fault"]},"grounding":{"t":"Grounding (Earthing) ((Earthing))","d":"Connecting electrical equipment to the earth to provide a safe path for fault currents, prevent electric shock, and reduce electromagnetic interference. Data center grounding systems include the main bonding jumper, equipment grounding conductors, and a ground grid beneath the building.","link":"glossary.html#term-grounding","aliases":["(Earthing)","Grounding (Earthing)"]},"gwp":{"t":"GWP (Global Warming Potential, AR4)","d":"How many times more warming one kilogram of a gas causes than one kilogram of CO2 over 100 years (IPCC AR4 values used sitewide). Legacy refrigerants are heavy: R-410A = 2088, R-134a = 1430; transition fluids sit mid-range (R-513A = 631); next-generation options are near zero (R-1234ze = 7, R-290 propane = 3, R-717 ammonia = 0). GWP x annual leak rate x refrigerant charge gives the Scope-1 carbon from cooling, and GWP thresholds are the regulatory trigger — AIM Act bans GWP > 700 in new equipment from 2025, EU F-Gas targets GWP > 150.","f":"Scope-1 leakage tCO2e/yr = charge (kg) x leak rate (%/yr) x GWP / 1000","s":"IPCC AR4 GWP100","rel":["refrigerant","r410a","r134a","r1234ze","tab-carbon"],"aliases":["GWP","Global Warming Potential"]},"harmonic-distortion":{"t":"Harmonic Distortion (THD) ((THD))","d":"Non-sinusoidal voltage or current waveform distortions caused by nonlinear loads (UPS, VFDs, servers). Total Harmonic Distortion above 5% can cause overheating in transformers and neutral conductors. IEEE 519 sets limits for harmonic current injection.","link":"glossary.html#term-harmonic-distortion","aliases":["(THD)","Harmonic Distortion (THD)"]},"hdpe-marine-pipeline":{"t":"HDPE Marine Pipeline","d":"The high-density polyethylene intake and outfall pipelines running from shore to depth — HDPE because it is corrosion-immune, flexible for seabed contours, and can be float-and-sink installed. Marine installation runs about 3x the onshore pipeline cost (industry range 2.5–4x); unit costs scale with flow, from ~$2.2M/km at ≤3 m³/s up to ~$7.5M/km at 20 m³/s, and the system needs 2 lines (intake + outfall) plus an intake structure (~$4.5M) and Outfall Diffuser (~$1.8M). Pipeline length to reach Intake Depth is typically the largest single CAPEX line in a Deep Sea Water Cooling build.","u":"$/km","table":[["Flow","Cost per km"],["≤3 m³/s","~$2.2M"],["≤6 m³/s","~$3.4M"],["≤10 m³/s","~$4.8M"],["≤20 m³/s","~$7.5M"]],"rel":["intake-depth","outfall-diffuser","seawater-flow","marine-opex"],"aliases":["Pipeline to Shore (km)","HDPE marine pipeline","marine pipeline"]},"header":{"t":"Header (Piping Header) ((Piping Header))","d":"A large-diameter pipe that distributes chilled water or coolant from the central plant to multiple branch circuits serving CRAH units or in-row coolers. Primary headers connect to the chiller plant; secondary headers distribute within the data hall. Properly sized headers ensure balanced flow distribution.","link":"glossary.html#term-header","aliases":["(Piping Header)","Header (Piping Header)"]},"heat-exchanger":{"t":"Heat Exchanger","d":"A device that transfers heat between two fluids without mixing them. Common types in data centers include plate heat exchangers (economizer mode), shell-and-tube (chiller condensers), and micro-channel (rear-door heat exchangers). Effectiveness ratings range from 60-95%.","link":"glossary.html#term-heat-exchanger","aliases":["Heat Exchanger"]},"heat-rejection":{"t":"Heat Rejection","d":"The process of transferring waste heat from a data center cooling system to the outdoor environment. Heat rejection equipment includes cooling towers (evaporative), dry coolers (air-based), and adiabatic coolers (hybrid). Heat rejection capacity must match or exceed total facility heat generation.","link":"glossary.html#term-heat-rejection","aliases":["Heat Rejection"]},"high-voltage":{"t":"High Voltage (HV) ((HV))","d":"Electrical systems operating above 1,000V AC (IEC definition). Data centers receive utility power at high voltage (11 kV-132 kV) and step it down through transformers. HV systems require specialized personnel, PPE, and safety procedures including arc flash assessments.","link":"glossary.html#term-high-voltage","aliases":["(HV)","High Voltage (HV)"]},"hot-aisle":{"t":"Hot Aisle","d":"The aisle between two rows of server racks where hot exhaust air is expelled from the rear of equipment. Hot aisle containment (HAC) captures this heated air and routes it to cooling return paths, preventing mixing with cold supply air and improving cooling efficiency.","link":"glossary.html#term-hot-aisle","aliases":["Hot Aisle"]},"hot-spot":{"t":"Hot Spot","d":"A localized area within a data center where temperatures significantly exceed the cooling design target, usually caused by inadequate airflow, missing blanking panels, or high-density racks without supplemental cooling. Thermal imaging identifies hot spots for remediation.","link":"glossary.html#term-hot-spot","aliases":["Hot Spot"]},"hpc":{"t":"HPC (High Performance Computing) ((High Performance Computing))","d":"Computing environments using clusters of powerful processors for computationally intensive tasks like scientific simulation, financial modeling, and AI training. HPC racks typically draw 30-100+ kW, requiring liquid cooling and specialized power distribution.","link":"glossary.html#term-hpc","aliases":["(High Performance Computing)","HPC (High Performance Computing)"]},"humidity":{"t":"Humidity","d":"The moisture content of air. ASHRAE TC 9.9 recommends maintaining server inlet conditions between 8% and 60% relative humidity (RH), with a dew point range of 5.5-15 C. Low humidity causes electrostatic discharge (ESD); high humidity causes condensation and corrosion.","link":"glossary.html#term-humidity","aliases":["Humidity"]},"hvac":{"t":"HVAC (Heating, Ventilation, and Air Conditioning) ((Heating, Ventilation, and Air Conditioning))","d":"The combined systems that control temperature, humidity, and air quality in a building. Data center HVAC focuses primarily on cooling and humidity control using precision air conditioning (CRAC/CRAH), chillers, and economizers.","link":"glossary.html#term-hvac","aliases":["(Heating, Ventilation, and Air Conditioning)","HVAC (Heating, Ventilation, and Air Conditioning)"]},"hybrid-cooling":{"t":"Hybrid Cooling","d":"A cooling strategy combining multiple technologies such as air cooling for low-density racks and liquid cooling for high-density GPU racks within the same data hall. Hybrid approaches optimize cost and efficiency by matching cooling technology to workload density requirements.","link":"glossary.html#term-hybrid-cooling","aliases":["Hybrid Cooling"]},"hyperscale":{"t":"Hyperscale","d":"A data center architecture designed for massive horizontal scaling, typically with 5,000+ servers and 10+ MW critical IT load. Operated by cloud providers (AWS, Azure, Google, Meta), hyperscale facilities feature custom server designs, advanced automation, and PUE values below 1.2.","link":"glossary.html#term-hyperscale","aliases":["Hyperscale"]},"hyperscaler-prelease":{"t":"Hyperscaler Pre-Lease","d":"A long-term lease (often 10–15 years) signed with a hyperscale cloud or AI tenant before or during construction, typically for the entire building. It transforms the risk profile: the Occupancy Ramp collapses to near-instant, lenders accept higher Debt Ratios at lower rates because DSCR is contractually visible, and exit buyers pay premium EV/EBITDA multiples for the covenant. The trade-off is lower Revenue per kW than retail colocation and concentration risk in a single credit.","rel":["occupancy-ramp","dscr","exit-ev-ebitda-multiple","colocation-pricing","debt-ratio-leverage"],"aliases":["Hyperscaler Pre-Lease","pre-lease","hyperscale lease"]},"igbt":{"t":"IGBT (Insulated-Gate Bipolar Transistor) ((Insulated-Gate Bipolar Transistor))","d":"A power semiconductor device used in UPS inverters and VFDs for efficient high-frequency switching. IGBTs combine the high-current handling of bipolar transistors with the voltage-controlled input of MOSFETs. Modern UPS systems use IGBT-based designs for 97%+ conversion efficiency.","link":"glossary.html#term-igbt","aliases":["(Insulated-Gate Bipolar Transistor)","IGBT (Insulated-Gate Bipolar Transistor)"]},"immersion-cooling":{"t":"Immersion Cooling","d":"A liquid cooling method where IT components are fully submerged in a dielectric fluid that absorbs heat directly. Single-phase immersion uses a pump to circulate fluid; two-phase immersion uses evaporation/condensation. Enables rack densities exceeding 200 kW.","link":"glossary.html#term-immersion-cooling","aliases":["Immersion Cooling"]},"in-row-cooling":{"t":"In-Row Cooling","d":"Cooling units placed between server racks within a row, drawing hot air from the hot aisle and discharging cold air to the cold aisle. In-row coolers reduce the distance between heat source and cooling, improving efficiency for medium-to-high-density deployments (10-30 kW/rack).","link":"glossary.html#term-in-row-cooling","aliases":["In-Row Cooling"]},"incident-management":{"t":"Incident Management","d":"The process of detecting, responding to, and resolving unplanned events that disrupt data center operations. Incident management follows ITIL-based workflows: detection, classification, escalation, resolution, and post-incident review. Critical incidents require defined response times per SLA.","link":"glossary.html#term-incident-management","aliases":["Incident Management"]},"inergen":{"t":"INERGEN (IG-541) ((IG-541))","d":"An inert gas fire suppression agent composed of 52% nitrogen, 40% argon, and 8% CO2. INERGEN reduces oxygen concentration to 12.5% (below combustion threshold) while maintaining breathable conditions for personnel. Zero ozone depletion potential and zero GWP.","link":"glossary.html#term-inergen","aliases":["(IG-541)","INERGEN (IG-541)"]},"infrared":{"t":"Infrared Thermography (IR Scanning) ((IR Scanning))","d":"A predictive maintenance technique using infrared cameras to detect abnormal heat patterns in electrical connections, switchgear, and mechanical equipment. Hot spots indicate loose connections, overloaded circuits, or failing components. Recommended annually for all critical distribution equipment.","link":"glossary.html#term-infrared","aliases":["(IR Scanning)","Infrared Thermography (IR Scanning)"]},"inhibitor-reserve":{"t":"Inhibitor Reserve","d":"The remaining concentration of corrosion inhibitor (e.g. azole) in the secondary coolant, target >100 ppm. A falling reserve signals active corrosion attack and the need to re-dose; it is tracked via quarterly coolant sampling alongside pH, conductivity and glycol percentage.","link":"glossary.html#term-inhibitor-reserve","aliases":["Inhibitor Reserve"]},"intake-depth":{"t":"Intake Depth","d":"How deep the seawater intake sits, which sets the source temperature and therefore the whole cooling capability: typical tropical/subtropical profiles give ~4 °C at 1100 m+, 5 °C at 900 m, 6 °C at 700 m, 8 °C at 500 m, 11 °C at 300 m, and ~16 °C at the surface. The design target of 4–6 °C means intakes at 800–1000 m; going shallower saves HDPE Marine Pipeline cost but warms the source, shrinking the Titanium PHE approach margin and forcing more Trim Chiller hours. Depth also increases Pump Head via longer pipeline friction.","u":"m","table":[["Depth","Typical Temp"],["1100 m+","4.0 °C"],["900 m","5.0 °C"],["700 m","6.0 °C"],["500 m","8.0 °C"],["300 m","11.0 °C"]],"s":"NOAA World Ocean Atlas typical tropical/subtropical profiles","rel":["deep-sea-water-cooling","hdpe-marine-pipeline","pump-head","trim-chiller"],"aliases":["Intake Depth (m)","Intake Depth","intake depth"]},"interconnect":{"t":"Interconnect","d":"A physical or logical connection between two networks, cloud providers, or data center tenants. Interconnect fabrics (like Equinix Fabric or Megaport) enable dynamic, software-defined cross-connections between parties without dedicated physical cables.","link":"glossary.html#term-interconnect","aliases":["Interconnect"]},"interconnection-queue":{"t":"Interconnection Queue","d":"The pipeline of generation and load projects awaiting connection studies and approval from a regional transmission organization (e.g., PJM, MISO, ERCOT). PJM's queue has ballooned to 200+ GW as utility-scale solar/storage and AI-driven data center loads compete for transmission capacity. Average queue time for new generation now exceeds 4 years, contributing to the capacity shortfall PJM forecasts for 2027.","link":"glossary.html#term-interconnection-queue","aliases":["Interconnection Queue"]},"inverter":{"t":"Inverter","d":"An electronic device that converts direct current (DC) to alternating current (AC). In UPS systems, the inverter converts DC from batteries or rectifiers back to clean AC power for IT loads. Modern inverters use IGBT technology with efficiency ratings above 97%.","link":"glossary.html#term-inverter","aliases":["Inverter"]},"iot":{"t":"IoT (Internet of Things) ((Internet of Things))","d":"A network of connected sensors and devices used in data centers for environmental monitoring, asset tracking, and predictive maintenance. IoT sensors measure temperature, humidity, pressure, vibration, and power at granular levels, feeding data to analytics platforms for operational optimization.","link":"glossary.html#term-iot","aliases":["(Internet of Things)","IoT (Internet of Things)"]},"ip-rating":{"t":"IP Rating (Ingress Protection) ((Ingress Protection))","d":"A two-digit code (IEC 60529) indicating an enclosure's protection against solid objects and water. IP54 is common for outdoor data center equipment (dust-protected, splash-proof). IP20 is standard for indoor electrical panels (finger-safe, no water protection).","link":"glossary.html#term-ip-rating","aliases":["(Ingress Protection)","IP Rating (Ingress Protection)"]},"islanding":{"t":"Islanding","d":"Operating a data center independently from the utility grid using on-site generators. Islanding occurs intentionally during planned utility maintenance or automatically when the grid becomes unstable. Anti-islanding protection prevents backfeeding generator power to the utility grid.","link":"glossary.html#term-islanding","aliases":["Islanding"]},"iso":{"t":"ISO Standards (Data Center Relevant) ((Data Center Relevant))","d":"International standards applicable to data centers: ISO 27001 (information security), ISO 22301 (business continuity), ISO 50001 (energy management), ISO 30134 (KPIs for resource efficiency including PUE, REF, WUE). Certification demonstrates operational maturity.","link":"glossary.html#term-iso","aliases":["(Data Center Relevant)","ISO Standards (Data Center Relevant)"]},"ist":{"t":"IST (Integrated Systems Testing) ((Integrated Systems Testing))","d":"The final phase of data center commissioning where all systems (electrical, mechanical, fire, BMS) are tested together under simulated failure conditions. IST validates that automatic transfer, cooling failover, and generator start sequences work correctly as an integrated system rather than in isolation.","link":"glossary.html#term-ist","aliases":["(Integrated Systems Testing)","IST (Integrated Systems Testing)"]},"it-load":{"t":"IT Load","d":"The total electrical power drawn by the IT equipment itself — servers, storage arrays, and network devices — excluding cooling and power-delivery overhead. It is the sizing anchor for the whole facility: cooling capacity, UPS, generators, and Total CAPEX all scale from it, and PUE is defined relative to it. Small/edge sites run 100–500 kW, hyperscale campuses exceed 10 MW; the capex calculator accepts 100 kW to 100 MW.","u":"kW","table":[["Category","Range"],["Small / Edge","100–500 kW"],["Medium","500–2,000 kW"],["Large","2–10 MW"],["Hyperscale","10+ MW"]],"rel":["total-capex","pue","cost-per-kw","rack-density"],"aliases":["IT Load (kW)","IT Load","IT load"]},"jbod":{"t":"JBOD (Just a Bunch of Disks) ((Just a Bunch of Disks))","d":"A storage configuration where multiple hard drives are connected without RAID. Each disk operates independently and appears as a separate volume. JBOD is used in hyperscale environments where software-defined storage handles redundancy at the application layer.","link":"glossary.html#term-jbod","aliases":["(Just a Bunch of Disks)","JBOD (Just a Bunch of Disks)"]},"joule":{"t":"Joule (J) ((J))","d":"The SI unit of energy. 1 Joule = 1 Watt-second. In data centers, energy consumption is typically measured in kilowatt-hours (kWh) where 1 kWh = 3,600,000 J. Joule ratings also indicate surge protector energy absorption capacity.","link":"glossary.html#term-joule","aliases":["(J)","Joule (J)"]},"junction-box":{"t":"Junction Box","d":"An enclosed container for electrical connections that protects wire splices and provides access for maintenance. In data centers, junction boxes are used for under-floor power connections, sensor wiring, and fire alarm circuits. Must be accessible and properly rated for the environment.","link":"glossary.html#term-junction-box","aliases":["Junction Box"]},"kill-switch":{"t":"Kill Switch (Emergency Disconnect) ((Emergency Disconnect))","d":"A manually operated switch that immediately cuts power to equipment or an entire area. Different from EPO in that kill switches may be zone-specific. Used for maintenance isolation and emergency situations. Must be clearly labeled and accessible.","link":"glossary.html#term-kill-switch","aliases":["(Emergency Disconnect)","Kill Switch (Emergency Disconnect)"]},"kraljic-matrix":{"t":"Kraljic Matrix","d":"A 2×2 procurement strategy framework (Peter Kraljic, HBR 1983) that positions items on supply risk (x-axis) versus profit/spend impact (y-axis): Strategic (high-high) → partnership, dual-source; Bottleneck (high risk, low spend) → secure supply, safety stock; Leverage (low risk, high spend) → competitive tender; Non-Critical (low-low) → catalog purchasing. For data center M&E spares, most long-lead equipment (switchgear, transformers, chillers) falls in Strategic or Bottleneck, justifying proactive safety stock and supplier partnership investment.","link":"glossary.html#term-kraljic-matrix","aliases":["Kraljic Matrix"]},"kva":{"t":"kVA (Kilovolt-Ampere) ((Kilovolt-Ampere))","d":"A unit of apparent power equal to 1,000 volt-amperes. Apparent power combines active power (kW) and reactive power (kVAR). kVA = kW / Power Factor. UPS systems and transformers are commonly rated in kVA. A 500 kVA UPS at 0.9 power factor delivers 450 kW of usable power.","link":"glossary.html#term-kva","aliases":["(Kilovolt-Ampere)","kVA (Kilovolt-Ampere)"]},"kw":{"t":"kW (Kilowatt) ((Kilowatt))","d":"A unit of active (real) power equal to 1,000 watts. Data center capacity is typically expressed in kW or MW of IT load. Rack power density is measured in kW/rack, ranging from 5 kW (traditional) to 100+ kW (AI/GPU clusters).","link":"glossary.html#term-kw","aliases":["(Kilowatt)","kW (Kilowatt)"]},"kwh":{"t":"kWh (Kilowatt-Hour) ((Kilowatt-Hour))","d":"A unit of energy equal to one kilowatt of power sustained for one hour. Data center energy consumption is billed in kWh. A 10 MW facility operating at full load consumes 240,000 kWh per day (87.6 million kWh per year). Electricity cost is the largest single OPEX item.","link":"glossary.html#term-kwh","aliases":["(Kilowatt-Hour)","kWh (Kilowatt-Hour)"]},"l2a":{"t":"L2A (Liquid-to-Air CDU) ((Liquid-to-Air CDU))","d":"A Coolant Distribution Unit that rejects the server-side coolant heat directly to room air through an internal air coil, needing no facility water. The key retrofit enabler for direct-to-chip cooling in halls with no chilled-water plumbing — at the cost of lower density and added room heat the CRAH/CRAC must absorb.","link":"glossary.html#term-l2a","aliases":["(Liquid-to-Air CDU)","L2A (Liquid-to-Air CDU)"]},"l2l":{"t":"L2L (Liquid-to-Liquid CDU) ((Liquid-to-Liquid CDU))","d":"A Coolant Distribution Unit that rejects the server-side coolant heat to a facility water loop through a plate heat exchanger. Highest capacity and efficiency — the standard for purpose-built AI halls with a chilled- or condenser-water plant; warm-water classes (ASHRAE W40/W45) enable chiller-less free cooling.","link":"glossary.html#term-l2l","aliases":["(Liquid-to-Liquid CDU)","L2L (Liquid-to-Liquid CDU)"]},"last-time-buy":{"t":"Last-Time-Buy (LTB) ((LTB))","d":"A procurement action taken when a supplier announces end-of-life (EOL) for a component, allowing buyers to purchase sufficient stock to cover the remaining support life before the part becomes unavailable. LTB quantity is calculated as: annualDemand × supportYears × safetyFactor − onHand − openPO. The LTB vs requalify decision compares NPV of stocking through end-of-life against qualifying a replacement part. Part of the DMSMS (Diminishing Manufacturing Sources and Material Shortages) lifecycle management discipline.","link":"glossary.html#term-last-time-buy","aliases":["(LTB)","Last-Time-Buy (LTB)"]},"latency":{"t":"Latency","d":"The time delay between a request and its response, measured in milliseconds. Network latency within a data center is typically sub-millisecond. Edge data centers are deployed closer to end users to reduce latency below 5ms for real-time applications.","link":"glossary.html#term-latency","aliases":["Latency"]},"lcp":{"t":"LCP (Liquid Cooling Package) ((Liquid Cooling Package))","d":"A self-contained liquid cooling unit designed to mount beside or between server racks. LCPs combine a heat exchanger, pump, and controls to manage coolant flow for direct-to-chip or rear-door heat exchanger deployments.","link":"glossary.html#term-lcp","aliases":["(Liquid Cooling Package)","LCP (Liquid Cooling Package)"]},"leaf-spine":{"t":"Leaf-Spine Architecture","d":"A two-tier network topology where every leaf (access) switch connects to every spine (aggregation) switch, providing predictable latency and equal-cost paths. Leaf-spine replaces legacy three-tier designs in modern data centers, supporting east-west traffic patterns common in cloud and virtualized environments.","link":"glossary.html#term-leaf-spine","aliases":["Leaf-Spine Architecture"]},"leak-detection":{"t":"Leak Detection","d":"Sensor systems (cable-based or spot sensors) that detect water or liquid coolant leaks under raised floors, near CRAC units, and around piping. Early leak detection prevents equipment damage and downtime. Modern systems pinpoint leak location within centimeters along the sensing cable.","link":"glossary.html#term-leak-detection","aliases":["Leak Detection"]},"leak-detection-cdu":{"t":"Leak Detection (CDU) ((CDU))","d":"Active leak sensing on a CDU using rope/cable zone sensors plus point/spot sensors at drip trays and the reservoir, interlocked with a pressure/level-drop signal to trigger a latching shutdown. The first line of defence for any liquid-cooled rack; distinct from generic facility leak detection.","link":"glossary.html#term-leak-detection-cdu","aliases":["(CDU)","Leak Detection (CDU)"]},"lifecycle":{"t":"Lifecycle Management","d":"Managing data center assets from procurement through deployment, operation, maintenance, and decommissioning. Lifecycle planning ensures equipment is replaced before end-of-life failures, warranty expirations are tracked, and capacity is refreshed to meet evolving performance and efficiency requirements.","link":"glossary.html#term-lifecycle","aliases":["Lifecycle Management"]},"lighting":{"t":"Lighting (Data Center Lighting) ((Data Center Lighting))","d":"LED lighting systems with occupancy sensors and emergency backup in data halls. Lighting contributes 1-3% of total facility energy. Best practices include motion-activated zones, minimum 500 lux at rack face for maintenance, and emergency lighting per NFPA 101 life safety code requirements.","link":"glossary.html#term-lighting","aliases":["(Data Center Lighting)","Lighting (Data Center Lighting)"]},"lights-out-dc":{"t":"Lights-Out Data Center","d":"A facility designed to operate with minimal or zero continuous on-site human presence. Routine operations (cooling, power, monitoring) are fully automated; humans intervene only for scheduled maintenance windows or emergency dispatch. EdgeConneX has built lights-out into its edge-DC business model; Microsoft Project Natick demonstrated unmanned operation at sea. Mostly aspirational for hyperscale today, but eliminates 15-30% of OpEx in labor when achieved.","link":"glossary.html#term-lights-out-dc","aliases":["Lights-Out Data Center"]},"liquid-cooling":{"t":"Liquid Cooling","d":"A cooling method that uses liquid (water or dielectric fluid) to remove heat directly from IT components. Includes direct-to-chip (cold plates on CPUs/GPUs), rear-door heat exchangers, and full immersion. Liquid cooling is 1,000x more thermally efficient than air per unit volume.","link":"glossary.html#term-liquid-cooling","aliases":["Liquid Cooling"]},"lithium-ion":{"t":"Lithium-Ion Battery (Li-ion) ((Li-ion))","d":"A rechargeable battery chemistry increasingly used in data center UPS systems. Li-ion batteries offer 2-3x longer lifespan (8-15 years vs. 3-5 for VRLA), 70% smaller footprint, faster recharge, and wider temperature tolerance. Higher upfront cost is offset by reduced replacement cycles.","link":"glossary.html#term-lithium-ion","aliases":["(Li-ion)","Lithium-Ion Battery (Li-ion)"]},"load-bank":{"t":"Load Bank","d":"A device that applies an electrical load to a power source (generator, UPS) for testing purposes. Resistive load banks convert electricity to heat. Load bank testing verifies generator capacity, UPS transfer, and battery runtime. Required annually for most compliance standards.","link":"glossary.html#term-load-bank","aliases":["Load Bank"]},"load-factor":{"t":"Load Factor","d":"The ratio of actual power consumed to the maximum power capacity of a system, expressed as a percentage. A data center operating at 6 MW out of 10 MW capacity has a 60% load factor. Optimal load factors balance efficiency against headroom for growth.","link":"glossary.html#term-load-factor","aliases":["Load Factor"]},"loto":{"t":"LOTO (Lockout/Tagout) ((Lockout/Tagout))","d":"A safety procedure requiring the isolation and physical locking of energy sources before equipment maintenance. OSHA 29 CFR 1910.147 mandates LOTO for all servicing of machines where unexpected energization could cause injury. Every data center maintenance event on electrical or mechanical systems requires LOTO.","link":"glossary.html#term-loto","aliases":["(Lockout/Tagout)","LOTO (Lockout/Tagout)"]},"low-voltage":{"t":"Low Voltage (LV) ((LV))","d":"Electrical systems operating at or below 1,000V AC (IEC definition). In data centers, LV distribution typically operates at 400/230V (Europe) or 480/208V (North America). LV switchboards distribute power from transformers to PDUs and mechanical equipment.","link":"glossary.html#term-low-voltage","aliases":["(LV)","Low Voltage (LV)"]},"maintenance-vapor-release":{"t":"Maintenance Vapor Release (Two-Phase Immersion) ((Two-Phase Immersion))","d":"The atmospheric release of PFAS-containing dielectric fluid vapor that occurs every time a two-phase immersion cooling system is opened for scheduled service (pump seal inspections, fluid top-up, server swap). The one published field measurement (2016 DoD/LBNL) recorded 17.1%/yr evaporative loss; against EPA Section 608's 10% sealed-leak benchmark that is roughly 3-15x a tolerated leak. The informal \"20-30x\" figure is best read as a modeled upper bound for the worst-maintained deployments, not a measured constant &mdash; the precise multiplier is unknown because the release is unmetered. Zero federal reporting is required, and EPA TRI applies only to manufacturers of PFAS, not facilities that use it.","link":"glossary.html#term-maintenance-vapor-release","aliases":["(Two-Phase Immersion)","Maintenance Vapor Release (Two-Phase Immersion)"]},"make-up-rate":{"t":"Make-up Rate","d":"The volume of dielectric fluid added to keep a two-phase or immersion system topped up over a year, expressed as a percentage of the installed charge (top-up volume &divide; charge, %/yr). It is the single best operator-side proxy for total fluid loss because it needs no new sensor &mdash; it is purchasing data the facility already collects. Vendor \"sealed-tank\" claims run 1-2%/yr; the only published field measurement (2016 DoD/LBNL) recorded 17.1%/yr. A rising make-up rate is the leading indicator of an unmetered atmospheric PFAS release.","link":"glossary.html#term-make-up-rate","aliases":["Make-up Rate"]},"manifold":{"t":"Manifold (Rack Manifold) ((Rack Manifold))","d":"The rack-level distribution header that splits CDU secondary flow to each cold plate and recombines the return. The flow path is chip cold-plate &rarr; rack manifold &rarr; CDU &rarr; facility water; the manifold sets per-rack flow balance and houses the quick-disconnect couplers.","link":"glossary.html#term-manifold","aliases":["(Rack Manifold)","Manifold (Rack Manifold)"]},"marine-opex":{"t":"Marine OPEX","d":"The recurring cost of operating the seawater side: maintenance at ~3% of marine CAPEX per year, anti-biofouling chlorination dosing (~$6.5 per m³/h of flow per year), and annual ROV pipeline inspection (~$350k/yr). Pumps run at roughly 0.85 load factor, so pumping electricity is the other big line — together these replace the chiller maintenance and refrigerant costs of a conventional plant. Marine OPEX is usually well below the compressor energy it displaces, which is what makes the PUE ≤ 1.15 economics work over the asset life.","u":"USD/yr","rel":["deep-sea-water-cooling","hdpe-marine-pipeline","seawater-filtration","opex"],"aliases":["Marine OPEX","marine maintenance","ROV inspection"]},"market-condition":{"t":"Market Conditions","d":"Current supply-demand dynamics in the construction market at bid time. In a buyer's market (overcapacity) pricing drops ~5%; balanced is the baseline; in a seller's market — the norm during the AI build-out — contractors charge ~+10% premiums because order books are full. Compounds with Contractor Availability and Year Escalation; timing a bid into a cooler market is one of the few free CAPEX levers.","table":[["Condition","Impact"],["Buyer's Market","-5% (overcapacity)"],["Balanced","0% (baseline)"],["Seller's Market","+10% (high demand)"]],"rel":["contractor-availability","year-escalation","delivery-method"],"aliases":["Market Conditions","market conditions","Seller's Market","Buyer's Market"]},"mdb":{"t":"MDB (Main Distribution Board) ((Main Distribution Board))","d":"The primary electrical panel that receives power from the utility transformer and distributes it to sub-distribution boards, UPS systems, and mechanical loads. The MDB contains the main circuit breaker, bus bars, and metering equipment for the facility.","link":"glossary.html#term-mdb","aliases":["(Main Distribution Board)","MDB (Main Distribution Board)"]},"mechanical-plant":{"t":"Mechanical Plant","d":"The collective cooling and ventilation equipment in a data center, including chillers, cooling towers, pumps, air handlers, and piping. The mechanical plant typically consumes 30-40% of total facility energy. Efficient plant design is the largest lever for reducing PUE.","link":"glossary.html#term-mechanical-plant","aliases":["Mechanical Plant"]},"medium-voltage":{"t":"Medium Voltage (MV) ((MV))","d":"Electrical systems operating between 1 kV and 36 kV (IEC definition). Data centers commonly receive utility power at medium voltage (11 kV, 22 kV, or 33 kV) and distribute it through MV switchgear and ring main units before stepping down to LV via transformers.","link":"glossary.html#term-medium-voltage","aliases":["(MV)","Medium Voltage (MV)"]},"meet-me-room":{"t":"Meet-Me Room (MMR) ((MMR))","d":"A dedicated room within a colocation facility where network carriers and tenants interconnect via cross-connects. The meet-me room houses carrier demarcation points, patch panels, and fiber distribution frames. Carrier-neutral MMRs offer the widest choice of network providers.","link":"glossary.html#term-meet-me-room","aliases":["(MMR)","Meet-Me Room (MMR)"]},"megapack":{"t":"Megapack (Tesla)","d":"Tesla's utility-scale battery energy storage system (BESS) rated up to 3.9 MWh per unit. Megapacks are increasingly deployed at data centers for power conditioning, peak shaving, and emergency ride-through. xAI's Colossus campus uses Megapacks to bridge the gap between turbine generation and substation power upgrades, illustrating BESS's role in accelerated DC commissioning.","link":"glossary.html#term-megapack","aliases":["Megapack (Tesla)"]},"memphis-turbine-deployment":{"t":"Memphis Turbine Deployment (xAI Colossus) ((xAI Colossus))","d":"The temporary 35-turbine methane generator deployment that powered xAI's Colossus during its first months of operation while permanent grid power infrastructure was upgraded. Operated without Clean Air Act permits, drawing a $75,000 Shelby County Health Department enforcement action and lawsuits from the Southern Environmental Law Center and NAACP citing environmental-justice violations against the predominantly Black Boxtown community.","link":"glossary.html#term-memphis-turbine-deployment","aliases":["(xAI Colossus)","Memphis Turbine Deployment (xAI Colossus)"]},"metering":{"t":"Metering","d":"The measurement of electrical parameters (voltage, current, power, energy, power factor) at various points in the distribution chain. Accurate metering enables PUE calculation, capacity management, tenant billing, and early detection of electrical anomalies.","link":"glossary.html#term-metering","aliases":["Metering"]},"method-of-procedure":{"t":"MOP (Method of Procedure) ((Method of Procedure))","d":"A detailed, step-by-step document describing how to perform a specific maintenance or change activity in a data center. MOPs include prerequisites, safety requirements, step-by-step instructions, verification checkpoints, and rollback procedures. Required for all activities affecting critical infrastructure.","link":"glossary.html#term-method-of-procedure","aliases":["(Method of Procedure)","MOP (Method of Procedure)"]},"metric-vari-metric":{"t":"METRIC / VARI-METRIC","d":"Multi-echelon inventory optimization models for recoverable spare parts. METRIC (Multi-Echelon Technique for Recoverable Item Control, Sherbrooke 1968) minimises expected backorders across a supply network (sites → depot) for a given spares budget, using Poisson demand and Palm's theorem. VARI-METRIC (Slay 1984) adds variance correction, improving accuracy from ~11% to within 1% of the true optimum. Applied to data center fleet management, METRIC/VARI-METRIC determines the optimal split of spare units between regional hubs and central depot to maximise fleet readiness within budget. Superseded in large-scale applications by full MEIO (Multi-Echelon Inventory Optimisation) solvers.","link":"glossary.html#term-metric-vari-metric","aliases":["METRIC / VARI-METRIC"]},"micro-data-center":{"t":"Micro Data Center","d":"A self-contained, fully enclosed computing environment in a compact form factor (single rack to small room). Micro data centers integrate IT equipment, power, cooling, and security in a pre-engineered unit. Used for edge computing, remote offices, and tactical deployments.","link":"glossary.html#term-micro-data-center","aliases":["Micro Data Center"]},"modular":{"t":"Modular Data Center","d":"A prefabricated, standardized data center unit (container, pod, or skid-mounted) that can be factory-built and deployed rapidly. Modular designs reduce construction time from 18-24 months to 6-12 months and allow incremental capacity scaling.","link":"glossary.html#term-modular","aliases":["Modular Data Center"]},"monitoring":{"t":"Monitoring","d":"Continuous observation of data center systems using sensors, meters, and software platforms. Monitoring covers power (voltage, current, energy), environmental (temperature, humidity), mechanical (chiller status, pump flow), and network (bandwidth, latency) parameters.","link":"glossary.html#term-monitoring","aliases":["Monitoring"]},"monte-carlo":{"t":"Monte-Carlo Simulation","d":"Thousands of model runs (the capex calculator uses 4,000, seeded and reproducible) with the uncertain inputs — construction bid spread, multi-year Escalation, scope growth, or in the DCMOC financial version revenue and cost drivers — drawn randomly from probability distributions each time. The output is a distribution rather than a point estimate, summarized as P10/P50/P90 percentiles: your Contingency should cover the gap between the point estimate and where P90 lands. Powered by RZEngine v2.0 in the capex calculator; the DCMOC Monte Carlo tab applies the same method to IRR and NPV.","rel":["p10-p50-p90","tornado-chart","contingency","sensitivity-matrix","tab-montecarlo"],"aliases":["Monte-Carlo","Monte Carlo","Monte-Carlo range","Monte Carlo simulation"]},"mother-bus":{"t":"Mother Bus","d":"The main busway that runs the length of a data hall, providing overhead power distribution. Individual PDUs tap off the mother bus via plug-in units. Mother bus systems simplify power deployment, reduce cable congestion, and enable non-disruptive capacity additions.","link":"glossary.html#term-mother-bus","aliases":["Mother Bus"]},"mtbf":{"t":"MTBF (Mean Time Between Failures) ((Mean Time Between Failures))","d":"The predicted elapsed time between inherent failures of a system during normal operation, measured in hours. Higher MTBF indicates greater reliability. Enterprise hard drives target 1-2 million hours MTBF. UPS systems target 200,000-500,000 hours. MTBF is a statistical prediction, not a guarantee.","link":"glossary.html#term-mtbf","aliases":["(Mean Time Between Failures)","MTBF (Mean Time Between Failures)"]},"mttr":{"t":"MTTR (Mean Time To Repair) ((Mean Time To Repair))","d":"The average time required to diagnose and repair a failed component, measured from failure detection to service restoration. Lower MTTR improves availability. Strategies to reduce MTTR include spare parts inventory, trained staff on-site, and modular replaceable components. Availability = MTBF / (MTBF + MTTR).","link":"glossary.html#term-mttr","aliases":["(Mean Time To Repair)","MTTR (Mean Time To Repair)"]},"mw":{"t":"MW (Megawatt) ((Megawatt))","d":"A unit of power equal to 1,000 kilowatts (1,000,000 watts). Data center campus capacity is measured in MW of IT load. Enterprise facilities range from 1-20 MW; hyperscale campuses reach 100-500+ MW across multiple buildings.","link":"glossary.html#term-mw","aliases":["(Megawatt)","MW (Megawatt)"]},"n-plus-1":{"t":"N+1 Redundancy","d":"A redundancy configuration where one additional component is installed beyond the minimum required (N) to support the load. If 4 cooling units are needed (N=4), a fifth is added (N+1=5). This allows one unit to fail or undergo maintenance without affecting operations.","link":"glossary.html#term-n-plus-1","aliases":[]},"n-plus-1-redundancy":{"t":"N+1 Redundancy (Marine Systems)","d":"One spare unit beyond the count needed for full load, applied throughout the Deep Sea Water Cooling design: pumps 4+1 (the +1 is design margin beyond the hydraulic minimum), filters N+1, Titanium PHE banks N+1 in parallel, Trim Chillers N+1, while power and controls run 2N. This lets any single pump, screen, or heat-exchanger be serviced with the system at full capacity — the marine equivalent of the electrical Redundancy that defines the facility Tier Classification.","rel":["redundancy","deep-sea-water-cooling","trim-chiller","titanium-phe"],"aliases":["N+1 pumps","N+1 redundancy"]},"n-plus-2":{"t":"N+2 Redundancy","d":"A redundancy configuration with two additional components beyond the minimum required. Provides higher availability than N+1 by allowing simultaneous failure and maintenance events. Common for cooling systems in large data centers where a single unit failure during maintenance must not impact operations.","link":"glossary.html#term-n-plus-2","aliases":["N+2 Redundancy"]},"nec":{"t":"NEC (National Electrical Code) ((National Electrical Code))","d":"NFPA 70, the standard for electrical safety in the United States. The NEC covers wiring methods, overcurrent protection, grounding, and equipment requirements. Article 645 specifically addresses IT equipment rooms and data centers, including provisions for EPO and under-floor wiring.","link":"glossary.html#term-nec","aliases":["(National Electrical Code)","NEC (National Electrical Code)"]},"network-fabric":{"t":"Network Fabric","d":"The underlying network topology connecting all switches, routers, and servers within a data center. Modern fabrics use leaf-spine architectures with equal-cost multipath (ECMP) routing, providing predictable low-latency connectivity between any two endpoints. Replaces traditional three-tier network designs.","link":"glossary.html#term-network-fabric","aliases":["Network Fabric"]},"neutral":{"t":"Neutral Conductor","d":"The return path conductor in an AC electrical system that carries unbalanced current. In data centers with non-linear IT loads, the neutral conductor may carry significant harmonic currents (particularly 3rd harmonic). Oversized or double-neutral conductors are specified to prevent overheating.","link":"glossary.html#term-neutral","aliases":["Neutral Conductor"]},"newsvendor-model":{"t":"Newsvendor Model (Critical-Fractile Model) ((Critical-Fractile Model))","d":"An inventory optimization framework for single-period or slow-moving items that balances under-stock cost (C u ) against over-stock cost (C o ). The optimal stock level Q* satisfies: P(demand ≤ Q*) = C u / (C u + C o ), the \"critical ratio.\" For data center critical spares, C u = downtime cost × MTTR + expedite premium, which is typically far larger than C o = carrying cost over part life, driving the critical ratio close to 1 and recommending generous stocking. The newsvendor model combined with fill-rate safety stock is the standard quantitative approach for critical spare-parts optimisation.","link":"glossary.html#term-newsvendor-model","aliases":["(Critical-Fractile Model)","Newsvendor Model (Critical-Fractile Model)"]},"nfpa":{"t":"NFPA (National Fire Protection Association) ((National Fire Protection Association))","d":"The organization that publishes fire safety codes including NFPA 70 (National Electrical Code), NFPA 75 (IT equipment protection), NFPA 76 (telecom facilities fire protection), and NFPA 2001 (clean agent fire suppression). These codes define data center fire safety requirements.","link":"glossary.html#term-nfpa","aliases":["(National Fire Protection Association)","NFPA (National Fire Protection Association)"]},"nfpa-855":{"t":"NFPA 855","d":"The NFPA standard for the Installation of Stationary Energy Storage Systems &mdash; governs lithium-ion battery siting, unit spacing, fire-rated separation, explosion control, and gas detection (alarm at 25% of the lower flammable limit). The key code for data-center Li-ion BBU / UPS battery rooms, working alongside UL 9540 / 9540A and IEC 62619.","link":"glossary.html#term-nfpa-855","aliases":["NFPA 855"]},"noael-loael":{"t":"NOAEL & LOAEL","d":"No-Observed-Adverse-Effect-Level and Lowest-Observed-Adverse-Effect-Level &mdash; the occupant-safety thresholds for a clean agent (NFPA 2001). The design concentration must not exceed the NOAEL in spaces people occupy: Novec 1230 NOAEL 10%, FM-200 NOAEL 9% / LOAEL 10.5%, IG-541 NOAEL 43% / LOAEL 52%.","link":"glossary.html#term-noael-loael","aliases":["NOAEL & LOAEL"]},"noc":{"t":"NOC (Network Operations Center) ((Network Operations Center))","d":"A centralized location from which IT and network infrastructure is monitored, managed, and controlled 24/7. NOC staff respond to alarms, manage incidents, coordinate maintenance, and ensure service level agreements are met. Modern NOCs use wall-mounted dashboards and DCIM integration.","link":"glossary.html#term-noc","aliases":["(Network Operations Center)","NOC (Network Operations Center)"]},"nocaas":{"t":"NOCaaS (NOC-as-a-Service) ((NOC-as-a-Service))","d":"A managed-service model where a third-party provider delivers 24/7 network and facility monitoring, alerting, and incident management. Typical contracts run $2K-$25K/month per facility versus $400K-$1.2M/year for an equivalent in-house NOC team. Major providers include INOC, Park Place Technologies, Pomeroy, and ConnectWise. Integration windows are typically 30-90 days, making NOCaaS the fastest substitution-tier lever for remote-ops staffing pressure.","link":"glossary.html#term-nocaas","aliases":["(NOC-as-a-Service)","NOCaaS (NOC-as-a-Service)"]},"noi":{"t":"NOI (Net Operating Income)","d":"Revenue minus operating expenses, before debt service, income tax, Depreciation, and capital expenditure — the clean measure of what the asset itself earns. NOI is the numerator of both DSCR (lender view) and the Cap Rate valuation (buyer view), making it the single most consequential line in the operating model. It is built from Revenue per kW x occupancy minus the OPEX stack, so the Occupancy Ramp and energy costs move it directly.","f":"NOI = Operating Revenue - Operating Expenses (before debt, tax, depreciation)","u":"USD/yr","rel":["dscr","cap-rate","ebitda","revenue-per-kw","opex"],"aliases":["NOI","Net Operating Income"]},"novec":{"t":"Novec 1230 (FK-5-1-12) ((FK-5-1-12))","d":"A clean agent fire suppressant manufactured by 3M with a global warming potential of 1 (versus 3,220 for FM-200). Novec 1230 absorbs heat to extinguish fires, is safe for occupied spaces, and leaves no residue. It is the most common FM-200 replacement in new data center builds. Note: a separate 3M product, Novec 7000 , is used for two-phase immersion cooling and was discontinued by 3M at end of 2025; both are PFAS compounds but serve different DC applications.","link":"glossary.html#term-novec","aliases":["(FK-5-1-12)","Novec 1230 (FK-5-1-12)"]},"novec-7000":{"t":"Novec 7000 (HFE-7000, 3M) ((HFE-7000, 3M))","d":"A two-phase immersion cooling fluid manufactured by 3M with a 34&deg;C boiling point and 270 hPa vapor pressure (8.4&times; faster evaporation than water). Novec 7000 is a PFAS compound; 3M announced its exit from PFAS production in December 2022 and completed wind-down by end of 2025. The installed base in hyperscale and colocation deployments runs on stockpiled supply with no fully-equivalent replacement at scale; current alternatives are Chemours Opteon SF/2P50 and Solvay Galden HT .","link":"glossary.html#term-novec-7000","aliases":["(HFE-7000, 3M)","Novec 7000 (HFE-7000, 3M)"]},"nps":{"t":"NPS (Net Promoter Score) ((Net Promoter Score))","d":"A customer satisfaction metric used by colocation and managed service providers. Customers rate likelihood of recommending the service on a 0-10 scale. Score = % Promoters (9-10) minus % Detractors (0-6). Industry-leading data center operators target NPS above 50.","link":"glossary.html#term-nps","aliases":["(Net Promoter Score)","NPS (Net Promoter Score)"]},"npsh":{"t":"NPSH (Net Positive Suction Head) ((Net Positive Suction Head))","d":"The margin (in metres) between the pressure at a pump's suction and the coolant's vapour pressure. NPSH-available must exceed NPSH-required by &ge;10–20% or the pump cavitates — eroding impellers and collapsing flow. Set by system pressure, static head, suction losses and fluid temperature.","link":"glossary.html#term-npsh","aliases":["(Net Positive Suction Head)","NPSH (Net Positive Suction Head)"]},"npv":{"t":"NPV (Net Present Value)","d":"The sum of all project cash flows discounted back to today at the discount rate (usually WACC), minus the initial investment — the direct dollar answer to 'does this create value'. Positive NPV means the project earns more than its cost of capital; the equivalent rate form of the same test is comparing Project IRR to the hurdle. Unlike IRR, NPV handles non-conventional cash flows cleanly and scales with project size, which is why the Financial module's Sensitivity Matrix reports both NPV and IRR per cell.","f":"NPV = sum( CF_t / (1 + r)^t ) - Initial Investment","u":"USD","rel":["wacc","project-irr","payback-period","terminal-value","sensitivity-matrix"],"aliases":["NPV","Net Present Value"]},"occupancy-ramp":{"t":"Occupancy Ramp","d":"The year-by-year fill schedule from opening day to stabilized occupancy — typically 2–4 years for colocation, or nearly instant with a Hyperscaler Pre-Lease. The ramp shape dominates early cash flows: slow fill means years of fixed OPEX and debt service against partial Revenue per kW, depressed DSCR, and worse Partial-Load PUE. It is one of the highest-impact variables in the Tornado Chart, and editable per-year in the DCMOC financial model.","u":"% occupied per year","rel":["revenue-per-kw","dscr","partial-load-pue","hyperscaler-prelease","tornado-chart"],"aliases":["Occupancy Ramp","occupancy ramp","fill rate"]},"ocp":{"t":"OCP (Open Compute Project) ((Open Compute Project))","d":"An initiative founded by Facebook/Meta to share open-source hardware designs for data center servers, storage, and networking. OCP designs optimize for efficiency and cost by removing unnecessary features (bezels, proprietary connectors). Widely adopted by hyperscale and large enterprise operators.","link":"glossary.html#term-ocp","aliases":["(Open Compute Project)","OCP (Open Compute Project)"]},"off-gassing":{"t":"Off-Gassing (Battery Vent Gas) ((Battery Vent Gas))","d":"The release of flammable and toxic vent gases (hydrogen, carbon monoxide, CO 2 , electrolyte vapour) from a lithium-ion cell before and during thermal runaway. Because the vent-gas volume vastly exceeds any room's flammable limit, early off-gas detection (H 2 /CO sensors per UL 9540A / NFPA 855) plus ventilation is the first line of defence &mdash; ahead of suppression.","link":"glossary.html#term-off-gassing","aliases":["(Battery Vent Gas)","Off-Gassing (Battery Vent Gas)"]},"ohm":{"t":"Ohm (Resistance) ((Resistance))","d":"The SI unit of electrical resistance. Ohm's Law (V = I x R) governs current flow. In data centers, insulation resistance testing (megohm testing) verifies cable insulation integrity. Minimum acceptable insulation resistance values depend on voltage rating and cable age.","link":"glossary.html#term-ohm","aliases":["(Resistance)","Ohm (Resistance)"]},"on-site-generation":{"t":"On-site Generation","d":"Electrical power produced at the data center campus using generators, fuel cells, solar panels, or micro-turbines. On-site generation provides backup power and can supplement or replace utility supply. Some hyperscale operators deploy dedicated natural gas power plants for baseload power.","link":"glossary.html#term-on-site-generation","aliases":[]},"onsite-renewable":{"t":"On-Site Renewable Generation","d":"On-site solar PV and/or battery energy storage (BESS) reducing grid dependency at the cost of added CAPEX: rooftop solar runs roughly $1.2M/MW installed, solar + BESS roughly $2.5M/MW. BESS (screening basis ~$180/kWh installed, ~88% round-trip efficiency) can double as UPS reserve and peak-shaving asset. On-site generation improves CUE (carbon intensity) and hedges the electricity rate behind the Annual Energy Cost, but land take (~1.2 ha/MWp for solar) usually caps it well below full facility load.","table":[["Option","Cost Addition"],["None","$0"],["Rooftop Solar","~$1.2M/MW"],["Solar + BESS","~$2.5M/MW"]],"s":"Lazard LCOE+ 2025, IRENA 2024, BNEF BESS 2026 (screening-grade)","rel":["annual-energy-cost","cue","ups-type","tab-carbon"],"aliases":["On-Site Renewable","On-Site Generation","BESS","Rooftop Solar"]},"open-transition":{"t":"Open Transition Transfer","d":"A power transfer method where the load is momentarily disconnected from one source before connecting to another (break-before-make). Open-transition ATS creates a brief interruption (10-20ms) during transfer. The UPS bridges this gap to maintain continuous power to IT equipment.","link":"glossary.html#term-open-transition","aliases":["Open Transition Transfer"]},"opex":{"t":"OPEX (Operating Expenditure)","d":"The recurring cost of running the facility: electricity (usually 40–60% of the stack — see Annual Energy Cost), staffing, Maintenance contracts, water, insurance, security, and property taxes. OPEX compounds at the OPEX Growth rate and, over a 10–15 year hold, typically exceeds the original CAPEX — which is why efficiency (PUE) and maintenance strategy dominate lifetime economics. Revenue minus OPEX is NOI, the engine of every valuation and coverage metric.","u":"USD/yr","rel":["capex","annual-energy-cost","opex-growth","noi","tco","tab-maint"],"aliases":["OPEX","Operating Expenditure","operating expenses"]},"opex-growth":{"t":"OPEX Growth","d":"The annual escalation rate applied to operating costs — energy, staffing, Maintenance, insurance — typically modeled at 2–4%/yr. The margin story lives in the spread between OPEX Growth and revenue Escalation: contracts that escalate at CPI while energy costs spike compress NOI and DSCR over the hold. Energy usually dominates the OPEX stack, so a power-price hedge or On-Site Renewable can matter more than every other cost line combined.","u":"%/yr","rel":["opex","escalation","noi","annual-energy-cost"],"aliases":["OPEX Growth","opex growth","cost escalation rate"]},"orm":{"t":"ORM (Operations and Maintenance) ((Operations and Maintenance))","d":"The ongoing activities required to keep data center infrastructure functioning reliably, including preventive maintenance, corrective repairs, inspections, testing, and documentation. O&M programs follow manufacturer recommendations and industry standards (NFPA 70B, ASHRAE 180).","link":"glossary.html#term-orm","aliases":["(Operations and Maintenance)","ORM (Operations and Maintenance)"]},"outage":{"t":"Outage (Downtime) ((Downtime))","d":"An unplanned interruption to data center services. Uptime Institute reports that 60% of outages cost over $100,000 and 15% exceed $1M. Leading causes include power failures (43%), cooling failures (15%), network outages (13%), and human error (22%).","link":"glossary.html#term-outage","aliases":["(Downtime)","Outage (Downtime)"]},"outfall-diffuser":{"t":"Outfall Diffuser","d":"The multi-port discharge structure (~$1.8M reference cost) that returns warmed seawater to the ocean while rapidly mixing it to meet the environmental limit — typically ΔT ≤ 5 °C at the edge of the mixing zone. Port sizing, spacing, and discharge depth are set by dilution modeling in the environmental permit; a well-designed diffuser is what keeps the thermal plume from stressing local ecosystems and keeps the discharge consent defensible. Paired with the intake structure at the other end of the HDPE Marine Pipeline.","rel":["seawater-delta-t","hdpe-marine-pipeline","entrainment"],"aliases":["Outfall Diffuser","outfall diffuser","diffuser"]},"over-provisioning":{"t":"Over-provisioning","d":"Deploying more infrastructure capacity than currently needed to accommodate future growth or unexpected demand spikes. While providing headroom, over-provisioning increases CAPEX and reduces efficiency. Best practice is modular deployment to balance readiness with capital efficiency.","link":"glossary.html#term-over-provisioning","aliases":["Over-provisioning"]},"overhead":{"t":"Overhead (Facility Overhead) ((Facility Overhead))","d":"Energy consumed by non-IT systems including cooling, power distribution losses, lighting, and security. Overhead is the difference between total facility power and IT load. PUE quantifies this: a PUE of 1.5 means 50% overhead energy relative to IT load.","link":"glossary.html#term-overhead","aliases":["(Facility Overhead)","Overhead (Facility Overhead)"]},"p10-p50-p90":{"t":"P10 / P50 / P90 Percentiles","d":"Three points on the Monte-Carlo output distribution: P10 = only 10% of simulated outcomes come in below this (optimistic case), P50 = the median (most-likely), P90 = 90% of outcomes fall below it (conservative case — for a cost metric, only 10% of scenarios exceed it). Lenders and investment committees typically underwrite at P90 cost and P50-or-worse revenue; the P90/P10 spread is a direct measure of how uncertain the estimate really is. If your budget sits at P50 with no Contingency, you have roughly a coin-flip of overrunning.","table":[["Percentile","Reading (cost metric)"],["P10","Optimistic — 10% chance of coming in lower"],["P50","Median / most-likely"],["P90","Conservative — 90% of outcomes below"]],"rel":["monte-carlo","contingency","tornado-chart"],"aliases":["P10","P50","P90","P10/P50/P90"]},"partial-load-pue":{"t":"Partial-Load PUE","d":"PUE measured at less than design IT load — and almost always worse than nameplate, because fixed overheads (transformers, always-on fans, UPS losses) spread over fewer IT kilowatts. A facility rated PUE 1.3 at full load may run 1.6+ at 30% occupancy, which is exactly the early years of an Occupancy Ramp; this is why modeled Annual Energy Cost should use load-dependent PUE curves, not the brochure number. Modular plant deployment (adding cooling and UPS blocks with load) is the standard mitigation.","rel":["pue","occupancy-ramp","annual-energy-cost","ppue"],"aliases":["Partial-Load PUE","partial load PUE"]},"payback-period":{"t":"Payback Period","d":"How many years until cumulative cash inflows recover the initial investment — the simplest capital-recovery metric. Data center builds typically pay back in 6–10 years undiscounted depending on Revenue per kW and Occupancy Ramp speed. Its weakness is ignoring the time value of money and everything after breakeven (including Terminal Value); use the Discounted Payback and NPV alongside it rather than instead of them.","f":"Payback = years until cumulative cash flow >= initial investment","u":"years","rel":["discounted-payback","npv","total-capex"],"aliases":["Payback Period","payback period","payback"]},"pdu":{"t":"PDU (Power Distribution Unit) ((Power Distribution Unit))","d":"A device that distributes electric power to server racks. Floor-standing PDUs (transformer-based) step down voltage and distribute to rack-level units. Rack PDUs (intelligent/metered) provide per-outlet monitoring and switching. Typical rack PDUs deliver 5-22 kW per unit.","link":"glossary.html#term-pdu","aliases":["(Power Distribution Unit)","PDU (Power Distribution Unit)"]},"pdu-type":{"t":"PDU Type (Power Distribution Unit)","d":"The rack-level power strips that feed servers. Basic metered PDUs (~$800/rack) only distribute and show aggregate load; intelligent monitored PDUs (~$1,500/rack) add per-outlet metering feeding DCIM/CBM analytics; intelligent + switched (~$2,500/rack) adds remote outlet control for stranded-capacity recovery and remote reboot. Per-outlet visibility becomes critical at high Rack Density where a single overloaded circuit can trip a whole AI pod.","table":[["Type","Cost per Rack"],["Basic Metered","~$800/rack"],["Intelligent (monitored)","~$1,500/rack"],["Intelligent + Switched","~$2,500/rack"]],"rel":["rack-density","power-distribution","tab-cbm"],"aliases":["PDU Type","PDU","Power Distribution Unit"]},"perforated-tile":{"t":"Perforated Tile","d":"A raised floor tile with holes or slots that allows conditioned air to flow from the under-floor plenum into the cold aisle. Tile open area ranges from 25% to 80%, controlling airflow volume. Directional tiles, dampered tiles, and variable-flow tiles provide precise air delivery to match rack demands.","link":"glossary.html#term-perforated-tile","aliases":["Perforated Tile"]},"pfas":{"t":"PFAS (Per- and Polyfluoroalkyl Substances) ((Per- and Polyfluoroalkyl Substances))","d":"A family of 12,000+ synthetic compounds containing carbon-fluorine bonds, valued in data centers for two-phase immersion cooling fluids (Novec 7000, Galden HT, Fluorinert FC-40/FC-72), PTFE/FEP cable jackets, and legacy fire suppression. PFAS are environmentally persistent (\"forever chemicals\") and bioaccumulative; EPA finalized a 4 ppt MCL for PFOA and PFOS in 2024. The DC industry's primary release pathway is maintenance vapor release, which is unmeasured and unreported.","link":"glossary.html#term-pfas","aliases":["(Per- and Polyfluoroalkyl Substances)","PFAS (Per- and Polyfluoroalkyl Substances)"]},"pjm-interconnection":{"t":"PJM Interconnection","d":"The largest regional transmission organization (RTO) in North America, coordinating wholesale electricity for 65 million people across 13 states and DC. PJM operates the Reliability Pricing Model (RPM) capacity auction, manages the interconnection queue, and forecasts a 6 GW capacity shortfall by 2027 driven significantly by data center load growth in Northern Virginia, Ohio, and Pennsylvania.","link":"glossary.html#term-pjm-interconnection","aliases":["PJM Interconnection"]},"plenum":{"t":"Plenum","d":"An enclosed space used for airflow distribution. Under-floor plenums deliver cold air through perforated tiles to the cold aisle. Overhead plenums (ceiling return) collect hot air. Plenum depth, obstructions, and tile placement directly affect airflow uniformity and cooling effectiveness.","link":"glossary.html#term-plenum","aliases":["Plenum"]},"pm":{"t":"Preventive Maintenance (PM) ((PM))","d":"Scheduled maintenance activities performed to reduce the probability of equipment failure. PM tasks include filter replacement, belt inspection, electrical connection torquing, battery testing, and calibration. Adherence to PM schedules is critical for maintaining warranty coverage and Uptime Tier certification.","link":"glossary.html#term-pm","aliases":["(PM)","Preventive Maintenance (PM)"]},"pm-fee":{"t":"Project Management Fee","d":"Owner's project management and construction management cost, typically 3–8% of construction value (5% midpoint). Covers schedule control, vendor coordination, quality assurance, and commissioning oversight — cheap insurance on a project where a missed Transformer Lead Time or failed integrated systems test costs far more. Lower when using EPC turnkey Delivery Method (contractor absorbs coordination), higher for multi-phase Capacity Plan builds.","u":"% of construction cost","rel":["design-fee","delivery-method","contingency"],"aliases":["Project Management","PM Fee","project management fee"]},"power-chain":{"t":"Power Chain","d":"The complete path of electrical power from utility entrance to server power supply. A typical chain: utility transformer, HV switchgear, MV/LV transformer, main switchboard, UPS, PDU, rack PDU, server PSU. Each stage introduces conversion losses and potential failure points.","link":"glossary.html#term-power-chain","aliases":["Power Chain"]},"power-density":{"t":"Power Density","d":"The amount of electrical power consumed per unit area (W/sqm) or per rack (kW/rack). Traditional data centers design for 5-8 kW/rack; modern AI/HPC deployments require 40-100+ kW/rack. Power density drives cooling strategy, structural requirements, and electrical distribution design.","link":"glossary.html#term-power-density","aliases":[]},"power-distribution":{"t":"Power Distribution Method","d":"How power travels from switchgear to the PDUs on the floor. Overhead cable tray is cheapest (-8%) but less flexible for moves and changes; busway (busbar trunking) is the industry-standard baseline for large facilities with tap-off flexibility; underground conduit adds ~+15% for cable pits and trenching but suits campus layouts; mixed bus + underground (+8%) fits multi-building sites. Interacts with Floor Construction (underfloor routing needs raised floor).","table":[["Method","Cost Impact"],["Overhead Cable Tray","-8% (cheapest, less flexible)"],["Busway","Baseline (industry standard)"],["Underground Conduit","+15% (cable pits, trenching)"],["Mixed (Bus + Underground)","+8% (campus/multi-building)"]],"rel":["pdu-type","floor-type","cabling-type"],"aliases":["Power Distribution","Power Distribution Method","Busway"]},"power-factor":{"t":"Power Factor (PF) ((PF))","d":"The ratio of active power (kW) to apparent power (kVA). Power factor of 1.0 means all power performs useful work. Modern server PSUs achieve PF above 0.99. Poor power factor (below 0.9) wastes capacity in transformers and conductors, and may incur utility penalties.","link":"glossary.html#term-power-factor","aliases":["(PF)","Power Factor (PF)"]},"power-whip":{"t":"Power Whip","d":"A short, pre-terminated cable assembly connecting a floor-standing PDU or busway tap-off to a rack PDU. Whips use plug-and-socket connections for rapid deployment and reconfiguration. Common connector types include IEC 60309, NEMA L6-30, and Saf-D-Grid for high-density applications.","link":"glossary.html#term-power-whip","aliases":["Power Whip"]},"ppa":{"t":"PPA (Power Purchase Agreement) ((Power Purchase Agreement))","d":"A long-term contract (10-25 years) between a data center operator and a renewable energy generator to purchase electricity at a fixed price. PPAs enable operators to claim 100% renewable energy and hedge against utility price volatility. Virtual PPAs provide financial benefits without physical power delivery.","link":"glossary.html#term-ppa","aliases":["(Power Purchase Agreement)","PPA (Power Purchase Agreement)"]},"ppue":{"t":"pPUE (Partial Power Usage Effectiveness)","d":"PUE measured for one subsystem or zone rather than the whole facility — for Deep Sea Water Cooling, the cooling pPUE counts seawater pump power, facility-water loop pumps (~38% of seawater pump power), and CDU pumps (~10%) against IT load. Because there are no compressors, cooling pPUE lands far below chiller plants and holds the facility PUE at ≤ 1.15 (including ~5% electrical distribution losses). Comparing pPUE across subsystems shows exactly where the overhead watts go.","f":"pPUE = (subsystem overhead energy + IT energy) / IT energy","rel":["pue","pump-head","deep-sea-water-cooling","partial-load-pue"],"aliases":["pPUE","partial PUE"]},"pre-action":{"t":"Pre-Action Sprinkler","d":"A fire sprinkler system where pipes are normally dry and require two triggers to activate: (1) a detection system confirms fire, filling pipes with water, and (2) individual sprinkler heads open when heat melts the fusible link. This dual-action design prevents accidental water discharge in data centers.","link":"glossary.html#term-pre-action","aliases":["Pre-Action Sprinkler"]},"predictive-maintenance":{"t":"Predictive Maintenance (PdM) ((PdM))","d":"Maintenance strategy using condition monitoring data (vibration, thermal, electrical) to predict equipment failures before they occur. PdM techniques include infrared thermography, ultrasonic testing, oil analysis, and battery impedance testing. Reduces unplanned downtime by 30-50% compared to reactive maintenance.","link":"glossary.html#term-predictive-maintenance","aliases":["(PdM)","Predictive Maintenance (PdM)"]},"primary-switchgear":{"t":"Primary Switchgear","d":"The main high-voltage or medium-voltage switching and protection equipment at the utility entrance point. Primary switchgear contains circuit breakers, bus bars, instrument transformers, and protection relays. It controls the incoming utility supply and generator paralleling.","link":"glossary.html#term-primary-switchgear","aliases":["Primary Switchgear"]},"project-irr":{"t":"Project IRR (Unlevered IRR)","d":"The internal rate of return on total invested capital before any financing — the project's intrinsic economics independent of how it is funded. Comparing Project IRR against WACC is the go/no-go test (a 12% hurdle is a common data center screen); the gap between Project IRR and the cost of debt is what leverage converts into extra Equity IRR. Because it strips out capital-structure choices, it is the right metric for ranking sites in the Portfolio module.","f":"IRR: rate where NPV of unlevered project cash flows = 0","u":"%","rel":["equity-irr","wacc","npv","tab-portfolio"],"aliases":["Project IRR","unlevered IRR"]},"psu":{"t":"PSU (Power Supply Unit) ((Power Supply Unit))","d":"The component within a server that converts AC power to the DC voltages required by internal components (12V, 5V, 3.3V). Efficient PSUs are rated 80 PLUS (Bronze through Titanium), with Titanium achieving 96% efficiency at 50% load. Redundant PSUs (1+1) prevent single-PSU failure from downing a server.","link":"glossary.html#term-psu","aliases":["(Power Supply Unit)","PSU (Power Supply Unit)"]},"pue":{"t":"PUE (Power Usage Effectiveness)","d":"The headline data center efficiency metric: total facility power divided by IT equipment power, so 1.0 is theoretical perfection and everything above it is overhead (mostly cooling, then distribution losses). Industry average sits around 1.55; efficient facilities run 1.2–1.4; best-in-class free-cooled or Deep Sea Water Cooling designs achieve below 1.2 (the DSWC reference designs to ≤ 1.15). Every 0.1 of PUE on a 10 MW facility is roughly 8.76 GWh/yr — PUE feeds straight into Annual Energy Cost, CUE, and the Carbon/ESG story.","f":"PUE = Total Facility Power / IT Equipment Power","table":[["Class","PUE"],["Industry average","~1.55"],["Efficient","1.2-1.4"],["Best-in-class","<1.2"],["Deep-sea design","≤1.15"]],"rel":["dcie","partial-load-pue","ppue","annual-energy-cost","cue","deep-sea-water-cooling"],"aliases":["PUE","Power Usage Effectiveness","Estimated PUE"]},"pump-head":{"t":"Pump Head (Seawater Pumping)","d":"The total pressure the seawater pumps must develop, combining static lift (~15 m base) plus pipeline friction (~12 m per km of pipeline). The reference design uses 4 duty + 1 standby pumps rated 2.9 m³/s at 60 m head, roughly 2,000 kW each — pumping is the dominant energy user in a chiller-less system and the main term in its pPUE. Efficiencies stack multiplicatively (pump 0.87 x motor 0.96 x VFD 0.97 ≈ 0.81; poster basis uses 0.85 combined), so every point of pump efficiency bought at CAPEX time pays back for 25+ years.","f":"Pump power (W) = rho x g x Head x Flow / eff_total","u":"m","rel":["seawater-flow","ppue","hdpe-marine-pipeline","n-plus-1-redundancy"],"aliases":["Pump Head","pump head","seawater pumps"]},"qos":{"t":"QoS (Quality of Service) ((Quality of Service))","d":"Network traffic management policies that prioritize critical data flows over less important ones. QoS mechanisms include traffic classification, bandwidth allocation, and congestion management. Essential for ensuring consistent performance of latency-sensitive applications in shared data center networks.","link":"glossary.html#term-qos","aliases":["(Quality of Service)","QoS (Quality of Service)"]},"quarter-turn":{"t":"Quarter-Turn Fastener","d":"A quick-release fastener used on server rack doors, side panels, and blanking panels. Quarter-turn fasteners enable rapid access without tools, improving maintenance speed. Common in high-density environments where frequent hardware changes occur.","link":"glossary.html#term-quarter-turn","aliases":["Quarter-Turn Fastener"]},"quick-disconnect":{"t":"Quick-Disconnect (QD / UQD / UQDB) ((QD / UQD / UQDB))","d":"A drip-free coupling that connects and disconnects liquid-cooling lines without draining the loop. OCP's UQD (Universal Quick Disconnect) and UQDB (blind-mate) standardise coupler dimensions and performance so parts interoperate across vendors — typically 100 psi working / 300 psi burst, &ge;5,000 mating cycles, ~0.02-0.07 mL dripless spillage; UQDB adds &plusmn;1 mm blind-mate tolerance for rack insertion. Never mix QD standards across a loop.","link":"glossary.html#term-quick-disconnect","aliases":["(QD / UQD / UQDB)","Quick-Disconnect (QD / UQD / UQDB)"]},"r1234ze":{"t":"R-1234ze(E)","d":"An ultra-low-GWP hydrofluoroolefin (HFO) with GWP 7 — effectively future-proof against both the AIM Act and EU F-Gas thresholds — used in centrifugal and screw chillers. It is mildly flammable (A2L, ~3% mitigation capex) with a small efficiency penalty (COP index 0.96) and a low 2%/yr modeled leak rate. It is the engine's auto-pick for Deep Sea Water Cooling Trim Chillers, where the few hundred annual run-hours make its near-zero climate footprint essentially free.","table":[["Property","Value"],["GWP (AR4)","7"],["Safety class","A2L"],["COP index","0.96"]],"rel":["a2l","gwp","trim-chiller","refrigerant"],"aliases":["R-1234ze(E)","R-1234ze","R1234ze","HFO"]},"r134a":{"t":"R-134a","d":"The baseline centrifugal-chiller refrigerant (COP index 1.00 — everything else is measured against it), non-flammable A1 with GWP 1430. It remains common in large water-cooled chillers but is being phased down under the Kigali Amendment HFC schedule; R-513A is the low-GWP drop-in replacement (~3% capacity/efficiency penalty) and R-1234ze the clean-sheet successor. Typical modeled leak rate 3%/yr with 0.20 kg charge per kWth.","table":[["Property","Value"],["GWP (AR4)","1430"],["Safety class","A1"],["COP index","1.00 (baseline)"]],"rel":["r513a","r1234ze","gwp","cop"],"aliases":["R-134a","R134a"]},"r290-propane":{"t":"R-290 (Propane)","d":"Natural-refrigerant propane: GWP 3, excellent efficiency (COP index 1.00), and the smallest charge requirement in the database (0.05 kg/kWth). The catch is class A3 — highly flammable — which imposes strict charge limits and confines it to outdoor or rooftop packaged units well away from occupied space, modeled as a ~6% capex premium. Attractive for modular outdoor chiller farms where the flammability zoning is free.","table":[["Property","Value"],["GWP (AR4)","3"],["Safety class","A3"],["COP index","1.00"],["Capex premium","+6%"]],"rel":["ashrae-34-safety-class","gwp","cop"],"aliases":["R-290 Propane","R-290","R290","propane"]},"r410a":{"t":"R-410A","d":"The dominant legacy refrigerant in DX CRAC units and packaged air conditioning — non-flammable A1, but with GWP 2088, among the worst climate profiles in service. The US AIM Act restricts GWP > 700 in new equipment from 2025 and the EU F-Gas phase-down is squeezing supply, so new builds should treat R-410A as end-of-life technology; R-454B is its designated successor in new DX equipment. Typical modeled leak rate 4%/yr with 0.15 kg charge per kWth — the highest Scope-1 leakage burden in the database.","table":[["Property","Value"],["GWP (AR4)","2088"],["Safety class","A1"],["COP index","0.95"],["Typical leak","4%/yr"]],"rel":["gwp","ashrae-34-safety-class","refrigerant","cop"],"aliases":["R-410A","R410A"]},"r513a":{"t":"R-513A","d":"A lower-GWP azeotropic blend (GWP 631, non-flammable A1) designed as a drop-in replacement for R-134a in existing chillers, accepting roughly a 3% capacity/efficiency penalty (COP index 0.97). It is the pragmatic retrofit path: no equipment change, no flammability mitigation, and a 56% GWP cut — though it still exceeds the EU F-Gas GWP > 150 trajectory, making it transitional rather than final. New equipment increasingly skips straight to R-1234ze.","table":[["Property","Value"],["GWP (AR4)","631"],["Safety class","A1"],["COP index","0.97"]],"rel":["r134a","r1234ze","gwp"],"aliases":["R-513A","R513A"]},"r717-ammonia":{"t":"R-717 (Ammonia)","d":"The zero-GWP industrial refrigerant with the best cycle efficiency in the database (COP index 1.04) and a century of industrial track record. Its constraint is toxicity: safety class B2L requires machine-room isolation, gas detection, and occupied-space charge limits per IIAR and EN 378, modeled as a ~7% capex premium. Compelling for large central plants where the machine room is remote from white space and the efficiency gain compounds across megawatts.","table":[["Property","Value"],["GWP (AR4)","0"],["Safety class","B2L"],["COP index","1.04"],["Capex premium","+7%"]],"rel":["b2l","gwp","cop"],"aliases":["R-717 Ammonia","R-717","R717","ammonia"]},"rack":{"t":"Rack (Server Rack / Cabinet) ((Server Rack / Cabinet))","d":"A standardized metal frame for mounting IT equipment. Standard width is 19 inches (482.6mm) per EIA-310. Heights are 42U or 48U. Depths range from 900mm-1200mm. Open-frame racks suit low-density environments; enclosed cabinets provide security and better airflow management.","link":"glossary.html#term-rack","aliases":["(Server Rack / Cabinet)","Rack (Server Rack / Cabinet)"]},"rack-density":{"t":"Rack Density","d":"Power consumption per rack, the single strongest driver of the cooling architecture. Standard racks at 5–7 kW are fine on air cooling; 10–15 kW needs enhanced airflow or in-row units; 20–30 kW requires in-row or rear-door heat exchangers (RDHX); AI/HPC racks at 50–100 kW demand direct liquid cooling (DLC). Higher density shrinks White Space per megawatt but concentrates heat, raising Cooling Type CAPEX per rack while lowering building cost per kW.","u":"kW/rack","table":[["Density","Cooling Needs"],["Standard (5-7 kW)","Air cooling adequate"],["Medium (10-15 kW)","Enhanced airflow"],["High (20-30 kW)","In-row or RDHX required"],["AI/HPC (50-100 kW)","Direct liquid cooling"]],"rel":["cooling-type","white-space","rack-density-kw-m2","pdu-type"],"aliases":["Rack Density","rack density","kW/rack"]},"rack-density-kw-m2":{"t":"Area Power Density","d":"IT power per square meter of White Space, combining rack power and rack spacing — legacy enterprise halls run 1–2 kW/m², modern colocation 2–4 kW/m², and AI/HPC liquid-cooled halls can exceed 10 kW/m². Higher density shrinks the building (cheaper shell per MW) but concentrates structural floor loading (liquid-cooled racks can exceed 1,500 kg) and cooling distribution. The engine's space model derives hall area from IT Load, Rack Density, and layout allowances.","u":"kW/m²","rel":["rack-density","white-space","floor-type"],"aliases":["kW/m²","area power density","power density"]},"rack-unit":{"t":"Rack Unit (U / RU) ((U / RU))","d":"A standard unit of vertical space in a server rack equal to 44.45mm (1.75 inches). Standard racks are 42U or 48U tall. A 1U server is one rack unit high; a 2U server is two. Rack unit planning determines how many devices fit in each cabinet.","link":"glossary.html#term-rack-unit","aliases":["(U / RU)","Rack Unit (U / RU)"]},"raised-floor":{"t":"Raised Floor","d":"An elevated floor system creating an under-floor plenum for cable routing and cold air distribution. Standard heights range from 300mm (cable-only) to 1000mm (full airflow distribution). While still common, overhead cooling and cableless rack designs are reducing reliance on raised floors.","link":"glossary.html#term-raised-floor","aliases":[]},"rca":{"t":"RCA (Root Cause Analysis) ((Root Cause Analysis))","d":"A systematic investigation method used after incidents to identify the underlying cause of a failure, rather than just the symptoms. RCA techniques include 5-Why analysis, fishbone diagrams, and fault tree analysis. Every significant data center incident should result in a documented RCA report.","link":"glossary.html#term-rca","aliases":["(Root Cause Analysis)","RCA (Root Cause Analysis)"]},"rear-door":{"t":"Rear-Door Heat Exchanger (RDHx) ((RDHx))","d":"A liquid-cooled coil assembly mounted on the rear door of a server rack that captures heat from exhaust air before it enters the room. RDHx can remove 30-100% of rack heat at the source, enabling higher rack densities without modifying the room-level cooling infrastructure.","link":"glossary.html#term-rear-door","aliases":["(RDHx)","Rear-Door Heat Exchanger (RDHx)"]},"rectifier":{"t":"Rectifier","d":"An electronic device that converts alternating current (AC) to direct current (DC). In UPS systems, the rectifier converts utility AC to DC for battery charging and inverter input. Modern thyristor and IGBT rectifiers achieve 97%+ efficiency with active power factor correction.","link":"glossary.html#term-rectifier","aliases":["Rectifier"]},"redfish-coolingunit":{"t":"Redfish CoolingUnit","d":"The DMTF Redfish CoolingUnit schema (DSP2064 v1.1.0, controls landed Dec 2024) — the open telemetry and control API for CDUs: CoolingLoop, CoolantConnector, Pump, LeakDetection, Filters and Reservoirs, plus settable flow / supply-temperature / &Delta;P setpoints. OCP mandates Redfish for 2024+ liquid-cooling deployments.","link":"glossary.html#term-redfish-coolingunit","aliases":["Redfish CoolingUnit"]},"redundancy":{"t":"Redundancy Level","d":"How many spare capacity paths the power and cooling systems carry: N is need-only, N+1 adds one spare module, 2N duplicates the entire plant, 2N+1 duplicates plus a spare. Higher redundancy buys uptime — N gives 99.671% (~28.8 hr/yr down), N+1 gives 99.982% (~1.6 hr/yr), 2N gives 99.995% (~26 min/yr) — but 2N roughly doubles the electrical and mechanical infrastructure cost. Redundancy is the primary determinant of the Tier Classification and Expected Uptime shown in the results.","table":[["Level","Uptime SLA"],["N (Basic)","99.671% (~28.8hr/yr)"],["N+1 (Standard)","99.982% (~1.6hr/yr)"],["2N (Full)","99.995% (~26min/yr)"],["2N+1 (Premium)","99.9995% (~2.6min/yr)"]],"rel":["tier-class","uptime-sla","n-plus-1-redundancy","total-capex"],"aliases":["Redundancy","Redundancy Level","N+1","2N","2N+1"]},"ref":{"t":"REF (Renewable Energy Factor) ((Renewable Energy Factor))","d":"The ratio of renewable energy used by a data center to its total energy consumption, expressed as a percentage. REF = Renewable Energy / Total Energy x 100%. Defined in ISO 30134-3. A REF of 100% means the facility matches all energy consumption with renewable sources.","link":"glossary.html#term-ref","aliases":["(Renewable Energy Factor)","REF (Renewable Energy Factor)"]},"refrigerant":{"t":"Refrigerant","d":"The working fluid in chillers and CRAC units, and a triple-impact choice: it drives cycle efficiency (COP), Scope-1 leakage emissions (via GWP), and safety-mitigation CAPEX (via the ASHRAE 34 Safety Class). Regulation is forcing the transition — the US AIM Act restricts GWP > 700 in new equipment from 2025 and the EU F-Gas Regulation targets GWP > 150 — pushing the industry from R-410A and R-134a toward A2L blends and ultra-low-GWP HFOs like R-1234ze. The calculator's 'Auto' mode picks the industry-typical refrigerant for the selected Cooling Type (e.g. R-410A for CRAC, R-134a for RDHX chillers, R-1234ze for Deep Sea trim plants).","s":"GWP100 per IPCC AR4; ASHRAE Standard 34 safety classes","rel":["gwp","cop","ashrae-34-safety-class","cooling-type","trim-chiller"],"aliases":["Refrigerant","Refrigerant Type","refrigerant"]},"region-location":{"t":"Region","d":"The geographic region that sets the base construction-cost multiplier before any city-level override: Americas is the 1.00x baseline, EMEA-Europe runs 1.15x, Middle East 0.90x, and APAC averages 0.85x but varies widely (Tokyo and Singapore are among the world's most expensive markets). Region also drives permitting timelines and labor market conditions. Selecting a specific City / Market replaces this generic multiplier with precise $/W data from Turner & Townsend DCCI 2025 and Cushman & Wakefield 2025.","table":[["Region","Default Mult."],["Americas","1.00x (baseline)"],["EMEA - Europe","1.15x"],["Middle East","0.90x"],["APAC","0.85x (varies widely)"]],"rel":["city-market","total-capex","contractor-availability"],"aliases":["Region","APAC","EMEA"]},"reliability-pricing-model":{"t":"Reliability Pricing Model (RPM, PJM) ((RPM, PJM))","d":"PJM's forward capacity market mechanism that procures generation and demand-response resources three years ahead of the delivery year. Annual Base Residual Auction (BRA) clearing prices signal capacity adequacy. Recent BRA results cleared 9-10x higher than the previous year, reflecting load growth and generator retirements. RPM is the primary financial signal driving new generation investment in PJM.","link":"glossary.html#term-reliability-pricing-model","aliases":["(RPM, PJM)","Reliability Pricing Model (RPM, PJM)"]},"remote-monitoring":{"t":"Remote Monitoring","d":"The ability to observe and manage data center systems from off-site locations via network-connected sensors, cameras, and management platforms. Remote monitoring enables centralized operations centers to oversee multiple facilities, reducing staffing requirements per site.","link":"glossary.html#term-remote-monitoring","aliases":["Remote Monitoring"]},"reserve-margin":{"t":"Reserve Margin","d":"The percentage of installed generating capacity exceeding peak forecast load, expressed as a buffer for unplanned outages and demand spikes. NERC reference reserve margins for PJM are 14-15.8%; PJM's 2024 LTRA forecast shows reserve margin compressing toward target floors as data center load growth outpaces new generation. Reserve margin below the reference triggers reliability concerns and emergency procurement.","link":"glossary.html#term-reserve-margin","aliases":["Reserve Margin"]},"resilience":{"t":"Resilience","d":"The ability of a data center to anticipate, withstand, recover from, and adapt to adverse conditions. Resilience goes beyond redundancy to encompass operational procedures, training, supply chain management, and geographic diversity. Uptime Institute's TCOS certification evaluates operational resilience.","link":"glossary.html#term-resilience","aliases":["Resilience"]},"revenue-per-kw":{"t":"Revenue per kW","d":"The top-line pricing unit of the data center business: monthly (or annual) revenue per kW of contracted IT capacity. Retail colocation commonly achieves $100–250/kW/month depending on market and service level, while wholesale and Hyperscaler Pre-Lease deals run materially lower per kW but with long terms, built-in Escalation, and near-zero vacancy. Together with the Occupancy Ramp it defines revenue; against OPEX it defines NOI and EBITDA — it is a top driver in every Sensitivity Matrix.","u":"$/kW/month","rel":["colocation-pricing","occupancy-ramp","noi","escalation","sensitivity-matrix"],"aliases":["Revenue per kW","Revenue/kW","$/kW/month"]},"ring-bus":{"t":"Ring Bus","d":"An electrical distribution topology where switchgear forms a closed loop (ring), allowing power to flow in either direction. If one segment fails, power routes through the other direction. Ring bus configurations provide higher availability than radial distribution at medium-voltage levels.","link":"glossary.html#term-ring-bus","aliases":["Ring Bus"]},"roi":{"t":"ROI (Return on Investment) ((Return on Investment))","d":"A financial metric measuring the profitability of a data center investment. ROI = (Net Profit / Total Investment) x 100%. Typical data center ROI ranges from 10-25% annually for colocation operators. Factors include utilization rate, energy efficiency, and pricing strategy.","link":"glossary.html#term-roi","aliases":["(Return on Investment)","ROI (Return on Investment)"]},"rollback":{"t":"Rollback","d":"The process of reverting a system, configuration, or software change to its previous known-good state. Rollback procedures are essential in data center change management. Every maintenance window should include a documented rollback plan with specific time criteria for triggering it.","link":"glossary.html#term-rollback","aliases":["Rollback"]},"room-integrity":{"t":"Room Integrity (Door-Fan Test) ((Door-Fan Test))","d":"The measured air-tightness of a clean-agent protected room, expressed as an equivalent leakage area. NFPA 2001 requires the agent concentration to be retained for a minimum hold time (typically &ge;10 min); a door-fan (blower-door) test verifies the enclosure is tight enough &mdash; otherwise the agent leaks away before the fire is fully extinguished and re-ignites.","link":"glossary.html#term-room-integrity","aliases":["(Door-Fan Test)","Room Integrity (Door-Fan Test)"]},"rpo":{"t":"RPO (Recovery Point Objective) ((Recovery Point Objective))","d":"The maximum acceptable amount of data loss measured in time. An RPO of 1 hour means the organization can tolerate losing up to 1 hour of data. RPO determines backup frequency: synchronous replication achieves near-zero RPO; daily backups set RPO at 24 hours.","link":"glossary.html#term-rpo","aliases":["(Recovery Point Objective)","RPO (Recovery Point Objective)"]},"rto":{"t":"RTO (Recovery Time Objective) ((Recovery Time Objective))","d":"The maximum acceptable duration to restore services after a disaster. An RTO of 4 hours means systems must be operational within 4 hours of an outage. Active-active configurations achieve near-zero RTO; cold standby sites may have RTOs of 24-72 hours.","link":"glossary.html#term-rto","aliases":["(Recovery Time Objective)","RTO (Recovery Time Objective)"]},"runtime":{"t":"Runtime (UPS Battery Runtime) ((UPS Battery Runtime))","d":"The duration a UPS can sustain IT load on battery power after utility failure. Standard runtime designs provide 5-15 minutes, sufficient for generator start and transfer. Extended runtime configurations use additional battery cabinets. Runtime decreases as batteries age and as load increases.","link":"glossary.html#term-runtime","aliases":["(UPS Battery Runtime)","Runtime (UPS Battery Runtime)"]},"san":{"t":"SAN (Storage Area Network) ((Storage Area Network))","d":"A dedicated high-speed network that provides block-level access to shared storage devices. SANs use Fibre Channel (16/32 Gbps) or iSCSI protocols. Being partially displaced by NVMe-oF (NVMe over Fabrics) which offers lower latency for flash storage arrays.","link":"glossary.html#term-san","aliases":["(Storage Area Network)","SAN (Storage Area Network)"]},"scada":{"t":"SCADA (Supervisory Control and Data Acquisition) ((Supervisory Control and Data Acquisition))","d":"An industrial control system used to monitor and control data center mechanical and electrical infrastructure. SCADA collects real-time data from PLCs, RTUs, and sensors, providing operator interfaces, alarm management, and historical trending for critical systems.","link":"glossary.html#term-scada","aliases":["(Supervisory Control and Data Acquisition)","SCADA (Supervisory Control and Data Acquisition)"]},"seawater-delta-t":{"t":"Seawater ΔT (Temperature Rise)","d":"How much the seawater warms passing through the heat exchanger — the design value is 5 °C, which is also the common environmental discharge limit (ΔT ≤ 5 °C at the Outfall Diffuser mixing zone). ΔT and Seawater Flow trade off directly: halving ΔT doubles the required flow, pump power, and pipeline size, while pushing ΔT above the permit limit risks the discharge consent. The reference design moves 8.625 m³/s at exactly 5 °C to reject 172.5 MW.","f":"Q (heat) = rho x cp x Flow x deltaT","u":"°C","rel":["seawater-flow","outfall-diffuser","deep-sea-water-cooling","entrainment"],"aliases":["Seawater ΔT (°C)","Seawater ΔT","seawater delta T"]},"seawater-filtration":{"t":"Seawater Filtration","d":"The multi-stage screening train that keeps marine life and debris out of the Titanium PHE: coarse 50 mm bars → fine 5 mm screens → traveling screens → 200 µm disc filters → 50 µm auto-backwash, configured N+1 so cleaning never interrupts flow. Sized at roughly $260 per m³/h of Seawater Flow (about $8M for the 31,050 m³/h reference). Filtration performance directly controls HX fouling rates and therefore Marine OPEX (cleaning frequency, chlorination dosing).","u":"$ per m³/h","rel":["titanium-phe","seawater-flow","entrainment","marine-opex","n-plus-1-redundancy"],"aliases":["Seawater Filtration","seawater filtration","traveling screen"]},"seawater-flow":{"t":"Seawater Flow","d":"The volume of seawater pumped through the system, fixed by physics: Flow = Heat / (density x specific heat x ΔT). The 150 MW reference (172.5 MW total heat with electrical losses) needs 8.625 m³/s = 31,050 m³/h at the 5 °C Seawater ΔT — comparable to a small river. Flow determines everything downstream: pump count and Pump Head, HDPE Marine Pipeline diameter, Seawater Filtration sizing ($260 per m³/h), and the Entrainment footprint at the intake.","f":"Flow (m3/s) = Heat (MW) x 1e6 / (rho x cp x deltaT); poster: 172.5 / (4.0 x 5) = 8.625 m3/s","u":"m³/s","rel":["seawater-delta-t","pump-head","hdpe-marine-pipeline","seawater-filtration","entrainment"],"aliases":["Seawater Flow","seawater flow rate"]},"security-level":{"t":"Physical Security Level","d":"The physical security infrastructure package: fencing, CCTV, access control, bollards, mantraps, vehicle barriers, and a security operations center (SOC). Standard (CCTV + access control) is baseline; enterprise adds ~+2% for biometrics and mantraps; high security adds ~+5% for a 24/7 SOC, anti-vehicle K12 barriers, and layered perimeters. Colocation and Hyperscaler Pre-Lease customers frequently mandate specific levels, and Compliance regimes (SOC 2, ISO 27001) audit against them.","table":[["Level","Impact"],["Standard","Baseline (CCTV+access)"],["Enterprise","+2% (biometric+mantrap)"],["High Security","+5% (SOC+barriers+K12)"]],"rel":["tab-compliance","hyperscaler-prelease"],"aliases":["Security Level","Physical Security"]},"seismic":{"t":"Seismic Protection","d":"Structural and equipment design measures to protect data centers from earthquake damage. Includes seismic bracing for racks, flexible pipe connections, base isolation systems, and raised floor pedestal bracing. Seismic zone classification determines the level of protection required per building codes.","link":"glossary.html#term-seismic","aliases":["Seismic Protection"]},"seismic-zone":{"t":"Seismic Zone","d":"The earthquake-risk classification of the site, which dictates structural reinforcement: base isolation, braced racks, seismically rated cable tray and piping restraints. Cost impact ranges from +0% in Zone 0 to +15% in Zone 4 (very high risk); Indonesia is typically Zone 2–4. It also affects equipment anchorage specs for UPS Type and Generator Type gear and feeds the Disaster Risk assessment.","table":[["Zone","Cost Impact"],["Zone 0 - No Risk","+0%"],["Zone 1 - Low","+3%"],["Zone 2 - Moderate","+6%"],["Zone 3 - High","+10%"],["Zone 4 - Very High","+15%"]],"rel":["total-capex","tab-disaster","site-condition"],"aliases":["Seismic Zone","seismic zone"]},"selective-coordination":{"t":"Selective Coordination","d":"An electrical protection design where only the overcurrent device nearest to a fault opens, while upstream devices remain closed. This isolates the faulted circuit without affecting other loads. NEC Article 700 requires selective coordination for emergency and legally required standby systems.","link":"glossary.html#term-selective-coordination","aliases":["Selective Coordination"]},"sensitivity-matrix":{"t":"Sensitivity Matrix (Two-Way Data Table)","d":"A grid that recomputes the model across simultaneous variations of two drivers — in the DCMOC Financial module, CAPEX variation (rows) against Revenue per kW variation (columns), with each cell showing NPV / IRR. It reveals interaction effects a one-variable-at-a-time Tornado Chart misses (e.g. high CAPEX is survivable only if revenue also lands high), and shows how close the deal sits to its breakeven frontier. The disciplined workflow: tornado to find the top two drivers, then a sensitivity matrix on exactly those.","rel":["tornado-chart","monte-carlo","npv","revenue-per-kw","total-capex"],"aliases":["Sensitivity Matrix","sensitivity matrix","sensitivity analysis"]},"server":{"t":"Server","d":"A computer designed to process, store, and serve data to other devices over a network. Data center servers range from 1U rack-mount units to 4U GPU-accelerated systems. Key specifications include CPU cores, memory capacity, storage type (SSD/NVMe), and power supply efficiency (80 PLUS Titanium).","link":"glossary.html#term-server","aliases":["Server"]},"site-condition":{"t":"Site Condition (Greenfield / Brownfield / Retrofit)","d":"The starting state of the land or building. Greenfield (raw land) adds +5–8% for grading, drainage, and utility extensions; brownfield (existing industrial site) is the baseline needing some demolition; retrofit/conversion of an existing building adds +10–20% for demolition, structural adaptation, and working around as-built surprises. Interacts with Building Type — a warehouse conversion is by definition a retrofit play trading shell savings against adaptation cost.","table":[["Condition","Site Cost"],["Greenfield (raw land)","+5-8% for grading/utilities"],["Brownfield","Baseline"],["Retrofit / Conversion","+10-20% for demo/adaptation"]],"rel":["building-type","seismic-zone"],"aliases":["Site Condition","Site Preparation","Greenfield","Brownfield","Retrofit"]},"skin":{"t":"Skin (Building Envelope) ((Building Envelope))","d":"The physical barrier between the interior and exterior of a data center building, including walls, roof, and foundation. The building skin provides thermal insulation, vapor barrier, and physical security. Data center skins are designed for minimal heat gain with high R-value insulation and reflective roofing.","link":"glossary.html#term-skin","aliases":["(Building Envelope)","Skin (Building Envelope)"]},"sla":{"t":"SLA (Service Level Agreement) ((Service Level Agreement))","d":"A contractual commitment defining service quality metrics including uptime percentage (e.g., 99.99%), response times, escalation procedures, and financial penalties for non-compliance. Data center SLAs cover power availability, cooling parameters, network uptime, and physical security access times.","link":"glossary.html#term-sla","aliases":["(Service Level Agreement)","SLA (Service Level Agreement)"]},"smart-hands":{"t":"Smart Hands","d":"On-site technical support services provided by colocation facility staff on behalf of remote tenants. Smart hands tasks include server reboots, cable patching, hardware swaps, visual inspections, and shipment receiving. Billed hourly or included in service packages.","link":"glossary.html#term-smart-hands","aliases":["Smart Hands"]},"snmp":{"t":"SNMP (Simple Network Management Protocol) ((Simple Network Management Protocol))","d":"A protocol for monitoring and managing network-attached devices including UPS, PDU, cooling units, and sensors. SNMPv3 adds encryption and authentication. SNMP traps provide asynchronous notifications when monitored parameters exceed thresholds. Essential for BMS and DCIM integration.","link":"glossary.html#term-snmp","aliases":["(Simple Network Management Protocol)","SNMP (Simple Network Management Protocol)"]},"soc2":{"t":"SOC 2 (System and Organization Controls) ((System and Organization Controls))","d":"An auditing framework developed by AICPA that evaluates a service organization's controls related to security, availability, processing integrity, confidentiality, and privacy. SOC 2 Type II reports cover a review period (typically 12 months) and are required by many enterprise data center customers.","link":"glossary.html#term-soc2","aliases":["(System and Organization Controls)","SOC 2 (System and Organization Controls)"]},"sop":{"t":"SOP (Standard Operating Procedure) ((Standard Operating Procedure))","d":"A documented step-by-step instruction for performing routine or critical data center tasks. SOPs cover equipment startup/shutdown, emergency response, maintenance procedures, and visitor access. Well-maintained SOPs reduce human error and ensure consistent operations across shifts.","link":"glossary.html#term-sop","aliases":["(Standard Operating Procedure)","SOP (Standard Operating Procedure)"]},"spectrum-x":{"t":"Spectrum-X (NVIDIA)","d":"NVIDIA's end-to-end Ethernet networking platform optimized for AI workloads, combining BlueField-3 DPUs with Spectrum-4 Ethernet switches and adaptive routing. Spectrum-X delivered the lossless inter-GPU fabric for xAI's Colossus 100,000-GPU cluster. Compared to InfiniBand, Spectrum-X targets operators who prefer Ethernet operational tooling while approaching IB-class collective communication performance.","link":"glossary.html#term-spectrum-x","aliases":["Spectrum-X (NVIDIA)"]},"spof":{"t":"SPOF (Single Point of Failure) ((Single Point of Failure))","d":"Any component whose failure alone would cause the entire system to stop functioning. Eliminating SPOFs is the fundamental goal of data center redundancy design. Common SPOFs include single utility feeds, non-redundant cooling, single-path PDUs, and shared control systems.","link":"glossary.html#term-spof","aliases":["(Single Point of Failure)","SPOF (Single Point of Failure)"]},"static-transfer-switch":{"t":"STS (Static Transfer Switch) ((Static Transfer Switch))","d":"A solid-state device that transfers electrical load between two independent power sources within 4-8 milliseconds using thyristors. STSs provide sub-cycle transfer for dual-fed facilities, ensuring seamless power continuity when one source fails or requires maintenance.","link":"glossary.html#term-static-transfer-switch","aliases":["(Static Transfer Switch)","STS (Static Transfer Switch)"]},"static-ups":{"t":"Static UPS","d":"A solid-state UPS with no moving parts, using power electronics (rectifier, inverter, battery) to provide uninterrupted power. Static UPS is the most common type in data centers, available from 10 kVA to 1,600+ kVA per module with efficiency ratings up to 97% in double-conversion mode.","link":"glossary.html#term-static-ups","aliases":["Static UPS"]},"stranded-capacity":{"t":"Stranded Capacity","d":"Deployed power, cooling, or space capacity that cannot be utilized due to imbalanced provisioning. For example, 10 MW of power capacity with only 7 MW of cooling limits usable capacity to 7 MW, stranding 3 MW. Modular design and right-sizing reduce stranded capacity.","link":"glossary.html#term-stranded-capacity","aliases":["Stranded Capacity"]},"structured-cabling":{"t":"Structured Cabling","d":"A standardized approach to data center cabling using organized pathways, patch panels, and labeling systems. TIA-942 defines structured cabling zones: entrance room, main distribution area (MDA), horizontal distribution area (HDA), equipment distribution area (EDA), and zone distribution area (ZDA).","link":"glossary.html#term-structured-cabling","aliases":[]},"substation-type":{"t":"Substation Type","d":"The grid connection point sizing. A shared utility substation costs $0.5–1.5M but caps capacity and expansion; a dedicated 33kV substation ($3–5M) is typical for 5–30 MW campuses; dedicated 132kV+ ($5–10M+) is required for hyperscale loads and gives the operator control over reliability. Part of the Front-of-Meter cost block, and the voltage class drives Transformer Lead Time exposure.","table":[["Type","Cost"],["Shared Utility","$0.5-1.5M"],["Dedicated 33kV","$3-5M"],["Dedicated 132kV+","$5-10M+"]],"rel":["front-of-meter","transformer-lead","tab-grid"],"aliases":["Substation Type","substation"]},"support-space":{"t":"Support Space","d":"All non-IT floor area: electrical rooms, UPS and battery rooms, cooling plant, generator yards, fuel storage, network entry rooms, corridors, loading docks, and offices. Support space commonly equals or exceeds the White Space itself — higher Redundancy (2N duplicates plant rooms) and on-site fuel for long Fuel Autonomy both inflate it. It earns no direct revenue, so efficient support-space ratio is a real design KPI in the space model.","u":"m²","rel":["white-space","redundancy","fuel-autonomy"],"aliases":["Support Space","support space"]},"surge-protection":{"t":"Surge Protection (SPD) ((SPD))","d":"Devices that protect electrical equipment from voltage spikes caused by lightning, utility switching, or generator transitions. Surge Protective Devices (SPDs) are installed at each level of the power distribution chain (Type 1 at service entrance, Type 2 at sub-panels, Type 3 at equipment).","link":"glossary.html#term-surge-protection","aliases":["(SPD)","Surge Protection (SPD)"]},"sustainability":{"t":"Sustainability","d":"Environmental practices in data center operations including renewable energy procurement, water conservation, waste heat reuse, and carbon offset programs. Key metrics include PUE, WUE, CUE, and REF (Renewable Energy Factor). Many operators target 100% renewable energy matching.","link":"glossary.html#term-sustainability","aliases":["Sustainability"]},"switchgear":{"t":"Switchgear","d":"An assembly of circuit breakers, disconnect switches, fuses, and protective relays used to control, protect, and isolate electrical equipment. Medium-voltage switchgear (11-33 kV) handles utility intake; low-voltage switchgear (below 1 kV) distributes to loads. Metal-clad and metal-enclosed designs provide arc containment.","link":"glossary.html#term-switchgear","aliases":["Switchgear"]},"tab-asset-lifecycle":{"t":"Asset Lifecycle","d":"Tracks every asset category through its useful life: category-level Depreciation expense per year (bar widths proportional to annual totals), declining book value versus cumulative replacement spend, and configurable depreciation method over the projection horizon. The refresh-capital planning view that keeps late-hold cash flows honest.","rel":["depreciation","capex","tab-cbm"],"aliases":["Asset Lifecycle"]},"tab-benchmark":{"t":"Benchmarks","d":"Country-level benchmark analysis scoring markets across categorized criteria (cost, energy, connectivity, risk, talent) with per-category detail. Converts raw market data into Benchmark Percentile rankings for site-selection decisions.","rel":["benchmark-percentile","city-market","tab-talent","tab-grid"],"aliases":["Benchmarks"]},"tab-capacity":{"t":"Capacity Plan","d":"Plans phased capacity build-out: phase configuration, a build-timeline Gantt chart, and a narrative of when each megawatt tranche lands. Phasing matches CAPEX deployment to the Occupancy Ramp so capital is not stranded ahead of demand — Transformer Lead Time is usually the gating item.","rel":["occupancy-ramp","transformer-lead","tab-phased-finance"],"aliases":["Capacity Plan"]},"tab-capex":{"t":"CAPEX Config","d":"Configures the capital-cost model inside DCMOC — build cost per kW, phasing, and category breakdowns — with a generated narrative explaining the estimate. Mirrors the standalone capex calculator's logic and feeds Total CAPEX into the Financial and Investment modules.","rel":["total-capex","cost-per-kw","tab-finance","tab-invest"],"aliases":["CAPEX Config"]},"tab-carbon":{"t":"Carbon / ESG","d":"Models the facility's emissions footprint across scenarios: grid-electricity carbon (Scope 2, driven by PUE and grid intensity — see CUE), generator fuel and refrigerant leakage (Scope 1, driven by Generator Type and GWP), and decarbonization scenario descriptions. The ESG evidence base behind Green Certification and investor reporting.","rel":["cue","gwp","generator-type","green-certification","onsite-renewable"],"aliases":["Carbon / ESG","Carbon/ESG"]},"tab-cbm":{"t":"CBM / DCIM (Condition-Based Maintenance)","d":"Module 43 — evaluates BMS/DCIM sensor investment against failure-avoidance savings: sensor categories with count formulas, coverage economics, and payback. Condition-based maintenance replaces calendar-based Maintenance intervals with actual equipment health data, cutting both cost and surprise failures; intelligent PDU Type telemetry is one of its data feeds.","rel":["tab-maint","pdu-type","tab-asset-lifecycle"],"aliases":["CBM / DCIM","CBM","DCIM"]},"tab-compliance":{"t":"Compliance","d":"Auto-generates the regulatory requirement checklist per country (Module 41) and scores compliance coverage — data-protection law, building and environmental permits, sector certifications — with per-item notes. Compliance gaps are schedule and licensing risk, not just paperwork.","rel":["tab-benchmark","security-level"],"aliases":["Compliance"]},"tab-disaster":{"t":"Disaster Risk","d":"Natural-hazard exposure per country shown as a risk radar (earthquake, flood, typhoon, volcanic) with costed mitigation options. Complements the Seismic Zone input in the capex model — hazard drives both construction premium and insurance OPEX.","rel":["seismic-zone","tab-risk","tab-grid"],"aliases":["Disaster Risk"]},"tab-faq":{"t":"FAQ / Manual","d":"The in-app manual: explains each DCMOC module, its inputs, assumptions, and data vintage, with per-item descriptions. Start here to understand what each tab computes and which numbers are estimate-grade versus sourced.","rel":["tab-sim","tab-report"],"aliases":["FAQ","FAQ / Manual","Open FAQ / Manual"]},"tab-finance":{"t":"Financial","d":"The core project-finance model: cash flows, NPV and IRR, and a two-way Sensitivity Matrix of CAPEX variation (rows) versus Revenue per kW variation (columns) with NPV / IRR shown per cell. Where the engineering configuration becomes an investment case.","rel":["npv","project-irr","sensitivity-matrix","revenue-per-kw","tab-invest"],"aliases":["Financial"]},"tab-fuel-gen":{"t":"Fuel & Generator","d":"Module 44 — diesel generator sizing, fuel consumption, and cost modeling: liters per year at the modeled run profile, priced at each country's diesel price including tax. Connects Grid Reliability (how often generators run) with Fuel Autonomy (how much tankage) into an annual OPEX number.","rel":["generator-type","fuel-autonomy","tab-grid"],"aliases":["Fuel & Generator"]},"tab-grid":{"t":"Grid Reliability","d":"Scores utility-grid dependability by country and computes the annual grid-risk cost breakdown: outage frequency/duration converted into generator run-hours, fuel burn, and downtime exposure. Weak grids shift the design toward longer Fuel Autonomy and heavier Generator Type investment.","rel":["fuel-autonomy","generator-type","tab-fuel-gen","tab-benchmark"],"aliases":["Grid Reliability"]},"tab-invest":{"t":"Investment","d":"The levered view of the deal: Capital Structure (debt/equity split), the Debt Amortization Schedule, and the Debt Service Coverage Ratio (DSCR) tracked year by year against covenant levels. This is where the Debt Ratio, Equity IRR, and the Cash Flow Waterfall live.","rel":["dscr","debt-ratio-leverage","equity-irr","cash-flow-waterfall"],"aliases":["Investment"]},"tab-maint":{"t":"Maintenance","d":"Plans preventive and corrective maintenance: event intensity by month (heatmap — darker means more events), per-system maintenance strategies with descriptions, and work-order views. Maintenance discipline is what converts designed Redundancy into actual Expected Uptime; deferred maintenance shows up later as Risk Analysis exposure.","rel":["opex","tab-cbm","tab-risk","uptime-sla"],"aliases":["Maintenance"]},"tab-montecarlo":{"t":"Monte Carlo","d":"Runs a configurable Monte-Carlo Simulation on the selected country's financial model: adjust variable distributions, run thousands of trials, and read the outcome distribution as P10/P50/P90 bands for IRR and NPV. The probabilistic reality-check on the deterministic Financial tab.","rel":["monte-carlo","p10-p50-p90","tornado-chart","tab-finance"],"aliases":[]},"tab-phased-finance":{"t":"Phased Finance","d":"The financial model of the phased build: blended cash flow across phases and an investment decision matrix against a 12% hurdle rate, with narrative. Shows whether later phases stand on their own economics or ride on phase-1 infrastructure.","rel":["tab-capacity","project-irr","npv"],"aliases":["Phased Finance"]},"tab-portfolio":{"t":"Portfolio","d":"Compares 2+ candidate sites side-by-side on a radar chart and metric table — import the current configuration or add blank site templates. The multi-site ranking view where unlevered Project IRR is the fair comparison basis.","rel":["project-irr","tab-benchmark","benchmark-percentile"],"aliases":["Portfolio"]},"tab-report":{"t":"Report","d":"Compiles the full analysis into an exportable report and lets you compare two saved scenarios side-by-side, including shift-model comparison recommendations. The executive-summary layer over every other module's output.","rel":["tab-sim","tab-finance"],"aliases":["Report"]},"tab-risk":{"t":"Risk Analysis","d":"Catalogs and scores operational risks — equipment failure modes, single points of failure, downtime exposure — with per-risk descriptions and mitigation status. Quantified downtime risk closes the loop between the engineering choices (Redundancy, Tier) and the financial model (lost revenue per outage hour).","rel":["tab-disaster","uptime-sla","redundancy","tab-sim"],"aliases":["Risk Analysis"]},"tab-sim":{"t":"SIM — Simulation Dashboard","d":"DCMOC's default operations-simulation view: models the facility's operating envelope including overtime and regulatory labor analysis (Indonesia PP 35/2021), environmental physics (power-law load/temperature effects), and risk-and-downtime exposure by Tier level. The launching point that feeds the Staffing, Maintenance, and Financial modules.","rel":["tab-staff","tab-maint","tab-risk","tier-class"],"aliases":["SIM","Simulation Dashboard"]},"tab-staff":{"t":"Staffing","d":"Models the operations headcount: detailed role breakdown with monthly costs, shift-pattern coverage, and a 5-year cost projection in USD. Staffing is a top-three OPEX line after energy, and Tier Classification drives minimum-coverage rules (24/7 shifts for Tier III+).","rel":["opex","tab-talent","tab-sim"],"aliases":["Staffing","Staff Model Config"]},"tab-strategic":{"t":"Strategic Planning","d":"Long-horizon capacity strategy: projects demand growth against installed capacity and flags when expansion is needed within the planning horizon (or confirms none is). The bridge from a single-site Capacity Plan to a multi-year, multi-phase investment roadmap.","rel":["tab-capacity","tab-phased-finance","tab-portfolio"],"aliases":["Strategic Planning"]},"tab-talent":{"t":"Talent Index","d":"Scores the availability of qualified data center operations and engineering talent by country, with factor-level analysis. Talent scarcity inflates the Staffing cost model and construction-phase Contractor Availability premiums.","rel":["tab-staff","contractor-availability","tab-benchmark"],"aliases":["Talent Index"]},"tab-tax":{"t":"Tax & Incentives","d":"Models country tax regimes and incentives: a tax-rate timeline (standard vs effective under a Tax Holiday), free-trade-zone listings, and an NPV-normalized incentive value ranking. Effective-tax deltas of this size routinely re-rank countries in the Portfolio comparison.","rel":["tax-holiday","depreciation","tab-benchmark"],"aliases":[]},"tax-holiday":{"t":"Tax Holiday / Incentives","d":"Government incentives that reduce or defer taxes for qualifying data center investments: corporate income tax holidays (Indonesia offers up to 20 years for large pioneer-industry investments), sales/VAT exemptions on equipment, accelerated Depreciation, and free-trade-zone benefits. Incentives can move after-tax Equity IRR by several points and materially shift country rankings — which is why the DCMOC Tax & Incentives module computes an effective tax-rate timeline and NPV-normalized incentive ranking per country.","rel":["depreciation","equity-irr","tab-tax","tab-benchmark"],"aliases":["Tax Holiday","tax holiday","tax incentives","Tax & Incentives"]},"tco":{"t":"TCO (Total Cost of Ownership)","d":"The all-in lifetime cost of the facility: CAPEX plus the present value of every year of OPEX, refresh capital, and end-of-life costs over the analysis horizon (typically 10–15 years). TCO is the fair basis for comparing design alternatives that trade capital against operations — Deep Sea Water Cooling or a better PUE costs more up front and wins on TCO; a cheap build with poor efficiency loses. Discounting at WACC keeps the comparison honest across time.","f":"TCO = CAPEX + sum( OPEX_t / (1+r)^t ) over horizon","u":"USD","rel":["capex","opex","annual-energy-cost","wacc","pue"],"aliases":["TCO","Total Cost of Ownership"]},"tcs":{"t":"TCS (Technology Cooling System) ((Technology Cooling System))","d":"The secondary loop — the closed chip-side circuit between the CDU and the cold plates, typically PG-25. Hydraulically separated from the facility water (FWS) by the CDU heat exchanger, and held to a tight chemistry band (pH 8–10.5, conductivity <1500 &micro;S/cm, >100 ppm inhibitor) to protect the micro-channels.","link":"glossary.html#term-tcs","aliases":["(Technology Cooling System)","TCS (Technology Cooling System)"]},"telemetry":{"t":"Telemetry","d":"Automated collection and transmission of measurements from remote sensors and meters to a central monitoring system. Data center telemetry covers electrical parameters, environmental conditions, cooling system status, and network performance. Modern telemetry uses streaming protocols (MQTT, gRPC) for real-time data ingestion.","link":"glossary.html#term-telemetry","aliases":["Telemetry"]},"terminal-value":{"t":"Terminal Value","d":"The assumed value of the asset at the end of the explicit forecast, typically exit-year EBITDA times the Exit EV/EBITDA Multiple (or NOI divided by an exit Cap Rate — the same idea in real-estate form). It frequently represents 40–60% of total present value in a 10-year model, which means the 'answer' is heavily an assumption about the future sale market. Stress the exit multiple in the Sensitivity Matrix before trusting any Equity IRR.","f":"Terminal Value = Exit EBITDA x Exit Multiple (or NOI / exit cap rate)","u":"USD","rel":["exit-ev-ebitda-multiple","cap-rate","equity-irr","npv"],"aliases":["Terminal Value","terminal value","exit value"]},"tfa":{"t":"TFA (Trifluoroacetic Acid, CF 3 ((Trifluoroacetic Acid, CF 3)","d":"A short-chain perfluorinated carboxylic acid that is the primary atmospheric breakdown product of the HFO \"PFAS-free\" immersion fluids (e.g. Opteon 2P50 / HFO-1336mzz-Z) and HFC/HFO refrigerants. R-1234yf degrades roughly 100% to TFA. TFA is extremely water-soluble, mobile, not removed by conventional treatment, and effectively persistent in the hydrosphere &mdash; \"forever-mobile.\" It sits outside the US EPA's 4 ppt PFOA/PFOS drinking-water rule, but the EU Drinking Water Directive's 0.5 &micro;g/L PFAS-Total limit (live Jan 2026) and member-state limits (Italy 10, NL 2.2, Germany 60 &micro;g/L) do capture it, and ECHA's RAC moved in 2025-2026 to classify TFA as a Reproductive Toxicant Category 1B. This is why an \"HFO replacement\" can trade a persistent fluid for a persistent degradation product.","link":"glossary.html#term-tfa","aliases":["(Trifluoroacetic Acid, CF 3","TFA (Trifluoroacetic Acid, CF 3"]},"thermal-management":{"t":"Thermal Management","d":"The comprehensive strategy for removing heat from a data center including airflow design, cooling equipment selection, containment, and temperature monitoring. Effective thermal management balances energy efficiency with maintaining ASHRAE-recommended server inlet temperatures.","link":"glossary.html#term-thermal-management","aliases":["Thermal Management"]},"thermal-runaway":{"t":"Thermal Runaway","d":"An uncontrolled self-heating chain reaction in a lithium-ion cell: an internal short or over-temperature raises the cell temperature, which accelerates exothermic decomposition, which raises temperature further. Onset is ~150 °C for NMC and ~166.8 °C for LFP. The cell then vents flammable gas (H 2 /CO) and can propagate cell-to-cell &mdash; the central fire risk of lithium-ion data-center battery backup (BBU/UPS).","link":"glossary.html#term-thermal-runaway","aliases":["Thermal Runaway"]},"three-loop-architecture":{"t":"Three-Loop Architecture (TCS / FWS / Seawater)","d":"The separation of the cooling chain into three isolated hydraulic loops: the Technology Cooling System (rack CDU loop, direct-to-chip at 20–25 °C), the closed Facility Water System (clean treated water, ~10 bar design), and the open seawater loop. Each boundary crossing happens in a heat exchanger — the Titanium PHE at the seawater boundary — so corrosive, biologically active seawater never approaches the IT equipment, and a leak in any loop is contained. This layering costs approach temperature (each HX adds ~2 °C) but is what makes ocean cooling insurable and maintainable.","rel":["deep-sea-water-cooling","titanium-phe","cooling-type"],"aliases":["Three-Loop Architecture","3 separated loops","TCS","FWS","facility water system"]},"tia-942":{"t":"TIA-942 (Telecommunications Infrastructure Standard for Data Centers) ((Telecommunications Infrastructure Standard for Data Centers))","d":"An ANSI/TIA standard that specifies minimum requirements for data center telecommunications infrastructure including site selection, architectural considerations, electrical systems, mechanical systems, fire protection, and structured cabling. Updated versions (TIA-942-B) align with modern design practices.","link":"glossary.html#term-tia-942","aliases":["(Telecommunications Infrastructure Standard for Data Centers)","TIA-942 (Telecommunications Infrastructure Standard for Data Centers)"]},"tier":{"t":"Tier Classification (Uptime Institute) ((Uptime Institute))","d":"A four-level rating system for data center infrastructure resilience. Tier I: basic (99.671%), single path, no redundancy. Tier II: redundant components (99.749%), N+1. Tier III: concurrently maintainable (99.982%), multiple paths. Tier IV: fault tolerant (99.995%), 2N distribution.","link":"glossary.html#term-tier","aliases":["(Uptime Institute)","Tier Classification (Uptime Institute)"]},"tier-class":{"t":"Tier Classification (Uptime Institute)","d":"The Uptime Institute's four-level availability classification, determined chiefly by Redundancy topology: Tier I (N) = 99.671% availability, Tier II = 99.741%, Tier III (N+1, concurrently maintainable) = 99.982%, Tier IV (2N, fault tolerant) = 99.995%. Each tier step roughly means an order-of-magnitude less annual downtime but materially more CAPEX — Tier IV can cost 1.5–2x a Tier II per kW. Tier III is the commercial colocation standard; the tier you build should match the revenue and SLA model, not exceed it.","table":[["Tier","Availability"],["Tier I (N)","99.671%"],["Tier II","99.741%"],["Tier III (N+1)","99.982%"],["Tier IV (2N)","99.995%"]],"s":"Uptime Institute Tier Standard","rel":["redundancy","uptime-sla","fuel-autonomy"],"aliases":["Tier Classification","Uptime Tier","Tier III","Tier IV"]},"titanium-phe":{"t":"Titanium Plate Heat Exchanger (PHE)","d":"The barrier between the corrosive open seawater loop and the clean closed facility-water loop, built from Titanium Grade 2 plates — the only mainstream material that survives decades of warm chloride exposure without pitting. Design approach temperature is 2.0 °C (range 1.5–2.5 °C): tighter approach means colder facility water but more plate area and cost (~$95k per MWth). Configured N+1 in parallel banks so individual units can be opened for cleaning without dropping the Three-Loop Architecture.","u":"$/MWth","rel":["deep-sea-water-cooling","three-loop-architecture","n-plus-1-redundancy","seawater-filtration"],"aliases":["Titanium PHE","titanium plate heat exchanger","Titanium Gr2 PHE","plate heat exchanger"]},"ton":{"t":"Ton of Refrigeration (TR) ((TR))","d":"A unit of cooling capacity equal to 12,000 BTU/hr or approximately 3.517 kW. A 500-ton chiller provides 1,758 kW of cooling capacity. Data center cooling requirements are often expressed in tons when sizing chillers and cooling towers.","link":"glossary.html#term-ton","aliases":["(TR)","Ton of Refrigeration (TR)"]},"tor":{"t":"ToR Switch (Top of Rack) ((Top of Rack))","d":"A network switch mounted at the top of a server rack that aggregates connections from all servers in that rack to the upstream network. ToR switches reduce cable runs and simplify management. Modern ToR switches support 25/100/400 GbE and are a key element of leaf-spine architectures.","link":"glossary.html#term-tor","aliases":["(Top of Rack)","ToR Switch (Top of Rack)"]},"tornado-chart":{"t":"Tornado Chart","d":"A ranked bar chart showing how much the output (Total CAPEX, NPV, or IRR) moves when each input swings across its plausible range, one variable at a time, holding the rest at base case — widest bar on top, hence the tornado shape. It answers the only question that matters in early-stage estimating: which two or three assumptions deserve real diligence money. In the capex calculator it ranks construction cost spread, escalation, and scope growth; pair it with the Sensitivity Matrix for the interaction view.","rel":["monte-carlo","sensitivity-matrix","p10-p50-p90"],"aliases":["Tornado Chart","tornado chart","tornado diagram"]},"torque":{"t":"Torque Testing","d":"Verification that electrical connections (bus bar joints, terminal lugs, breaker connections) are tightened to manufacturer-specified torque values. Loose connections cause resistive heating, which is a leading cause of electrical fires. NFPA 70B recommends annual torque verification on all critical connections.","link":"glossary.html#term-torque","aliases":["Torque Testing"]},"total-capex":{"t":"Total CAPEX (Capital Expenditure)","d":"The total upfront investment required to build the data center: construction, electrical and mechanical equipment, fit-out, soft costs (Design Fee, Project Management, Contingency), and commissioning. It scales primarily with IT Load, Redundancy, Cooling Type, and location (Region, City / Market), then gets adjusted by escalation and market factors. Total CAPEX divided by IT capacity gives Cost per kW, the industry benchmark; it also anchors every downstream financial metric — Equity IRR, DSCR, NPV, and Payback Period all start from this number.","f":"Total CAPEX = sum(construction + equipment + fit-out + soft costs) x location x escalation x market factors","u":"USD","rel":["cost-per-kw","it-load","capex","equity-irr","npv"],"aliases":["Total CAPEX","total CAPEX"]},"total-harmonic-distortion":{"t":"THD (Total Harmonic Distortion) ((Total Harmonic Distortion))","d":"A measure of waveform quality expressed as a percentage of the fundamental frequency. IEEE 519 limits voltage THD to 5% and individual harmonic current limits based on system impedance. High THD causes transformer overheating, capacitor failure, and circuit breaker nuisance tripping.","link":"glossary.html#term-total-harmonic-distortion","aliases":["(Total Harmonic Distortion)","THD (Total Harmonic Distortion)"]},"transfer-switch":{"t":"Transfer Switch","d":"A device that switches electrical load between two power sources. Automatic Transfer Switches (ATS) detect utility failure and transfer to generators. Static Transfer Switches (STS) provide sub-cycle (4ms) transfer between two utility feeds using solid-state electronics.","link":"glossary.html#term-transfer-switch","aliases":["Transfer Switch"]},"transformer":{"t":"Transformer","d":"An electromagnetic device that changes voltage levels between circuits. Data centers use step-down transformers to convert utility high voltage (11-132 kV) to usable levels (400V/480V). K-rated transformers handle harmonic-rich loads from IT equipment. Dry-type transformers are preferred indoors for fire safety.","link":"glossary.html#term-transformer","aliases":["Transformer"]},"transformer-lead":{"t":"Transformer Lead Time","d":"The procurement wait for large power transformers, currently one of the industry's worst supply-chain bottlenecks. Standard delivery is 18–24 months; extended market conditions push 24–36 months and add ~15% cost; emergency expedited procurement adds ~30%. Because the transformer often sits on the project critical path, lead time interacts with Year Escalation (longer builds absorb more inflation) and can dominate the Capacity Plan timeline.","table":[["Scenario","Impact"],["Standard","18-24 mo"],["Extended","24-36 mo, +15%"],["Emergency","expedited, +30%"]],"rel":["front-of-meter","substation-type","year-escalation","tab-capacity"],"aliases":["Transformer Lead Time","transformer lead time"]},"transformer-type":{"t":"MV/LV Transformer Type","d":"The medium-voltage to low-voltage step-down transformer construction. Oil-filled outdoor units are ~10% cheaper but require oil containment bunds and fire separation distances; dry-type is the standard indoor choice; cast-resin is the premium indoor option (+12%) with the lowest fire risk and best tolerance of humid or dusty environments. Distinct from the large grid transformers counted under Front-of-Meter.","table":[["Type","Cost Impact"],["Oil-Filled (outdoor)","-10% (cheapest, needs bund)"],["Dry-Type","Baseline (indoor standard)"],["Cast Resin","+12% (premium, low fire risk)"]],"rel":["front-of-meter","power-distribution"],"aliases":["Transformer Type","MV/LV Transformer","Dry-Type","Cast Resin"]},"trim-chiller":{"t":"Trim Chiller (Hybrid Backup)","d":"A conventional chiller plant sized at a fraction of total load (design basis 35% capacity) that runs only during warm-water events, peak excursions, or seawater-system maintenance — roughly 300 hours per year in the reference design, at ~$260k per MWth installed. It converts Deep Sea Water Cooling from a single-point-of-failure bet into an N+1 hybrid: the ocean carries the base load, the trim plant guarantees the SLA. Because it runs so few hours, its Refrigerant choice (typically ultra-low-GWP R-1234ze) has minimal Scope-1 impact.","u":"% of cooling load","rel":["deep-sea-water-cooling","n-plus-1-redundancy","refrigerant","r1234ze"],"aliases":["Trim Chiller Capacity (%)","Trim Chiller","trim chiller"]},"trip":{"t":"Trip (Circuit Breaker Trip) ((Circuit Breaker Trip))","d":"The automatic opening of a circuit breaker due to overcurrent, short circuit, or ground fault. Nuisance trips (false triggers) in data centers can cause partial outages. Selective coordination ensures only the nearest upstream breaker trips, isolating the fault without cascading failures.","link":"glossary.html#term-trip","aliases":["(Circuit Breaker Trip)","Trip (Circuit Breaker Trip)"]},"two-phase-immersion-cooling":{"t":"Two-Phase Immersion Cooling","d":"A cooling architecture in which servers are submerged in a low-boiling-point dielectric fluid (typically 34-49°C). The fluid boils at the chip surface and condenses on a chilled coil, transferring heat through phase change. Two-phase enables rack densities exceeding 200 kW with very low PUE. Currently dependent on PFAS fluids (Novec 7000, Fluorinert, Galden HT) — driving regulatory scrutiny and supply-chain concerns following 3M's 2025 PFAS exit.","link":"glossary.html#term-two-phase-immersion-cooling","aliases":["Two-Phase Immersion Cooling"]},"u-space":{"t":"U-Space","d":"A unit of vertical space in a rack equal to 1.75 inches (44.45mm). Standard racks provide 42U or 48U of usable space. Efficient U-space planning maximizes equipment density while maintaining adequate airflow gaps and cable management clearance between devices.","link":"glossary.html#term-u-space","aliases":["U-Space"]},"ul-9540a":{"t":"UL 9540A","d":"The UL 9540A:2024 Test Method for Evaluating Thermal Runaway Fire Propagation in Battery Energy Storage Systems &mdash; measures a Li-ion cell/module/unit's off-gas composition, volume and flame behaviour. Its results drive the gas-detection thresholds and unit spacing that NFPA 855 requires for stationary battery installations.","link":"glossary.html#term-ul-9540a","aliases":["UL 9540A"]},"under-floor-plenum":{"t":"Under-floor Plenum","d":"The space between the structural slab and the raised access floor used as a pressurized air distribution pathway. Cold air from CRAC/CRAH units fills the plenum and flows up through perforated tiles into the cold aisle. Minimum recommended depth is 600mm for effective air distribution.","link":"glossary.html#term-under-floor-plenum","aliases":["Under-floor Plenum"]},"ups":{"t":"UPS (Uninterruptible Power Supply) ((Uninterruptible Power Supply))","d":"A device providing emergency power when the mains input fails, using stored energy (batteries, flywheels, or supercapacitors) to bridge the gap until generators start. UPS topologies include standby, line-interactive, and double-conversion (online). Modern modular UPS systems offer 97%+ efficiency and N+1 scalability.","link":"glossary.html#term-ups","aliases":["(Uninterruptible Power Supply)","UPS (Uninterruptible Power Supply)"]},"ups-paralleling":{"t":"UPS Paralleling","d":"Connecting multiple UPS modules to share the load and provide redundancy. Parallel UPS systems can operate in capacity mode (all modules share load) or redundancy mode (N+1, where one module is standby). Modular UPS architectures allow hot-swappable modules for maintenance without downtime.","link":"glossary.html#term-ups-paralleling","aliases":["UPS Paralleling"]},"ups-type":{"t":"UPS Type (Uninterruptible Power Supply)","d":"The battery/rotary system that bridges the 10–15 second gap between a utility outage and generator pickup — the heartbeat of ride-through power. Standalone units suit small fixed capacity; modular UPS scales in blocks and can carry N+1 within the frame; distributed/rack UPS fits edge deployments; rotary (diesel-coupled flywheel) UPS is the ultra-reliable option that merges UPS and generator. The choice interacts with Redundancy topology (N+1 vs 2N paths) and on-site BESS, which can double as UPS reserve.","table":[["Type","Best For"],["Standalone","Small, fixed capacity"],["Modular","Scalable, N+1 within"],["Distributed/Rack","Edge, distributed"],["Rotary UPS","Ultra-reliable, diesel"]],"rel":["generator-type","redundancy","onsite-renewable"],"aliases":["UPS Type","UPS","Uninterruptible Power Supply"]},"uptime-institute":{"t":"Uptime Institute","d":"An independent advisory organization that created the Tier Classification system for data center reliability. Uptime Institute certifies data centers at Tier I through Tier IV levels through three stages: Tier Certification of Design Documents (TCDD), Constructed Facility (TCCF), and Operational Sustainability (TCOS).","link":"glossary.html#term-uptime-institute","aliases":["Uptime Institute"]},"uptime-sla":{"t":"Expected Uptime (Availability SLA)","d":"The percentage of the year the facility is expected to be operational, set by the Redundancy level and Tier Classification. 99.982% (Tier III) allows about 1.6 hours of downtime per year; 99.995% (Tier IV) about 26 minutes; adding another nine multiplies infrastructure cost. Contractual SLA breaches typically trigger service credits, so the gap between designed availability and sold SLA is a real risk position quantified in the Risk Analysis module.","u":"%","table":[["Availability","Downtime/yr"],["99.671%","~28.8 hours"],["99.982%","~1.6 hours"],["99.995%","~26 minutes"],["99.9995%","~2.6 minutes"]],"rel":["tier-class","redundancy","tab-risk"],"aliases":["Expected Uptime","Uptime SLA","availability SLA"]},"utility-rate":{"t":"Utility Rate of Return","d":"The regulated return (typically 7–12%, commonly ~9%) a utility earns on Front-of-Meter infrastructure it builds on the operator's behalf, passed through in the interconnection agreement or tariff. A higher allowed return raises the effective cost of grid-supplied capacity and can tip the economics toward On-Site Renewables or a dedicated Substation owned outright.","u":"%","rel":["front-of-meter","substation-type","onsite-renewable"],"aliases":["Utility Rate of Return","utility rate of return"]},"utility-substation":{"t":"Utility Substation","d":"An electrical facility that transforms high-voltage utility power (66-400 kV) to medium voltage (11-33 kV) for data center distribution. Large data centers may negotiate dedicated substations with the utility to ensure adequate power capacity and reliability.","link":"glossary.html#term-utility-substation","aliases":["Utility Substation"]},"utilization":{"t":"Utilization","d":"The percentage of available capacity actively in use. Power utilization = actual IT load / provisioned capacity. Rack utilization = occupied U-spaces / total U-spaces. Optimal utilization balances efficiency (higher is better) against growth headroom (need buffer). Industry average IT power utilization is 40-60%.","link":"glossary.html#term-utilization","aliases":["Utilization"]},"utp":{"t":"UTP (Unshielded Twisted Pair) ((Unshielded Twisted Pair))","d":"Copper cable consisting of twisted wire pairs without metallic shielding. Cat6A UTP supports 10 Gbps at distances up to 100m and is the minimum recommended grade for new data center installations. Being increasingly supplemented by fiber for inter-rack connectivity.","link":"glossary.html#term-utp","aliases":["(Unshielded Twisted Pair)","UTP (Unshielded Twisted Pair)"]},"vapor-seal":{"t":"Vapor Seal (Vapor Barrier) ((Vapor Barrier))","d":"A material applied to data center walls, floors, and ceilings to prevent moisture migration into the controlled environment. Vapor seals are critical in humid climates to prevent condensation on cold surfaces (chilled water pipes, cold aisle floors) that could damage equipment or create safety hazards.","link":"glossary.html#term-vapor-seal","aliases":["(Vapor Barrier)","Vapor Seal (Vapor Barrier)"]},"ventilation":{"t":"Ventilation","d":"The supply of outdoor air to a data center for pressurization, combustion (generators), or air-side economizer cooling. Unlike office buildings, data centers require minimal ventilation for occupied spaces since most areas are unmanned. ASHRAE 62.1 defines minimum ventilation rates for occupied zones.","link":"glossary.html#term-ventilation","aliases":["Ventilation"]},"vesda":{"t":"VESDA (Very Early Smoke Detection Apparatus) ((Very Early Smoke Detection Apparatus))","d":"An aspirating smoke detection system that actively draws air samples through a pipe network to a central laser-based detector. VESDA detects smoke at the earliest stage (before visible smoke), providing 10-60 minutes of early warning before traditional spot detectors activate. Standard for data center fire protection.","link":"glossary.html#term-vesda","aliases":["(Very Early Smoke Detection Apparatus)","VESDA (Very Early Smoke Detection Apparatus)"]},"vfd":{"t":"VFD (Variable Frequency Drive) ((Variable Frequency Drive))","d":"An electronic controller that adjusts the speed of AC motors by varying the frequency and voltage of the power supply. VFDs on chiller compressors, pumps, and fans enable demand-based operation, reducing energy consumption by 20-50% compared to fixed-speed motors. Power savings follow the cubic affinity law.","link":"glossary.html#term-vfd","aliases":["(Variable Frequency Drive)","VFD (Variable Frequency Drive)"]},"virtual-machine":{"t":"Virtual Machine (VM) ((VM))","d":"A software-based emulation of a physical computer that runs an operating system and applications on shared physical hardware. Virtualization improves server utilization from 10-15% (bare metal) to 60-80%, reducing the total number of physical servers needed in a data center.","link":"glossary.html#term-virtual-machine","aliases":["(VM)","Virtual Machine (VM)"]},"virtualization":{"t":"Virtualization","d":"Technology that creates multiple virtual instances (VMs, containers) on a single physical server, improving hardware utilization from 10-15% to 60-80%. Virtualization reduces the number of physical servers needed, lowering power consumption, cooling requirements, and floor space.","link":"glossary.html#term-virtualization","aliases":["Virtualization"]},"voltage":{"t":"Voltage (V) ((V))","d":"The electrical potential difference that drives current through a circuit. Common data center voltage levels: 11-132 kV (utility intake), 400/480V (UPS and PDU input), 230/208V (rack power), and 12V/48V (server internal). Higher distribution voltages reduce cable size and losses.","link":"glossary.html#term-voltage","aliases":["(V)","Voltage (V)"]},"vrla":{"t":"VRLA (Valve-Regulated Lead-Acid) ((Valve-Regulated Lead-Acid))","d":"The most common battery type in traditional UPS systems. VRLA batteries are sealed, maintenance-free, and available in AGM (Absorbed Glass Mat) or gel variants. Typical lifespan is 3-5 years (design life 5-10 years). Temperature sensitivity requires battery rooms maintained at 20-25 C.","link":"glossary.html#term-vrla","aliases":["(Valve-Regulated Lead-Acid)","VRLA (Valve-Regulated Lead-Acid)"]},"wacc":{"t":"WACC (Weighted Average Cost of Capital)","d":"The blended required return across the capital stack: cost of equity weighted by the equity share plus after-tax cost of debt weighted by the Debt Ratio. It is the standard discount rate for NPV and the natural hurdle for Project IRR; data center WACCs commonly land in the 7–10% range depending on leverage, rates, and asset risk. Because debt is cheaper than equity (and interest is tax-deductible), leverage lowers WACC — up to the point where financial risk starts raising both components.","f":"WACC = E/(D+E) x Re + D/(D+E) x Rd x (1 - tax)","u":"%","rel":["npv","project-irr","debt-ratio-leverage","cap-rate"],"aliases":["WACC","Weighted Average Cost of Capital","discount rate"]},"walk-in":{"t":"Walk-In Test","d":"A post-installation inspection where the commissioning team physically walks through the data center to verify equipment placement, labeling, cable routing, and safety compliance before energization. Walk-in tests catch construction defects that may not appear in drawing reviews.","link":"glossary.html#term-walk-in","aliases":["Walk-In Test"]},"waste-heat-recovery":{"t":"Waste Heat Recovery","d":"Capturing and reusing heat generated by data center operations for district heating, industrial processes, or building HVAC. Nordic data centers increasingly sell waste heat to municipal heating networks. Waste heat recovery can offset 20-40% of a community's heating energy demand.","link":"glossary.html#term-waste-heat-recovery","aliases":["Waste Heat Recovery"]},"water-cooling":{"t":"Water Cooling","d":"Using chilled water to remove heat from a data center via air handlers (CRAH), in-row coolers, rear-door heat exchangers, or direct-to-chip cold plates. Water-cooled systems are more energy-efficient than air-cooled systems for large deployments but require water treatment and leak detection infrastructure.","link":"glossary.html#term-water-cooling","aliases":["Water Cooling"]},"watt":{"t":"Watt (W) ((W))","d":"The SI unit of power equal to one joule per second. Data center power is commonly expressed in kilowatts (kW = 1,000 W) and megawatts (MW = 1,000,000 W). A single server typically consumes 300-800W; a GPU server can consume 5,000-10,000W.","link":"glossary.html#term-watt","aliases":["(W)","Watt (W)"]},"wet-sprinkler":{"t":"Wet Sprinkler","d":"A fire sprinkler system with water-filled pipes at all times. Individual sprinkler heads activate when heat melts the fusible link. Not recommended for primary data hall protection due to accidental discharge risk. Used in support areas (offices, warehouses, corridors) where water damage risk is acceptable.","link":"glossary.html#term-wet-sprinkler","aliases":["Wet Sprinkler"]},"whip":{"t":"Whip (Power Whip) ((Power Whip))","d":"A short pre-terminated power cable connecting a PDU or busway tap-off to a rack PDU. Whips typically range from 3-10 meters and use industrial connectors for quick deployment. Standardized whip lengths simplify inventory management and reduce installation time during rack deployments.","link":"glossary.html#term-whip","aliases":["(Power Whip)","Whip (Power Whip)"]},"white-space":{"t":"White Space","d":"The floor area that holds IT racks — the revenue-generating footprint, as opposed to Support Space (electrical rooms, cooling plant, corridors, loading). White space requirement falls as Rack Density rises: an AI hall at 50–100 kW/rack needs a fraction of the floor of a 5 kW/rack enterprise hall for the same megawatts. Colocation Pricing and facility economics are quoted per kW far more than per square meter precisely because power, not floor, is the scarce resource.","u":"m²","rel":["support-space","rack-density","rack-density-kw-m2","colocation-pricing"],"aliases":["White Space","white space"]},"workload":{"t":"Workload","d":"A specific application, service, or set of computations running on data center infrastructure. Workload types include web serving, database, AI training, video encoding, and batch processing. Each has distinct power, cooling, latency, and storage requirements that influence infrastructure design.","link":"glossary.html#term-workload","aliases":["Workload"]},"wue":{"t":"WUE (Water Usage Effectiveness)","d":"Liters of water consumed per kWh of IT energy — the water twin of PUE, driven almost entirely by evaporative cooling (cooling towers, adiabatic pre-coolers). Evaporative plants commonly run 1–2 L/kWh, which for a 10 MW site is tens of millions of liters a year; closed-loop, air-cooled, and Deep Sea Water Cooling designs achieve WUE ≈ 0 because nothing evaporates. Increasingly a permitting and ESG gate in water-stressed regions, reported alongside PUE and CUE.","f":"WUE = Annual Water Consumption (L) / IT Energy (kWh)","u":"L/kWh","rel":["pue","cue","deep-sea-water-cooling","green-certification"],"aliases":["WUE","Water Usage Effectiveness"]},"x-connect":{"t":"X-Connect (Cross-Connect) ((Cross-Connect))","d":"A direct physical cable connection between two parties within a colocation facility. X-connects bypass the public internet, providing lower latency, higher security, and dedicated bandwidth. Common types: single-mode fiber (SMF), multi-mode fiber (MMF), Cat6A copper, and coaxial.","link":"glossary.html#term-x-connect","aliases":["(Cross-Connect)","X-Connect (Cross-Connect)"]},"xenon":{"t":"Xenon Lamp Testing","d":"A lighting emergency testing method where xenon strobes are used to verify fire alarm notification appliance circuit (NAC) functionality and visual alerting in high-noise data center environments. Regular testing ensures alarm systems meet NFPA 72 audibility and visibility requirements.","link":"glossary.html#term-xenon","aliases":["Xenon Lamp Testing"]},"year-escalation":{"t":"Year Escalation (Construction Cost Inflation)","d":"Multi-year construction cost inflation applied to future project start dates. Data center construction ran ~7% CAGR from 2020–2025 (Turner & Townsend) driven by equipment lead times and labor scarcity, and is projected to decelerate as supply chains normalize: 2026 +6.0%, 2027 cumulative 1.115x, through 2030 at 1.250x of the 2025 baseline. Escalation compounds with build duration, so slower Building Type or Delivery Method choices absorb more of it.","table":[["Year","Multiplier"],["2025 (baseline)","1.000x"],["2026","1.060x (+6.0%)"],["2028","1.165x (+4.5%)"],["2030","1.250x (+3.3%)"]],"s":"JLL 2026 Outlook, Turner & Townsend DCCI 2025, Avid Solutions 2026-2030 projections","rel":["escalation","total-capex","market-condition"],"aliases":["Projection Year","Year Escalation","cost escalation"]},"year-one-pue":{"t":"Year-One PUE","d":"The PUE measured during the first full year of data center operation, typically higher than design PUE due to low IT utilization against fixed overhead loads. Year-one PUE may be 1.8-2.0+ for facilities at 20-30% IT load, improving as the facility fills to design capacity.","link":"glossary.html#term-year-one-pue","aliases":["Year-One PUE"]},"yield":{"t":"Yield (Power Yield) ((Power Yield))","d":"The percentage of contracted or provisioned power capacity actually delivered to IT equipment after distribution losses. A data center with 10 MW provisioned and 9.2 MW delivered to racks has a 92% power yield. Losses occur in transformers, UPS systems, and cabling.","link":"glossary.html#term-yield","aliases":["(Power Yield)","Yield (Power Yield)"]},"zero-downtime":{"t":"Zero Downtime","d":"An operational goal where IT services remain continuously available with no interruption, even during planned maintenance or component failures. Achieved through 2N redundancy, concurrent maintenance capability, automated failover, and rigorous change management procedures.","link":"glossary.html#term-zero-downtime","aliases":["Zero Downtime"]},"zinc-whisker":{"t":"Zinc Whisker","d":"Microscopic conductive filaments that grow from zinc-plated surfaces (raised floor pedestals, cable trays) over time. When disturbed, zinc whiskers become airborne and can cause short circuits on server motherboards. A hidden reliability threat requiring periodic inspection and mitigation in older data centers.","link":"glossary.html#term-zinc-whisker","aliases":["Zinc Whisker"]},"zone":{"t":"Zone (Fire Zone / Power Zone) ((Fire Zone / Power Zone))","d":"A physically or logically separated area within a data center. Fire zones contain fire and smoke within defined boundaries. Power zones define electrical distribution territories. Cooling zones group racks with similar density. Zone-based design enables independent maintenance and fault isolation.","link":"glossary.html#term-zone","aliases":["(Fire Zone / Power Zone)","Zone (Fire Zone / Power Zone)"]},"zoning":{"t":"Zoning (Network Zoning) ((Network Zoning))","d":"Segmenting a data center network into isolated zones (DMZ, production, management, storage) using firewalls, VLANs, or physical separation. Zoning limits the blast radius of security breaches and enforces access control policies between different trust levels within the facility.","link":"glossary.html#term-zoning","aliases":["(Network Zoning)","Zoning (Network Zoning)"]}}};
